-- ============================================================================
-- v1374: Seed / sample data — Information Technology › Architecture registers
-- ============================================================================
-- Owner request 2026-11-09: the Architecture menus showed empty lists. Companion seed (rule 18.2)
-- for project SEED334-PRJ-08 (fictional Northbridge Bank technology programme; vendor-neutral,
-- rule 26). 10 records on each register:
--   Enterprise Architecture  (…-4000-a01b-…)   Solution Architecture   (…-4000-a01c-…)
--   Application Architecture (…-4000-a01d-…)   Data Architecture       (…-4000-a01e-…)
--   Integration Architecture (…-4000-a01f-…)   Security Architecture   (…-4000-a020-…)
--   Architecture Decisions   (…-4000-a021-…)   Architecture Reviews    (…-4000-a022-…)
-- The six architecture documents follow the ten delivery slices of the v1355 Delivery Overview
-- (same owners, scope, risks and team). Documents are Draft; the closed Regulatory reporting
-- slice and one replaced decision are Superseded (In Review / Approved are set by sign-off only).
-- Architecture Reviews has no form fields yet, so its records carry title, description, status.
-- Splittable lines use "A – B – C" so they read into columns if those fields become tables.
-- display_id is blank so Admin ID Generation assigns it (rule 16.2).
-- Prerequisites: v949, v1321, v1324, v1355. Idempotent (ON CONFLICT DO NOTHING).
-- ============================================================================

WITH proj AS (
  SELECT id, account_id FROM public.projects WHERE project_code = 'SEED334-PRJ-08' LIMIT 1
)
INSERT INTO public.local_register_records
  (id, register_id, display_id, title, description, status, field_values, account_id, project_id, record_project_id)
SELECT v.id::uuid, v.register_id::uuid, '', v.title, v.description, v.status, v.field_values::jsonb,
       p.account_id, p.id, p.id
FROM (VALUES
  ('00000000-0000-4000-a01b-000000000001', '00000000-0000-4000-9003-000000000005', 'Customer and digital channels enterprise architecture', 'Enterprise Architecture for customer and digital channels on the Northbridge Bank technology programme. Owner: Amina Diallo.', 'draft', $j${"document_reference":"NRB-EA-01","document_version":"0.9","document_owner":"Amina Diallo","next_review_date":"2026-11-16","purpose":"Describes the enterprise architecture for customer and digital channels on the Northbridge Bank technology programme. Delivery of customer master data and the internet, mobile and branch channels for the Northbridge Bank technology programme.","objectives":"Every active customer has one surviving customer number\nAddress completeness at or above 85%\nInternet and mobile users can sign in on day one\nDuplicate customers reduced below 1%\nMandate images linked to the surviving customer\nBranch search returns the customer in under 3 seconds","scope":"Retail and SME customer master\nCorporate customer master from the second legacy instance\nInternet banking registration\nMobile banking registration\nBranch teller customer search\nContact centre customer view","out_of_scope":"Card plastic personalisation\nMarketing campaign tool\nLoyalty scheme\nInsurance product origination\nWealth advisory portal","assumptions":"Both legacy instances are profiled before Mock 2\nThe surviving record is the one with the most complete KYC data\nCustomers accept a new customer number where numbers clash\nBranch staff are trained before the dress rehearsal\nStatement templates are approved by the business","constraints":"Customer numbers must be unique across both legacy instances\nKYC fields are mandatory before a customer can be loaded\nAddress completeness target is 85%\nImages must be linked before the channel is opened\nThe load window is the weekend of 10–12 April 2027","risks_mitigations":"Account takeover through weak registration checks – Two-factor registration and device binding\nDuplicate customer merged onto the wrong survivor – Survivor rule signed by the business data owner and sample-checked\nMandate images exposed through a direct link – Images served only through the authenticated retrieval API\nCredential stuffing on internet banking sign-in – Rate limits and lock-out on sign-in\nPersonal data copied into test environments – Masked data only in lower environments","roles_and_responsibilities":"Delivery lead – Owns delivery and the plan – Amina Diallo\nBusiness owner – Accepts the scope and the result – Nomvula Khumalo\nExecutive sponsor – Funds the work and decides escalations – Grace Moyo\nTechnical lead – Owns the technical design – Ravi Pillai\nData analyst – Profiles and maps the data – Priya Naidoo\nChannel analyst – Designs channel journeys and entitlements – Brian Otieno","glossary":"Target core\tThe new core banking platform that replaces both legacy cores\nMock\tA full rehearsal load of migrated data into the target core\nHypercare\tThe four weeks of extra support after go-live\nCapability\tSomething the bank does, independent of the system that does it\nTransition architecture\tAn interim state between the baseline and the target","appendices":"Customer and digital channels delivery overview\tDelivery Overview – Customer and digital channels\nCustomer and digital channels roadmap\tNRB-RM-01\nProgramme architecture principles\tNRB-EA-PR-01","version_history":"0.1\t2026-04-27\tAmina Diallo\tFirst draft\n0.5\t2026-07-05\tRavi Pillai\tComments from Channels steering group\n0.9\t2026-09-03\tAmina Diallo\tReady for review","related_documents":"NRB-RM-01 – Customer and digital channels roadmap\nDelivery Overview – Customer and digital channels\nNRB-ADR – Architecture decision log","architecture_owner":"Ravi Pillai","business_drivers":"One customer number for service and channels\nFewer duplicate records for staff to reconcile\nCustomers keep digital access on day one\nFaster branch and contact centre search\nCleaner KYC for ongoing due diligence","strategic_goals":"Single customer view\nCustomer deduplication\nInternet banking sign-in\nMobile banking sign-in\nBranch customer search","stakeholder_concerns":"Address completeness stays under 85%\nDuplicate customers are merged onto the wrong survivor\nImage volume slips the static window\nCustomers cannot sign in on day one\nOld customer numbers are dropped","architecture_principles":"One customer, one number, across every channel\nReuse the target core before building\nData is cleansed at source, not in the load\nEvery interface has a named owner and a contract\nSecurity controls are designed in, not added at the end","baseline_architecture":"Today customer and digital channels runs on two legacy core instances with point-to-point links to channels and finance. Address completeness measured at 82% after Mock 1","pain_points":"Address completeness measured at 82% after Mock 1\n23,400 customers exist in both legacy instances\n4,150 customers have more than one number in a single instance\nImage storage location is not decided\nKYC extract access is requested, not yet granted","target_architecture":"Customer master and channel access runs on the target core, reached through the API gateway and the integration platform, with one master record per entity and monitoring on every interface.","capability_map":"Single customer view\nCustomer deduplication\nInternet banking sign-in\nMobile banking sign-in\nBranch customer search\nContact centre desktop\nStatement preferences\nAlert preferences","gaps":"Confirm the survivor rule for duplicate customers\nDecide image storage: file store or database\nApprove the two outstanding statement templates\nName a champion in every branch\nConfirm KYC extract access by 30 November 2026","transition_architectures":"Mock 1: both legacy cores live, target core loaded for test only\nMock 3: financial data reconciled in the target core\nGo-live weekend: channels switched to the target core\nHypercare: legacy cores read-only for enquiry","roadmap_items":"Retail and SME customer master\nCorporate customer master from the second legacy instance\nInternet banking registration\nMobile banking registration\nBranch teller customer search","technology_standards":"Target core banking platform – customer module\nAPI gateway\nIdentity provider for customer sign-in\nRelational database for the customer master\nObject store for mandate images","governance_process":"Changes are raised at the Channels steering group with a decision record. Delivery lead raises an amber item at the weekly channels steering group. A red item, or any slip to the April 2027 go-live, goes to the executive sponsor the same day.","compliance_requirements":"Personal data stays in the agreed region\nRecords kept for seven years\nAccess recertified before user load\nChange records for every production release"}$j$),
  ('00000000-0000-4000-a01b-000000000002', '00000000-0000-4000-9003-000000000005', 'Payments and transfers enterprise architecture', 'Enterprise Architecture for payments and transfers on the Northbridge Bank technology programme. Owner: Ahmed Hassan.', 'draft', $j${"document_reference":"NRB-EA-02","document_version":"0.9","document_owner":"Ahmed Hassan","next_review_date":"2026-11-18","purpose":"Describes the enterprise architecture for payments and transfers on the Northbridge Bank technology programme. Delivery of domestic payments, standing orders and internal transfers onto the target platform.","objectives":"Every active standing order is recreated before go-live\nSettlement totals agree to the cent\nReturned payments land on the repair queue\nChannel limits match the signed matrix\nNo duplicate payment on the cutover weekend\nCut-off calendar loaded for the next 18 months","scope":"Domestic credit transfers\nInternal account transfers\nStanding orders\nFuture-dated payments\nPayment limits by channel\nSettlement timetable","out_of_scope":"Card authorisation\nATM cash\nCheque clearing replacement\nCross-border correspondent banking rebuild\nCash-in-transit","assumptions":"The scheme timetable does not change before go-live\nStanding orders are recreated, not replayed from history\nBoth legacy instances use the same value-date rule\nPayment limits are signed by the business before UAT\nThe repair queue is staffed for hypercare","constraints":"Scheme cut-off cannot move\nSettlement must balance on the night\nStanding orders with an end date in the past are excluded\nDual control stays on the repair queue\nPayment files are not accepted during the freeze","risks_mitigations":"Duplicate payment on the cutover weekend – Idempotent posting keyed on the payment reference\nChannel limits looser than the signed matrix – Load limits from the signed matrix and test every band\nScheme certificate expiry – Certificate inventory with 60-day expiry alerts\nTampered payment file in transit – Signed and encrypted payment files\nRepair actions without dual control – Dual control enforced on every repair action","roles_and_responsibilities":"Delivery lead – Owns delivery and the plan – Ahmed Hassan\nBusiness owner – Accepts the scope and the result – Catherine Mwangi\nExecutive sponsor – Funds the work and decides escalations – Daniel Okafor\nTechnical lead – Owns the technical design – Brian Otieno\nSettlement analyst – Designs settlement and reconciliation – Olivia Banda\nTest lead – Owns test entry, exit and evidence – Priya Naidoo","glossary":"Target core\tThe new core banking platform that replaces both legacy cores\nMock\tA full rehearsal load of migrated data into the target core\nHypercare\tThe four weeks of extra support after go-live\nCapability\tSomething the bank does, independent of the system that does it\nTransition architecture\tAn interim state between the baseline and the target","appendices":"Payments and transfers delivery overview\tDelivery Overview – Payments and transfers\nPayments and transfers roadmap\tNRB-RM-02\nProgramme architecture principles\tNRB-EA-PR-01","version_history":"0.1\t2026-05-25\tAhmed Hassan\tFirst draft\n0.5\t2026-08-02\tBrian Otieno\tComments from Payments working group\n0.9\t2026-10-04\tAhmed Hassan\tReady for review","related_documents":"NRB-RM-02 – Payments and transfers roadmap\nDelivery Overview – Payments and transfers\nNRB-ADR – Architecture decision log","architecture_owner":"Brian Otieno","business_drivers":"One payment engine instead of two cores\nStanding orders survive the cutover\nFaster repair of returned payments\nSettlement that operations can explain\nClearer channel limits","strategic_goals":"Domestic credit transfer\nInternal transfer\nStanding order booking\nFuture-dated payment\nPayment limits","stakeholder_concerns":"Standing orders are duplicated across the two instances\nScheme certificate expires before dress rehearsal\nSettlement does not balance on the night\nRepair queue is understaffed on day one\nFuture-dated payments are lost in the freeze","architecture_principles":"One customer, one number, across every channel\nReuse the target core before building\nData is cleansed at source, not in the load\nEvery interface has a named owner and a contract\nSecurity controls are designed in, not added at the end","baseline_architecture":"Today payments and transfers runs on two legacy core instances with point-to-point links to channels and finance. 1,180 standing orders exist in both instances","pain_points":"1,180 standing orders exist in both instances\nScheme certificate renewal is with the gateway team\nTwo limit bands are still in draft\nRepair training is booked but not delivered\nNotification suppression failed once in SIT","target_architecture":"Domestic payments and standing orders runs on the target core, reached through the API gateway and the integration platform, with one master record per entity and monitoring on every interface.","capability_map":"Domestic credit transfer\nInternal transfer\nStanding order booking\nFuture-dated payment\nPayment limits\nSettlement\nReturns and unpaids\nRepair queue","gaps":"Confirm standing orders are recreated rather than replayed\nExtend the cut-off calendar through October 2028\nApprove UAT funding for payment accounts\nName the two night-shift hypercare leads\nSign the remaining limit bands","transition_architectures":"Mock 1: both legacy cores live, target core loaded for test only\nMock 3: financial data reconciled in the target core\nGo-live weekend: channels switched to the target core\nHypercare: legacy cores read-only for enquiry","roadmap_items":"Domestic credit transfers\nInternal account transfers\nStanding orders\nFuture-dated payments\nPayment limits by channel","technology_standards":"Target core banking platform – payments module\nEvent broker\nScheme gateway\nRelational database for payment state\nIntegration platform","governance_process":"Changes are raised at the Payments working group with a decision record. The payments working group clears ambers weekly. A failed settlement test or a scheme-window slip is escalated to the executive sponsor before the next scheme cycle.","compliance_requirements":"Personal data stays in the agreed region\nRecords kept for seven years\nAccess recertified before user load\nChange records for every production release"}$j$),
  ('00000000-0000-4000-a01b-000000000003', '00000000-0000-4000-9003-000000000005', 'Lending, limits and collateral enterprise architecture', 'Enterprise Architecture for lending, limits and collateral on the Northbridge Bank technology programme. Owner: Joy Akinyi.', 'draft', $j${"document_reference":"NRB-EA-03","document_version":"0.9","document_owner":"Joy Akinyi","next_review_date":"2026-11-11","purpose":"Describes the enterprise architecture for lending, limits and collateral on the Northbridge Bank technology programme. Delivery of loans, limits and collateral, including overdue bills and the expired-limit rule.","objectives":"Every live loan has an arrangement, a balance and a schedule\nAgeing continues from the legacy past-due date\nExpired limits follow the signed rule\nCollateral is linked before the loan is loaded\nOne repayment account per customer per currency\nTake-over accounts return to zero","scope":"Retail loan arrangements\nCorporate loan arrangements\nOverdue and due bills\nAccrued interest on loans\nLimit records\nExpired limits still linked to a contract","out_of_scope":"New scorecard build\nDebt collection agency files\nSecuritisation\nSyndicated loan agency\nTrade finance instruments","assumptions":"Schedules are regenerated from the migrated frequency\nThe expired-limit rule is expiry plus one day, with the original date kept\nOne liquidation account is allowed per customer per currency\nCollateral rights load before collateral items\nPast-due date becomes the bill date","constraints":"A loan cannot load before its customer and account\nCollateral cannot load before its right\nAgeing must not reset to zero\nExpired limits cannot be dropped while a contract is live\nTake-over accounts must be zero after reconciliation","risks_mitigations":"Expired limit left securing a live contract – Expired-limit rule signed and every case on a credit review queue\nCollateral loaded before its right and rejected – Load rights before items, rehearsed in Mock 2\nAccrual counted twice after migration – Accrual value date set to the migration date\nUnauthorised limit override – Limit overrides need a second approver\nCredit data exposed to non-credit staff – Credit screens limited to credit roles","roles_and_responsibilities":"Delivery lead – Owns delivery and the plan – Joy Akinyi\nBusiness owner – Accepts the scope and the result – Daniel Okafor\nExecutive sponsor – Funds the work and decides escalations – Grace Moyo\nTechnical lead – Owns the technical design – Priya Naidoo\nCredit analyst – Defines lending and limit rules – Ahmed Hassan\nCollateral analyst – Maps collateral rights and items – Linda Zhou","glossary":"Target core\tThe new core banking platform that replaces both legacy cores\nMock\tA full rehearsal load of migrated data into the target core\nHypercare\tThe four weeks of extra support after go-live\nCapability\tSomething the bank does, independent of the system that does it\nTransition architecture\tAn interim state between the baseline and the target","appendices":"Lending, limits and collateral delivery overview\tDelivery Overview – Lending, limits and collateral\nLending, limits and collateral roadmap\tNRB-RM-03\nProgramme architecture principles\tNRB-EA-PR-01","version_history":"0.1\t2026-06-08\tJoy Akinyi\tFirst draft\n0.5\t2026-08-16\tPriya Naidoo\tComments from Credit design authority\n0.9\t2026-10-21\tJoy Akinyi\tReady for review","related_documents":"NRB-RM-03 – Lending, limits and collateral roadmap\nDelivery Overview – Lending, limits and collateral\nNRB-ADR – Architecture decision log","architecture_owner":"Priya Naidoo","business_drivers":"One lending record instead of two cores\nAgeing that collections can trust\nLimits that still secure live contracts\nCollateral linked to the right customer\nLess manual schedule repair","strategic_goals":"Loan arrangement\nBalance and accrual capture\nBill and ageing\nLimit maintenance\nExpired-limit rule","stakeholder_concerns":"Schedule design slips Mock 2\nExpired limits are dropped and a contract is left unsecured\nAgeing resets and collections mis-prioritise\nTake-over accounts do not return to zero\nCollateral loads before its right and is rejected","architecture_principles":"One customer, one number, across every channel\nReuse the target core before building\nData is cleansed at source, not in the load\nEvery interface has a named owner and a contract\nSecurity controls are designed in, not added at the end","baseline_architecture":"Today lending, limits and collateral runs on two legacy core instances with point-to-point links to channels and finance. Schedule design is two weeks behind the plan","pain_points":"Schedule design is two weeks behind the plan\n2,180 expired limits are not yet reviewed\n8,900 loans still have more than one repayment account\nCollateral mapping is approved but the load order is not rehearsed\nTake-over account for loans is not opened","target_architecture":"Loans, limits and collateral runs on the target core, reached through the API gateway and the integration platform, with one master record per entity and monitoring on every interface.","capability_map":"Loan arrangement\nBalance and accrual capture\nBill and ageing\nLimit maintenance\nExpired-limit rule\nCollateral right\nCollateral item\nRepayment account","gaps":"Sign the expired-limit rule\nOpen the loan take-over account\nConfirm one repayment account per customer per currency\nName an owner for the remaining limit band\nMove credit training ahead of UAT","transition_architectures":"Mock 1: both legacy cores live, target core loaded for test only\nMock 3: financial data reconciled in the target core\nGo-live weekend: channels switched to the target core\nHypercare: legacy cores read-only for enquiry","roadmap_items":"Retail loan arrangements\nCorporate loan arrangements\nOverdue and due bills\nAccrued interest on loans\nLimit records","technology_standards":"Target core banking platform – lending module\nCollateral register\nRelational database for limits\nIntegration platform\nReporting database","governance_process":"Changes are raised at the Credit design authority with a decision record. A red schedule item is raised at the credit design authority and copied to the executive sponsor. A product rule that changes a customer balance is not applied until credit and finance both agree.","compliance_requirements":"Personal data stays in the agreed region\nRecords kept for seven years\nAccess recertified before user load\nChange records for every production release"}$j$),
  ('00000000-0000-4000-a01b-000000000004', '00000000-0000-4000-9003-000000000005', 'Deposits and accounts enterprise architecture', 'Enterprise Architecture for deposits and accounts on the Northbridge Bank technology programme. Owner: Catherine Mwangi.', 'draft', $j${"document_reference":"NRB-EA-04","document_version":"0.9","document_owner":"Catherine Mwangi","next_review_date":"2026-11-17","purpose":"Describes the enterprise architecture for deposits and accounts on the Northbridge Bank technology programme. Delivery of current accounts, savings and term deposits, including balances and accruals.","objectives":"Every open account has a product, a balance and an owner\nInstance 2 account numbers are kept as alternate keys\nDormant accounts over five years are closed or transferred\nMatured deposits no longer carry a balance at the freeze\nRestrictions match the legacy narrative\nStatement frequency is remapped","scope":"Current accounts\nSavings accounts\nTerm deposits\nDeposit balances and accruals\nDormant accounts over five years\nMatured deposits that still hold a balance","out_of_scope":"Safe custody\nNew savings product launch\nPrize-linked savings\nChildren account campaign\nBrokerage cash accounts","assumptions":"Three legacy current-account products become one target product\nInstance 2 numbers become 10 digits with a check digit\nDormant means no customer-initiated transaction for five years\nUnclaimed balances move under the existing regulation\nMatured deposits are paid out or rolled, not migrated as running","constraints":"No account closures in the week before go-live\nA zero-balance account marked for closure is excluded\nAlternate keys are mandatory for instance 2\nAccrual value date cannot be the original accrual date\nProduct mapping cannot change after Mock 2 without a new approval","risks_mitigations":"Matured deposit still carrying a balance at the freeze – Pay out or roll matured deposits before the freeze\nAccount numbers clashing across the two instances – 10-digit numbers with check digit and alternate keys\nRestriction narrative dropped in migration – Sample-check restriction narratives after each mock\nStatement sent to the wrong address – Address taken from the survivor customer record\nInterest accrued twice – Accrual reconciled by product after Mock 3","roles_and_responsibilities":"Delivery lead – Owns delivery and the plan – Catherine Mwangi\nBusiness owner – Accepts the scope and the result – Nomvula Khumalo\nExecutive sponsor – Funds the work and decides escalations – Olivia Banda\nTechnical lead – Owns the technical design – Brian Otieno\nProduct analyst – Maps products to the target core – Amina Diallo\nFinance partner – Agrees accounting and control totals – Daniel Okafor","glossary":"Target core\tThe new core banking platform that replaces both legacy cores\nMock\tA full rehearsal load of migrated data into the target core\nHypercare\tThe four weeks of extra support after go-live\nCapability\tSomething the bank does, independent of the system that does it\nTransition architecture\tAn interim state between the baseline and the target","appendices":"Deposits and accounts delivery overview\tDelivery Overview – Deposits and accounts\nDeposits and accounts roadmap\tNRB-RM-04\nProgramme architecture principles\tNRB-EA-PR-01","version_history":"0.1\t2026-05-11\tCatherine Mwangi\tFirst draft\n0.5\t2026-07-19\tBrian Otieno\tComments from Deposits product forum\n0.9\t2026-09-26\tCatherine Mwangi\tReady for review","related_documents":"NRB-RM-04 – Deposits and accounts roadmap\nDelivery Overview – Deposits and accounts\nNRB-ADR – Architecture decision log","architecture_owner":"Brian Otieno","business_drivers":"One account record for the customer\nDeposits that are actually running on day one\nDormant balances treated under the existing rule\nRestrictions staff can read\nStatements on the frequency the customer expects","strategic_goals":"Current account\nSavings account\nTerm deposit\nBalance and accrual capture\nRestriction","stakeholder_concerns":"Matured deposits are still open at the freeze\nDormant processing slips past November\nAccount numbers clash across the two instances\nA restriction narrative is dropped\nStatement frequency defaults incorrectly","architecture_principles":"One customer, one number, across every channel\nReuse the target core before building\nData is cleansed at source, not in the load\nEvery interface has a named owner and a contract\nSecurity controls are designed in, not added at the end","baseline_architecture":"Today deposits and accounts runs on two legacy core instances with point-to-point links to channels and finance. 1,320 matured deposits still carry a balance","pain_points":"1,320 matured deposits still carry a balance\n18,700 dormant accounts are identified and not yet processed\nRestriction narratives are mapped but not sample-checked\nStatement frequency remapping has not started\nTake-over account for deposits is open","target_architecture":"Current, savings and term deposit accounts runs on the target core, reached through the API gateway and the integration platform, with one master record per entity and monitoring on every interface.","capability_map":"Current account\nSavings account\nTerm deposit\nBalance and accrual capture\nRestriction\nStatement frequency\nAlternate account key\nDormant processing","gaps":"Confirm matured deposits are paid out or rolled, not migrated as running\nPut the dormant workshop on the November branch calendar\nRetire the two product codes that point at a retired product\nStart statement-frequency remapping\nSample-check restriction narratives","transition_architectures":"Mock 1: both legacy cores live, target core loaded for test only\nMock 3: financial data reconciled in the target core\nGo-live weekend: channels switched to the target core\nHypercare: legacy cores read-only for enquiry","roadmap_items":"Current accounts\nSavings accounts\nTerm deposits\nDeposit balances and accruals\nDormant accounts over five years","technology_standards":"Target core banking platform – accounts module\nStatement engine\nRelational database for accounts\nIntegration platform\nObject store for statements","governance_process":"Changes are raised at the Deposits product forum with a decision record. The product forum owns ambers. A balance that will not reconcile, or a product mapping change after approval, goes to the executive sponsor and finance together.","compliance_requirements":"Personal data stays in the agreed region\nRecords kept for seven years\nAccess recertified before user load\nChange records for every production release"}$j$),
  ('00000000-0000-4000-a01b-000000000005', '00000000-0000-4000-9003-000000000005', 'Data migration and quality enterprise architecture', 'Enterprise Architecture for data migration and quality on the Northbridge Bank technology programme. Owner: Priya Naidoo.', 'draft', $j${"document_reference":"NRB-EA-05","document_version":"0.9","document_owner":"Priya Naidoo","next_review_date":"2026-11-13","purpose":"Describes the enterprise architecture for data migration and quality on the Northbridge Bank technology programme. Cross-cutting delivery of extraction, cleansing, transformation, mock runs and reconciliation for the programme.","objectives":"Mock 2 static data loads inside the window\nMock 3 financial data reconciles\nDress rehearsal finishes with no severity-1 defect open\nTake-over and suspense accounts are zero\nEach population has a named data owner\nControl totals tie to the trial balance","scope":"Source profiling\nExtraction from both legacy instances\nCleansing at source\nTransformation rules\nMock runs\nDress rehearsal","out_of_scope":"Building the target platform\nCard scheme certification\nGeneral ledger replacement\nStaff identity directory rebuild\nA new data warehouse","assumptions":"Three mock runs and one dress rehearsal are enough\nCleansing is done in the source, not in the load\nThe file layout is plain text, one record per line\nDates travel as YYYYMMDD\nControl totals come from the final close of business","constraints":"The April 2027 weekend is fixed\nPersonal data stays in the residency region\nA population cannot load before its predecessor\nSeverity-1 defects block the next mock\nTake-over accounts must finish at zero","risks_mitigations":"Production data copied into a shared workbook – Remove samples from shared workbooks; extracts stay in the staging store\nExtract taken before close of business – Extract after close of business, checked on the mock entry list\nTake-over accounts not at zero – Reconcile take-over accounts to zero before sign-off\nUnmasked data in a lower environment – Masking applied before any refresh\nLoad window overrun – Three mocks with the window measured each time","roles_and_responsibilities":"Delivery lead – Owns delivery and the plan – Priya Naidoo\nBusiness data owner – Signs off the data population – Amina Diallo\nExecutive sponsor – Funds the work and decides escalations – Olivia Banda\nTechnical lead – Owns the technical design – Brian Otieno\nReconciliation lead – Proves control totals after each load – Olivia Banda\nFinance partner – Agrees accounting and control totals – Daniel Okafor","glossary":"Target core\tThe new core banking platform that replaces both legacy cores\nMock\tA full rehearsal load of migrated data into the target core\nHypercare\tThe four weeks of extra support after go-live\nCapability\tSomething the bank does, independent of the system that does it\nTransition architecture\tAn interim state between the baseline and the target","appendices":"Data migration and quality delivery overview\tDelivery Overview – Data migration and quality\nData migration and quality roadmap\tNRB-RM-05\nProgramme architecture principles\tNRB-EA-PR-01","version_history":"0.1\t2026-03-23\tPriya Naidoo\tFirst draft\n0.5\t2026-05-31\tBrian Otieno\tComments from Data migration design authority\n0.9\t2026-08-11\tPriya Naidoo\tReady for review","related_documents":"NRB-RM-05 – Data migration and quality roadmap\nDelivery Overview – Data migration and quality\nNRB-ADR – Architecture decision log","architecture_owner":"Brian Otieno","business_drivers":"A load the bank can explain to audit\nControl totals that match the trial balance\nLess manual repair after go-live\nData owners who have signed their population\nA rehearsed rollback","strategic_goals":"Profiling\nExtraction\nCleansing tracking\nTransformation\nMock run","stakeholder_concerns":"Take-over accounts do not return to zero\nA source access request is still open at Mock 2\nCleansing slips past the freeze\nThe file layout changes late\nA severity-1 defect is found in dress rehearsal","architecture_principles":"One customer, one number, across every channel\nReuse the target core before building\nData is cleansed at source, not in the load\nEvery interface has a named owner and a contract\nSecurity controls are designed in, not added at the end","baseline_architecture":"Today data migration and quality runs on two legacy core instances with point-to-point links to channels and finance. Mock 1 take-over accounts were not at zero","pain_points":"Mock 1 take-over accounts were not at zero\nMock 1 overran by 9 hours and was rerun on 3–4 October 2026\nKYC extract access is still requested\nImage storage decision is open\nTwo data-owner sign-off forms are not issued","target_architecture":"Migration extract, transform, load and reconciliation runs on the target core, reached through the API gateway and the integration platform, with one master record per entity and monitoring on every interface.","capability_map":"Profiling\nExtraction\nCleansing tracking\nTransformation\nMock run\nReconciliation\nControl totals\nTake-over accounting","gaps":"Keep three mocks plus one dress rehearsal\nBook the dress rehearsal environment\nIssue the remaining data-owner sign-off forms\nAdd the defect scale to the mock entry checklist\nRemove the customer sample from the shared workbook","transition_architectures":"Mock 1: both legacy cores live, target core loaded for test only\nMock 3: financial data reconciled in the target core\nGo-live weekend: channels switched to the target core\nHypercare: legacy cores read-only for enquiry","roadmap_items":"Source profiling\nExtraction from both legacy instances\nCleansing at source\nTransformation rules\nMock runs","technology_standards":"Extract tooling for both legacy instances\nStaging database\nTransformation engine\nTarget core load utilities\nReconciliation reporting","governance_process":"Changes are raised at the Data migration design authority with a decision record. The design authority meets weekly. A control total that does not balance, or a missed mock entry criterion, is raised to the executive sponsor the same day.","compliance_requirements":"Personal data stays in the agreed region\nRecords kept for seven years\nAccess recertified before user load\nChange records for every production release"}$j$),
  ('00000000-0000-4000-a01b-000000000006', '00000000-0000-4000-9003-000000000005', 'Integration and interfaces enterprise architecture', 'Enterprise Architecture for integration and interfaces on the Northbridge Bank technology programme. Owner: Brian Otieno.', 'draft', $j${"document_reference":"NRB-EA-06","document_version":"0.9","document_owner":"Brian Otieno","next_review_date":"2026-11-19","purpose":"Describes the enterprise architecture for integration and interfaces on the Northbridge Bank technology programme. Delivery of the interfaces the target platform needs from channels, cards, finance, documents and the user store.","objectives":"Each in-scope interface has a contract, a test and an owner\nFailed messages are visible on one dashboard\nCard status cross-check agrees active cards\nTrial-balance file balances before it is used\nImage retrieval works for a mandate\nChannels no longer call the legacy cores after go-live","scope":"Internet banking interface\nMobile banking interface\nBranch teller interface\nContact centre interface\nCard status cross-check\nDocument image retrieval","out_of_scope":"A new integration platform product selection\nOpen-banking directory build\nCard scheme certification\nATM switch replacement\nPoint of sale acquiring","assumptions":"Existing channels are reused and pointed at the target\nThe card system is not migrated; only status is cross-checked\nThe finance system stays and sends a file\nCertificates can be renewed without a scheme change\nOne dashboard covers every in-scope interface","constraints":"SIT entry dates are fixed on the integration plan\nA missing certificate blocks that interface\nCard numbers are not stored on the dashboard\nThe trial-balance file is after close of business\nReplay cannot create a second payment","risks_mitigations":"Silent message loss – Every interface reports to one dashboard with alerts\nCertificate expiring in hypercare – Certificates valid through hypercare, renewed before the freeze\nReplay creating a duplicate payment – Idempotent replay keyed on the message identifier\nA channel still calling the legacy core – Remove legacy addresses and test from each channel\nUnauthenticated internal API – Mutual TLS on every internal API","roles_and_responsibilities":"Delivery lead – Owns delivery and the plan – Brian Otieno\nBusiness owner – Accepts the scope and the result – Ravi Pillai\nExecutive sponsor – Funds the work and decides escalations – Daniel Okafor\nTechnical lead – Owns the technical design – Ravi Pillai\nInterface analyst – Writes and tests interface contracts – Priya Naidoo\nTest lead – Owns test entry, exit and evidence – Catherine Mwangi","glossary":"Target core\tThe new core banking platform that replaces both legacy cores\nMock\tA full rehearsal load of migrated data into the target core\nHypercare\tThe four weeks of extra support after go-live\nCapability\tSomething the bank does, independent of the system that does it\nTransition architecture\tAn interim state between the baseline and the target","appendices":"Integration and interfaces delivery overview\tDelivery Overview – Integration and interfaces\nIntegration and interfaces roadmap\tNRB-RM-06\nProgramme architecture principles\tNRB-EA-PR-01","version_history":"0.1\t2026-06-22\tBrian Otieno\tFirst draft\n0.5\t2026-08-30\tRavi Pillai\tComments from Integration design authority\n0.9\t2026-11-13\tBrian Otieno\tReady for review","related_documents":"NRB-RM-06 – Integration and interfaces roadmap\nDelivery Overview – Integration and interfaces\nNRB-ADR – Architecture decision log","architecture_owner":"Ravi Pillai","business_drivers":"Channels call one platform\nFailed messages are seen, not lost\nCard status stays consistent\nFinance receives a file it can tie\nBranches can see a mandate","strategic_goals":"Channel interface\nCard status cross-check\nImage retrieval\nTrial-balance file\nUser-store link","stakeholder_concerns":"Two interfaces miss their SIT slot\nA certificate expires in hypercare\nCard status file is late\nTrial-balance file does not balance\nReplay creates a duplicate payment","architecture_principles":"One customer, one number, across every channel\nReuse the target core before building\nData is cleansed at source, not in the load\nEvery interface has a named owner and a contract\nSecurity controls are designed in, not added at the end","baseline_architecture":"Today integration and interfaces runs on two legacy core instances with point-to-point links to channels and finance. Card status and trial-balance have no SIT slot","pain_points":"Card status and trial-balance have no SIT slot\nCertificate inventory is incomplete\nDashboard shows four of twelve interfaces\nRepair role for payments is not named\nImage retrieval test used a synthetic mandate only","target_architecture":"Integration platform and interface estate runs on the target core, reached through the API gateway and the integration platform, with one master record per entity and monitoring on every interface.","capability_map":"Channel interface\nCard status cross-check\nImage retrieval\nTrial-balance file\nUser-store link\nNotification dispatch\nMessage repair\nInterface monitoring","gaps":"Book SIT slots for card status and the trial-balance file\nFinish the certificate inventory\nName the payments repair role\nExtend the duty roster through hypercare\nRemove the remaining legacy channel address","transition_architectures":"Mock 1: both legacy cores live, target core loaded for test only\nMock 3: financial data reconciled in the target core\nGo-live weekend: channels switched to the target core\nHypercare: legacy cores read-only for enquiry","roadmap_items":"Internet banking interface\nMobile banking interface\nBranch teller interface\nContact centre interface\nCard status cross-check","technology_standards":"Integration platform\nAPI gateway\nEvent broker\nManaged file transfer\nMonitoring and alerting service","governance_process":"Changes are raised at the Integration design authority with a decision record. The integration authority owns ambers. An interface that misses SIT entry is escalated to the executive sponsor with a revised slot before the next weekly meeting.","compliance_requirements":"Personal data stays in the agreed region\nRecords kept for seven years\nAccess recertified before user load\nChange records for every production release"}$j$),
  ('00000000-0000-4000-a01b-000000000007', '00000000-0000-4000-9003-000000000005', 'Cybersecurity and access enterprise architecture', 'Enterprise Architecture for cybersecurity and access on the Northbridge Bank technology programme. Owner: Nadia Rahman.', 'draft', $j${"document_reference":"NRB-EA-07","document_version":"0.9","document_owner":"Nadia Rahman","next_review_date":"2026-11-24","purpose":"Describes the enterprise architecture for cybersecurity and access on the Northbridge Bank technology programme. Delivery of user access, recertification and the security controls required before go-live. Currently on hold.","objectives":"Every loaded user has a recertified entitlement\nLeavers are absent from the load\nPrivileged access is listed and approved\nStaff can sign in on day one\nLogging meets the agreed control\nAudit can see who approved each role","scope":"Bank user profiles\nUser groups and roles\nLine-manager recertification\nPrivileged access\nJoiner, mover and leaver handling\nAuthentication for staff","out_of_scope":"Customer authentication redesign\nA new identity product selection\nBuilding access\nCard PIN platform\nEndpoint replacement","assumptions":"Line managers recertify their own staff\nThe identity directory is a source, not a system being replaced\nPrivileged access is a separate list\nLeavers are removed in the source before extract\nCustomer sign-in is owned by the channels delivery","constraints":"User load cannot start before recertification\nThe freeze date does not move for this workstream alone\nPrivileged access requires two approvers\nPersonal data in access logs follows the retention schedule\nA leaver cannot be loaded","risks_mitigations":"Leaver loaded into the target platform – Leaver extract applied before every user load\nShared identity created to save time – Named identities only; shared accounts refused\nPrivileged access copied unchanged – Privileged roles rebuilt and approved, not copied\nLogging weaker than the agreed control – Logging checked against the control before go-live\nSame-day revocation not possible in hypercare – Same-day revocation process tested with the service desk","roles_and_responsibilities":"Delivery lead – Owns delivery and the plan – Nadia Rahman\nBusiness owner – Accepts the scope and the result – Daniel Okafor\nExecutive sponsor – Funds the work and decides escalations – Grace Moyo\nTechnical lead – Owns the technical design – Nadia Rahman\nAccess analyst – Builds the role catalogue and access reviews – Ravi Pillai\nAudit partner – Checks evidence for audit – Olivia Banda","glossary":"Target core\tThe new core banking platform that replaces both legacy cores\nMock\tA full rehearsal load of migrated data into the target core\nHypercare\tThe four weeks of extra support after go-live\nCapability\tSomething the bank does, independent of the system that does it\nTransition architecture\tAn interim state between the baseline and the target","appendices":"Cybersecurity and access delivery overview\tDelivery Overview – Cybersecurity and access\nCybersecurity and access roadmap\tNRB-RM-07\nProgramme architecture principles\tNRB-EA-PR-01","version_history":"0.1\t2026-07-06\tNadia Rahman\tFirst draft\n0.5\t2026-09-13\tNadia Rahman\tComments from Security design authority\n0.9\t2026-11-30\tNadia Rahman\tReady for review","related_documents":"NRB-RM-07 – Cybersecurity and access roadmap\nDelivery Overview – Cybersecurity and access\nNRB-ADR – Architecture decision log","architecture_owner":"Nadia Rahman","business_drivers":"Users loaded are users the bank still wants\nLeavers do not keep access\nPrivileged access is visible\nAudit can see the approval\nStaff sign in on day one","strategic_goals":"User profile load\nRole recertification\nPrivileged access list\nLeaver removal\nStaff sign-in","stakeholder_concerns":"Recertification has no date and the user load misses the freeze\nLeavers are loaded\nA shared identity is created to save time\nPrivileged access is copied unchanged\nLogging is weaker than the agreed control","architecture_principles":"One customer, one number, across every channel\nReuse the target core before building\nData is cleansed at source, not in the load\nEvery interface has a named owner and a contract\nSecurity controls are designed in, not added at the end","baseline_architecture":"Today cybersecurity and access runs on two legacy core instances with point-to-point links to channels and finance. No recertification date is in the plan","pain_points":"No recertification date is in the plan\nThe workstream is on hold\nPrivileged role list is a draft from the legacy core\nLeaver extract definition is not written\nLogging requirements are not signed","target_architecture":"Staff identity, access and security logging runs on the target core, reached through the API gateway and the integration platform, with one master record per entity and monitoring on every interface.","capability_map":"User profile load\nRole recertification\nPrivileged access list\nLeaver removal\nStaff sign-in\nSecurity logging\nApproval evidence\nSame-day revocation","gaps":"Set a recertification date or keep the hold\nWrite the restart criteria\nName the two missing line managers\nSign the logging requirements\nDefine the leaver extract","transition_architectures":"Mock 1: both legacy cores live, target core loaded for test only\nMock 3: financial data reconciled in the target core\nGo-live weekend: channels switched to the target core\nHypercare: legacy cores read-only for enquiry","roadmap_items":"Bank user profiles\nUser groups and roles\nLine-manager recertification\nPrivileged access\nJoiner, mover and leaver handling","technology_standards":"Identity provider\nPrivileged access vault\nSecurity information and event monitoring\nDirectory service\nAccess recertification tool","governance_process":"Changes are raised at the Security design authority with a decision record. The hold is already with the executive sponsor. The authority does not restart build until recertification has a date and an owner.","compliance_requirements":"Personal data stays in the agreed region\nRecords kept for seven years\nAccess recertified before user load\nChange records for every production release"}$j$),
  ('00000000-0000-4000-a01b-000000000008', '00000000-0000-4000-9003-000000000005', 'Environments and release enterprise architecture', 'Enterprise Architecture for environments and release on the Northbridge Bank technology programme. Owner: Ravi Pillai.', 'draft', $j${"document_reference":"NRB-EA-08","document_version":"0.9","document_owner":"Ravi Pillai","next_review_date":"2026-11-18","purpose":"Describes the enterprise architecture for environments and release on the Northbridge Bank technology programme. Delivery of the environment path from development through dress rehearsal, production and recovery, and the release calendar that uses it.","objectives":"Every test stage has a booked environment\nDress rehearsal uses a production-like path\nRefresh is requested and logged\nThe release calendar is the only source of release dates\nRecovery is restored and checked before go-live\nNo two mocks share an environment","scope":"Development environment\nTest environment\nSystem integration environment\nUser acceptance environment\nPre-production\nProduction cutover runbook","out_of_scope":"A new data centre build\nEnd-user device replacement\nNetwork redesign\nCloud provider selection\nProduction support model","assumptions":"Existing hosting is reused\nProduction-like data is masked except in dress rehearsal under approval\nOne calendar is enough\nRecovery is a restore test, not a second data centre project\nTeams will book if the booking is easier than asking in a chat","constraints":"The dress rehearsal date is fixed once booked\nMasked data is the default\nProduction access is named people only\nTwo mocks cannot share an environment\nA refresh during execution is refused","risks_mitigations":"Refresh using unmasked production data – Masking approved and applied before refresh\nTwo mocks booked on one environment – One booking register, mandatory from SIT\nRecovery backup that cannot be restored – Recovery restore rehearsed before go-live\nProduction access wider than the named list – Named production access list reviewed monthly\nConfiguration drift between environments – One configuration baseline promoted through every environment","roles_and_responsibilities":"Delivery lead – Owns delivery and the plan – Ravi Pillai\nBusiness owner – Accepts the scope and the result – Brian Otieno\nExecutive sponsor – Funds the work and decides escalations – Daniel Okafor\nTechnical lead – Owns the technical design – Ravi Pillai\nEnvironment analyst – Books and refreshes environments – Priya Naidoo\nRelease manager – Owns the release calendar – Linda Zhou","glossary":"Target core\tThe new core banking platform that replaces both legacy cores\nMock\tA full rehearsal load of migrated data into the target core\nHypercare\tThe four weeks of extra support after go-live\nCapability\tSomething the bank does, independent of the system that does it\nTransition architecture\tAn interim state between the baseline and the target","appendices":"Environments and release delivery overview\tDelivery Overview – Environments and release\nEnvironments and release roadmap\tNRB-RM-08\nProgramme architecture principles\tNRB-EA-PR-01","version_history":"0.1\t2026-04-06\tRavi Pillai\tFirst draft\n0.5\t2026-06-14\tRavi Pillai\tComments from Environment and release forum\n0.9\t2026-09-03\tRavi Pillai\tReady for review","related_documents":"NRB-RM-08 – Environments and release roadmap\nDelivery Overview – Environments and release\nNRB-ADR – Architecture decision log","architecture_owner":"Ravi Pillai","business_drivers":"Tests are not stopped by a clash\nDress rehearsal looks like production\nRefreshes are traceable\nOne calendar for the programme\nA recovery test before it is needed","strategic_goals":"Environment booking\nData refresh\nRelease calendar\nMasked data\nDress rehearsal path","stakeholder_concerns":"Dress rehearsal has no environment\nA refresh uses unmasked production data\nTwo mocks are booked on one environment\nThe April weekend is double-booked\nRecovery backup cannot be restored","architecture_principles":"One customer, one number, across every channel\nReuse the target core before building\nData is cleansed at source, not in the load\nEvery interface has a named owner and a contract\nSecurity controls are designed in, not added at the end","baseline_architecture":"Today environments and release runs on two legacy core instances with point-to-point links to channels and finance. Dress rehearsal environment is not booked","pain_points":"Dress rehearsal environment is not booked\nRefresh is still a manual copy\nMasking rules are drafted and not approved\nThe release calendar is a spreadsheet as well as the register\nRecovery restore has not been attempted","target_architecture":"Environment path and release calendar runs on the target core, reached through the API gateway and the integration platform, with one master record per entity and monitoring on every interface.","capability_map":"Environment booking\nData refresh\nRelease calendar\nMasked data\nDress rehearsal path\nProduction runbook\nRecovery restore\nAccess approval","gaps":"Book the dress rehearsal environment\nApprove the masking rules\nRetire the side spreadsheet\nWrite the production access list\nSchedule the recovery restore","transition_architectures":"Mock 1: both legacy cores live, target core loaded for test only\nMock 3: financial data reconciled in the target core\nGo-live weekend: channels switched to the target core\nHypercare: legacy cores read-only for enquiry","roadmap_items":"Development environment\nTest environment\nSystem integration environment\nUser acceptance environment\nPre-production","technology_standards":"Deployment pipeline\nConfiguration management\nData masking tooling\nEnvironment booking register\nBackup and restore service","governance_process":"Changes are raised at the Environment and release forum with a decision record. The forum owns environment clashes. A lost dress rehearsal slot, or a production defect caused by a bad refresh, goes to the executive sponsor the same day.","compliance_requirements":"Personal data stays in the agreed region\nRecords kept for seven years\nAccess recertified before user load\nChange records for every production release"}$j$),
  ('00000000-0000-4000-a01b-000000000009', '00000000-0000-4000-9003-000000000005', 'Operational readiness and hypercare enterprise architecture', 'Enterprise Architecture for operational readiness and hypercare on the Northbridge Bank technology programme. Owner: Linda Zhou.', 'draft', $j${"document_reference":"NRB-EA-09","document_version":"0.9","document_owner":"Linda Zhou","next_review_date":"2026-11-20","purpose":"Describes the enterprise architecture for operational readiness and hypercare on the Northbridge Bank technology programme. Delivery of the support model, runbooks, monitoring handover and the hypercare period after go-live.","objectives":"Every cutover step has a runbook someone has walked through\nHypercare shifts are named, including nights\nThe daily bridge has an agenda and a chair\nSeverity scale matches the defect scale\nMonitoring alerts reach the roster\nKnown errors are written down before go-live","scope":"Support model\nRunbooks for the cutover weekend\nHypercare roster\nDaily hypercare bridge\nSeverity scale for hypercare\nMonitoring handover","out_of_scope":"A new service-desk product\nBranch refurbishment\nA 24-hour contact centre build\nVendor contract renegotiation\nProduction data centre build","assumptions":"Hypercare lasts four weeks\nThe existing service desk is the front door\nRunbooks are steps with an expected result\nNight shifts are required for the first week only\nMonitoring is handed over, not rebuilt","constraints":"Hypercare cannot be staffed by unnamed roles\nA runbook that has not been walked through does not count\nThe first week has night cover\nExit criteria are set before go-live\nThe bridge is every business day in hypercare","risks_mitigations":"Alerts going to a mailbox nobody reads – Alerts routed to the named roster, not a mailbox\nNight shifts left unnamed – Name every shift, including nights, before the dress rehearsal\nRunbooks never walked through – Walk through every runbook in the dress rehearsal\nKnown errors found by customers – Publish the known-error list before go-live\nSeverity 1 response slower than 30 minutes – Severity 1 bridge opened within 15 minutes","roles_and_responsibilities":"Delivery lead – Owns delivery and the plan – Linda Zhou\nBusiness owner – Accepts the scope and the result – Catherine Mwangi\nExecutive sponsor – Funds the work and decides escalations – Grace Moyo\nTechnical lead – Owns the technical design – Ahmed Hassan\nService desk lead – Prepares the service desk for go-live – Brian Otieno\nOperations lead – Owns run procedures after go-live – Ravi Pillai","glossary":"Target core\tThe new core banking platform that replaces both legacy cores\nMock\tA full rehearsal load of migrated data into the target core\nHypercare\tThe four weeks of extra support after go-live\nCapability\tSomething the bank does, independent of the system that does it\nTransition architecture\tAn interim state between the baseline and the target","appendices":"Operational readiness and hypercare delivery overview\tDelivery Overview – Operational readiness and hypercare\nOperational readiness and hypercare roadmap\tNRB-RM-09\nProgramme architecture principles\tNRB-EA-PR-01","version_history":"0.1\t2026-09-22\tLinda Zhou\tFirst draft\n0.5\t2026-11-30\tAhmed Hassan\tComments from Operational readiness forum\n0.9\t2027-02-22\tLinda Zhou\tReady for review","related_documents":"NRB-RM-09 – Operational readiness and hypercare roadmap\nDelivery Overview – Operational readiness and hypercare\nNRB-ADR – Architecture decision log","architecture_owner":"Ahmed Hassan","business_drivers":"A weekend someone has already rehearsed\nNamed people on the night shift\nCustomers reach a desk that has a script\nAlerts that reach a person\nA known end to hypercare","strategic_goals":"Support model\nCutover runbook\nHypercare roster\nDaily bridge\nSeverity handling","stakeholder_concerns":"Night shifts stay unnamed\nRunbooks are written and never walked through\nHypercare is assumed to end on day 28\nMonitoring alerts go to a mailbox nobody reads\nThe service desk has no script","architecture_principles":"One customer, one number, across every channel\nReuse the target core before building\nData is cleansed at source, not in the load\nEvery interface has a named owner and a contract\nSecurity controls are designed in, not added at the end","baseline_architecture":"Today operational readiness and hypercare runs on two legacy core instances with point-to-point links to channels and finance. Support model is not drafted","pain_points":"Support model is not drafted\nNo runbook exists yet\nNight shifts are unnamed\nMonitoring owner is not named\nBridge chair is not named","target_architecture":"Support model, monitoring and hypercare runs on the target core, reached through the API gateway and the integration platform, with one master record per entity and monitoring on every interface.","capability_map":"Support model\nCutover runbook\nHypercare roster\nDaily bridge\nSeverity handling\nMonitoring handover\nKnown errors\nExit criteria","gaps":"Draft the support model before December\nName the bridge chair\nName night-shift leads for week one\nName the monitoring owner\nConfirm product owners as the business-as-usual owners","transition_architectures":"Mock 1: both legacy cores live, target core loaded for test only\nMock 3: financial data reconciled in the target core\nGo-live weekend: channels switched to the target core\nHypercare: legacy cores read-only for enquiry","roadmap_items":"Support model\nRunbooks for the cutover weekend\nHypercare roster\nDaily hypercare bridge\nSeverity scale for hypercare","technology_standards":"Service management tool\nMonitoring and alerting service\nCollaboration bridge\nKnowledge base\nOn-call roster","governance_process":"Changes are raised at the Operational readiness forum with a decision record. The monthly forum is enough while the work is in initiation. From the dress rehearsal onward, a missing runbook or an unstaffed hypercare shift is escalated the same day.","compliance_requirements":"Personal data stays in the agreed region\nRecords kept for seven years\nAccess recertified before user load\nChange records for every production release"}$j$),
  ('00000000-0000-4000-a01b-000000000010', '00000000-0000-4000-9003-000000000005', 'Regulatory reporting enterprise architecture', 'Enterprise Architecture for regulatory reporting. Superseded: the reporting workstream closed on 30 September 2026; kept for reference.', 'superseded', $j${"document_reference":"NRB-EA-10","document_version":"1.0","document_owner":"Olivia Banda","next_review_date":"2027-03-31","purpose":"Describes the enterprise architecture for regulatory reporting on the Northbridge Bank technology programme. Completed delivery of the report-line mapping that lets finance keep the existing reporting tool across the migration.","objectives":"Every report line used in the last year has a mapped source\nThe mock cross-check agreed\nDifferences go to the agreed difference account\nThe financial controller has signed\nFinance did not change tool\nEvidence is in the go-live pack","scope":"Report-line map from the trial balance\nCurrency and company mapping\nFirst mock cross-check\nEvidence pack for finance\nNamed owner per report family\nDifference account treatment","out_of_scope":"A new reporting tool\nPrudential return redesign\nTax engine replacement\nManagement information warehouse\nBoard pack redesign","assumptions":"The finance system stays\nThe chart of accounts does not change for go-live\nLast year of report lines is the scope\nDifferences use account 14918 as already agreed for the journals\nThe controller is the signer","constraints":"No new reporting tool\nThe map cannot drop a line used in the last year\nDifferences have one account\nSign-off is the controller, not the project\nThe guide stays short","risks_mitigations":"A report line missed in the map – Check every report line used in the last year against the map\nA mapped line changing meaning – Reopen rule limited to the affected report\nThe difference account used for something else – Account 14918 reserved for differences only\nCustomer-level data in the evidence pack – Remove customer-level rows from the pack\nController signature on the wrong version – Controller signs the version number on the pack","roles_and_responsibilities":"Delivery lead – Owns delivery and the plan – Olivia Banda\nBusiness owner – Accepts the scope and the result – Olivia Banda\nExecutive sponsor – Funds the work and decides escalations – Grace Moyo\nTechnical lead – Owns the technical design – Priya Naidoo\nFinance analyst – Maps ledger accounts and report lines – Daniel Okafor\nMapping analyst – Maintains the report-line map – Amina Diallo","glossary":"Target core\tThe new core banking platform that replaces both legacy cores\nMock\tA full rehearsal load of migrated data into the target core\nHypercare\tThe four weeks of extra support after go-live\nCapability\tSomething the bank does, independent of the system that does it\nTransition architecture\tAn interim state between the baseline and the target","appendices":"Regulatory reporting delivery overview\tDelivery Overview – Regulatory reporting\nRegulatory reporting roadmap\tNRB-RM-10\nProgramme architecture principles\tNRB-EA-PR-01","version_history":"0.1\t2026-02-23\tOlivia Banda\tFirst draft\n0.5\t2026-05-03\tPriya Naidoo\tComments from Finance and regulatory forum\n1.0\t2026-09-28\tOlivia Banda\tFinal; workstream closed","related_documents":"NRB-RM-10 – Regulatory reporting roadmap\nDelivery Overview – Regulatory reporting\nNRB-ADR – Architecture decision log","architecture_owner":"Priya Naidoo","business_drivers":"Finance keeps a tool it already knows\nReport lines that still tie\nA signed map\nA small guide\nA reopen path that is narrow","strategic_goals":"Report-line map\nCurrency mapping\nCompany mapping\nMock cross-check\nDifference account","stakeholder_concerns":"A report line was missed\nA mapped line changes meaning before April 2027\nThe difference account is used for something else\nThe controller signature is on the wrong version\nThe guide is not kept","architecture_principles":"One customer, one number, across every channel\nReuse the target core before building\nData is cleansed at source, not in the load\nEvery interface has a named owner and a contract\nSecurity controls are designed in, not added at the end","baseline_architecture":"Today regulatory reporting runs on two legacy core instances with point-to-point links to channels and finance. None open. The missed-line sample was corrected before sign-off","pain_points":"None open. The missed-line sample was corrected before sign-off\nThe first version of the guide was four pages and was cut\nOne company code was harmonised late and rechecked\nA draft pack page contained a customer sample and was removed\nThe controller signed version 1.1","target_architecture":"Report-line mapping for the existing reporting tool runs on the target core, reached through the API gateway and the integration platform, with one master record per entity and monitoring on every interface.","capability_map":"Report-line map\nCurrency mapping\nCompany mapping\nMock cross-check\nDifference account\nEvidence pack\nController sign-off\nReopen rule","gaps":"Close the workstream\nKeep the reopen rule to a single report\nKeep account 14918 as the difference account\nLeave the guide with finance\nDo not select a new reporting tool","transition_architectures":"Mock 1: both legacy cores live, target core loaded for test only\nMock 3: financial data reconciled in the target core\nGo-live weekend: channels switched to the target core\nHypercare: legacy cores read-only for enquiry","roadmap_items":"Report-line map from the trial balance\nCurrency and company mapping\nFirst mock cross-check\nEvidence pack for finance\nNamed owner per report family","technology_standards":"Existing reporting tool\nFinance ledger\nMapping workbook\nEvidence store\nReconciliation reporting","governance_process":"Changes are raised at the Finance and regulatory forum with a decision record. Closed work. A general-ledger line that changes meaning is raised to the finance forum and reopens only the affected report, not the whole workstream.","compliance_requirements":"Personal data stays in the agreed region\nRecords kept for seven years\nAccess recertified before user load\nChange records for every production release"}$j$),
  ('00000000-0000-4000-a01c-000000000001', '00000000-0000-4000-9003-000000000006', 'Customer and digital channels solution architecture', 'Solution Architecture for customer and digital channels on the Northbridge Bank technology programme. Owner: Amina Diallo.', 'draft', $j${"document_reference":"NRB-SA-01","document_version":"0.9","document_owner":"Amina Diallo","next_review_date":"2026-11-16","purpose":"Describes the solution architecture for customer and digital channels on the Northbridge Bank technology programme. Delivery of customer master data and the internet, mobile and branch channels for the Northbridge Bank technology programme.","objectives":"Every active customer has one surviving customer number\nAddress completeness at or above 85%\nInternet and mobile users can sign in on day one\nDuplicate customers reduced below 1%\nMandate images linked to the surviving customer\nBranch search returns the customer in under 3 seconds","scope":"Retail and SME customer master\nCorporate customer master from the second legacy instance\nInternet banking registration\nMobile banking registration\nBranch teller customer search\nContact centre customer view","out_of_scope":"Card plastic personalisation\nMarketing campaign tool\nLoyalty scheme\nInsurance product origination\nWealth advisory portal","assumptions":"Both legacy instances are profiled before Mock 2\nThe surviving record is the one with the most complete KYC data\nCustomers accept a new customer number where numbers clash\nBranch staff are trained before the dress rehearsal\nStatement templates are approved by the business","constraints":"Customer numbers must be unique across both legacy instances\nKYC fields are mandatory before a customer can be loaded\nAddress completeness target is 85%\nImages must be linked before the channel is opened\nThe load window is the weekend of 10–12 April 2027","risks_mitigations":"Account takeover through weak registration checks – Two-factor registration and device binding\nDuplicate customer merged onto the wrong survivor – Survivor rule signed by the business data owner and sample-checked\nMandate images exposed through a direct link – Images served only through the authenticated retrieval API\nCredential stuffing on internet banking sign-in – Rate limits and lock-out on sign-in\nPersonal data copied into test environments – Masked data only in lower environments","roles_and_responsibilities":"Delivery lead – Owns delivery and the plan – Amina Diallo\nBusiness owner – Accepts the scope and the result – Nomvula Khumalo\nExecutive sponsor – Funds the work and decides escalations – Grace Moyo\nTechnical lead – Owns the technical design – Ravi Pillai\nData analyst – Profiles and maps the data – Priya Naidoo\nChannel analyst – Designs channel journeys and entitlements – Brian Otieno","glossary":"Target core\tThe new core banking platform that replaces both legacy cores\nMock\tA full rehearsal load of migrated data into the target core\nHypercare\tThe four weeks of extra support after go-live\nNon-functional requirement\tA quality the solution must have, such as speed or availability\nRecovery time objective\tHow long the service may be down after a failure","appendices":"Customer and digital channels delivery overview\tDelivery Overview – Customer and digital channels\nCustomer and digital channels roadmap\tNRB-RM-01\nProgramme architecture principles\tNRB-EA-PR-01","version_history":"0.1\t2026-04-27\tAmina Diallo\tFirst draft\n0.5\t2026-07-05\tRavi Pillai\tComments from Channels steering group\n0.9\t2026-09-03\tAmina Diallo\tReady for review","related_documents":"NRB-RM-01 – Customer and digital channels roadmap\nDelivery Overview – Customer and digital channels\nNRB-ADR – Architecture decision log","solution_architect":"Ravi Pillai","solution_name":"Customer master and channel access","deployment_model":"hybrid","business_requirements":"Single customer view\nCustomer deduplication\nInternet banking sign-in\nMobile banking sign-in\nBranch customer search\nContact centre desktop","stakeholders":"Amina Diallo (Delivery lead)\nNomvula Khumalo (Business owner)\nGrace Moyo (Executive sponsor)\nRavi Pillai (Technical lead)\nPriya Naidoo (Data analyst)\nBrian Otieno (Channel analyst)","architecture_overview":"Customer master and channel access uses customer master service, deduplication and survivorship engine, internet banking front end on the target core. Channels reach it through the API gateway; batch and file flows run through the integration platform.","components":"Customer master service\nDeduplication and survivorship engine\nInternet banking front end\nMobile banking back end\nBranch customer search\nContact centre customer view","technology_stack":"Target core banking platform – customer module\nAPI gateway\nIdentity provider for customer sign-in\nRelational database for the customer master\nObject store for mandate images","non_functional_requirements":"Performance – Branch customer search response – Under 3 seconds at peak\nAvailability – Internet and mobile sign-in – 99.9% monthly\nData quality – Address completeness – 85% or higher\nSecurity – Strong customer sign-in – Two factors on every new device","availability_target":99.9,"recovery_point_objective":1,"recovery_time_objective":4,"interfaces":"Customer profile sync\nMandate image retrieval\nRegistration events\nCustomer cross-reference load\nContact centre lookup","data_flows":"Target core to Internet banking (real-time api)\nObject store to Branch teller (real-time api)\nInternet banking to Target core (event streaming)\nMigration staging to Target core (batch)\nTarget core to Contact centre desktop (real-time api)","security_controls":"Mutual TLS between services\nRole-based access from the recertified role catalogue\nEncryption at rest for customer and account data\nSecurity events sent to central monitoring","architecture_decisions":"NRB-ADR-01 – Survivor rule for duplicate customers\nNRB-ADR-02 – Store mandate and signature images in a file store\nNRB-ADR-03 – 8-digit customer number standard","technical_debt":"Two legacy instances kept read-only during hypercare\nManual reconciliation steps still in spreadsheets\nSome interfaces still file based"}$j$),
  ('00000000-0000-4000-a01c-000000000002', '00000000-0000-4000-9003-000000000006', 'Payments and transfers solution architecture', 'Solution Architecture for payments and transfers on the Northbridge Bank technology programme. Owner: Ahmed Hassan.', 'draft', $j${"document_reference":"NRB-SA-02","document_version":"0.9","document_owner":"Ahmed Hassan","next_review_date":"2026-11-18","purpose":"Describes the solution architecture for payments and transfers on the Northbridge Bank technology programme. Delivery of domestic payments, standing orders and internal transfers onto the target platform.","objectives":"Every active standing order is recreated before go-live\nSettlement totals agree to the cent\nReturned payments land on the repair queue\nChannel limits match the signed matrix\nNo duplicate payment on the cutover weekend\nCut-off calendar loaded for the next 18 months","scope":"Domestic credit transfers\nInternal account transfers\nStanding orders\nFuture-dated payments\nPayment limits by channel\nSettlement timetable","out_of_scope":"Card authorisation\nATM cash\nCheque clearing replacement\nCross-border correspondent banking rebuild\nCash-in-transit","assumptions":"The scheme timetable does not change before go-live\nStanding orders are recreated, not replayed from history\nBoth legacy instances use the same value-date rule\nPayment limits are signed by the business before UAT\nThe repair queue is staffed for hypercare","constraints":"Scheme cut-off cannot move\nSettlement must balance on the night\nStanding orders with an end date in the past are excluded\nDual control stays on the repair queue\nPayment files are not accepted during the freeze","risks_mitigations":"Duplicate payment on the cutover weekend – Idempotent posting keyed on the payment reference\nChannel limits looser than the signed matrix – Load limits from the signed matrix and test every band\nScheme certificate expiry – Certificate inventory with 60-day expiry alerts\nTampered payment file in transit – Signed and encrypted payment files\nRepair actions without dual control – Dual control enforced on every repair action","roles_and_responsibilities":"Delivery lead – Owns delivery and the plan – Ahmed Hassan\nBusiness owner – Accepts the scope and the result – Catherine Mwangi\nExecutive sponsor – Funds the work and decides escalations – Daniel Okafor\nTechnical lead – Owns the technical design – Brian Otieno\nSettlement analyst – Designs settlement and reconciliation – Olivia Banda\nTest lead – Owns test entry, exit and evidence – Priya Naidoo","glossary":"Target core\tThe new core banking platform that replaces both legacy cores\nMock\tA full rehearsal load of migrated data into the target core\nHypercare\tThe four weeks of extra support after go-live\nNon-functional requirement\tA quality the solution must have, such as speed or availability\nRecovery time objective\tHow long the service may be down after a failure","appendices":"Payments and transfers delivery overview\tDelivery Overview – Payments and transfers\nPayments and transfers roadmap\tNRB-RM-02\nProgramme architecture principles\tNRB-EA-PR-01","version_history":"0.1\t2026-05-25\tAhmed Hassan\tFirst draft\n0.5\t2026-08-02\tBrian Otieno\tComments from Payments working group\n0.9\t2026-10-04\tAhmed Hassan\tReady for review","related_documents":"NRB-RM-02 – Payments and transfers roadmap\nDelivery Overview – Payments and transfers\nNRB-ADR – Architecture decision log","solution_architect":"Brian Otieno","solution_name":"Domestic payments and standing orders","deployment_model":"hybrid","business_requirements":"Domestic credit transfer\nInternal transfer\nStanding order booking\nFuture-dated payment\nPayment limits\nSettlement","stakeholders":"Ahmed Hassan (Delivery lead)\nCatherine Mwangi (Business owner)\nDaniel Okafor (Executive sponsor)\nBrian Otieno (Technical lead)\nOlivia Banda (Settlement analyst)\nPriya Naidoo (Test lead)","architecture_overview":"Domestic payments and standing orders uses payment initiation service, standing order scheduler, limit check service on the target core. Channels reach it through the API gateway; batch and file flows run through the integration platform.","components":"Payment initiation service\nStanding order scheduler\nLimit check service\nSettlement posting\nRepair queue\nScheme gateway adapter","technology_stack":"Target core banking platform – payments module\nEvent broker\nScheme gateway\nRelational database for payment state\nIntegration platform","non_functional_requirements":"Performance – Payment initiation – Under 2 seconds end to end\nAvailability – Payment initiation – 99.95% monthly\nIntegrity – Settlement totals – Agree to the cent every cycle\nRecovery – Payment state – No lost or duplicated payment after failover","availability_target":99.95,"recovery_point_objective":0.25,"recovery_time_objective":2,"interfaces":"Outbound credit transfers\nInbound credits\nPayment status events\nReturned items\nNotification dispatch","data_flows":"Target core to Scheme gateway (file transfer)\nScheme gateway to Target core (file transfer)\nTarget core to Internet banking (event streaming)\nScheme gateway to Repair queue (batch)\nTarget core to Notification service (event streaming)","security_controls":"Mutual TLS between services\nRole-based access from the recertified role catalogue\nEncryption at rest for customer and account data\nSecurity events sent to central monitoring","architecture_decisions":"NRB-ADR-05 – Recreate standing orders instead of replaying them\nNRB-ADR-09 – One dashboard for every interface","technical_debt":"Two legacy instances kept read-only during hypercare\nManual reconciliation steps still in spreadsheets\nSome interfaces still file based"}$j$),
  ('00000000-0000-4000-a01c-000000000003', '00000000-0000-4000-9003-000000000006', 'Lending, limits and collateral solution architecture', 'Solution Architecture for lending, limits and collateral on the Northbridge Bank technology programme. Owner: Joy Akinyi.', 'draft', $j${"document_reference":"NRB-SA-03","document_version":"0.9","document_owner":"Joy Akinyi","next_review_date":"2026-11-11","purpose":"Describes the solution architecture for lending, limits and collateral on the Northbridge Bank technology programme. Delivery of loans, limits and collateral, including overdue bills and the expired-limit rule.","objectives":"Every live loan has an arrangement, a balance and a schedule\nAgeing continues from the legacy past-due date\nExpired limits follow the signed rule\nCollateral is linked before the loan is loaded\nOne repayment account per customer per currency\nTake-over accounts return to zero","scope":"Retail loan arrangements\nCorporate loan arrangements\nOverdue and due bills\nAccrued interest on loans\nLimit records\nExpired limits still linked to a contract","out_of_scope":"New scorecard build\nDebt collection agency files\nSecuritisation\nSyndicated loan agency\nTrade finance instruments","assumptions":"Schedules are regenerated from the migrated frequency\nThe expired-limit rule is expiry plus one day, with the original date kept\nOne liquidation account is allowed per customer per currency\nCollateral rights load before collateral items\nPast-due date becomes the bill date","constraints":"A loan cannot load before its customer and account\nCollateral cannot load before its right\nAgeing must not reset to zero\nExpired limits cannot be dropped while a contract is live\nTake-over accounts must be zero after reconciliation","risks_mitigations":"Expired limit left securing a live contract – Expired-limit rule signed and every case on a credit review queue\nCollateral loaded before its right and rejected – Load rights before items, rehearsed in Mock 2\nAccrual counted twice after migration – Accrual value date set to the migration date\nUnauthorised limit override – Limit overrides need a second approver\nCredit data exposed to non-credit staff – Credit screens limited to credit roles","roles_and_responsibilities":"Delivery lead – Owns delivery and the plan – Joy Akinyi\nBusiness owner – Accepts the scope and the result – Daniel Okafor\nExecutive sponsor – Funds the work and decides escalations – Grace Moyo\nTechnical lead – Owns the technical design – Priya Naidoo\nCredit analyst – Defines lending and limit rules – Ahmed Hassan\nCollateral analyst – Maps collateral rights and items – Linda Zhou","glossary":"Target core\tThe new core banking platform that replaces both legacy cores\nMock\tA full rehearsal load of migrated data into the target core\nHypercare\tThe four weeks of extra support after go-live\nNon-functional requirement\tA quality the solution must have, such as speed or availability\nRecovery time objective\tHow long the service may be down after a failure","appendices":"Lending, limits and collateral delivery overview\tDelivery Overview – Lending, limits and collateral\nLending, limits and collateral roadmap\tNRB-RM-03\nProgramme architecture principles\tNRB-EA-PR-01","version_history":"0.1\t2026-06-08\tJoy Akinyi\tFirst draft\n0.5\t2026-08-16\tPriya Naidoo\tComments from Credit design authority\n0.9\t2026-10-21\tJoy Akinyi\tReady for review","related_documents":"NRB-RM-03 – Lending, limits and collateral roadmap\nDelivery Overview – Lending, limits and collateral\nNRB-ADR – Architecture decision log","solution_architect":"Priya Naidoo","solution_name":"Loans, limits and collateral","deployment_model":"on_premises","business_requirements":"Loan arrangement\nBalance and accrual capture\nBill and ageing\nLimit maintenance\nExpired-limit rule\nCollateral right","stakeholders":"Joy Akinyi (Delivery lead)\nDaniel Okafor (Business owner)\nGrace Moyo (Executive sponsor)\nPriya Naidoo (Technical lead)\nAhmed Hassan (Credit analyst)\nLinda Zhou (Collateral analyst)","architecture_overview":"Loans, limits and collateral uses loan arrangement service, repayment schedule engine, limit hierarchy on the target core. Channels reach it through the API gateway; batch and file flows run through the integration platform.","components":"Loan arrangement service\nRepayment schedule engine\nLimit hierarchy\nCollateral register\nAgeing and arrears\nCredit enquiry","technology_stack":"Target core banking platform – lending module\nCollateral register\nRelational database for limits\nIntegration platform\nReporting database","non_functional_requirements":"Accuracy – Loan balance after migration – Agrees to legacy to the cent\nPerformance – Overnight schedule run – Completes inside 3 hours\nAvailability – Credit enquiry – 99.5% in business hours\nAuditability – Limit changes – Every change has an approver","availability_target":99.5,"recovery_point_objective":4,"recovery_time_objective":8,"interfaces":"Collateral to loan link\nLoan balances\nArrears status\nLimit utilisation\nLoan migration load","data_flows":"Collateral register to Target core (real-time api)\nTarget core to Finance ledger (batch)\nTarget core to Collections system (batch)\nTarget core to Credit risk reporting (batch)\nMigration staging to Target core (batch)","security_controls":"Mutual TLS between services\nRole-based access from the recertified role catalogue\nEncryption at rest for customer and account data\nSecurity events sent to central monitoring","architecture_decisions":"NRB-ADR-06 – Migrate expired limits that still secure a live contract","technical_debt":"Two legacy instances kept read-only during hypercare\nManual reconciliation steps still in spreadsheets\nSome interfaces still file based"}$j$),
  ('00000000-0000-4000-a01c-000000000004', '00000000-0000-4000-9003-000000000006', 'Deposits and accounts solution architecture', 'Solution Architecture for deposits and accounts on the Northbridge Bank technology programme. Owner: Catherine Mwangi.', 'draft', $j${"document_reference":"NRB-SA-04","document_version":"0.9","document_owner":"Catherine Mwangi","next_review_date":"2026-11-17","purpose":"Describes the solution architecture for deposits and accounts on the Northbridge Bank technology programme. Delivery of current accounts, savings and term deposits, including balances and accruals.","objectives":"Every open account has a product, a balance and an owner\nInstance 2 account numbers are kept as alternate keys\nDormant accounts over five years are closed or transferred\nMatured deposits no longer carry a balance at the freeze\nRestrictions match the legacy narrative\nStatement frequency is remapped","scope":"Current accounts\nSavings accounts\nTerm deposits\nDeposit balances and accruals\nDormant accounts over five years\nMatured deposits that still hold a balance","out_of_scope":"Safe custody\nNew savings product launch\nPrize-linked savings\nChildren account campaign\nBrokerage cash accounts","assumptions":"Three legacy current-account products become one target product\nInstance 2 numbers become 10 digits with a check digit\nDormant means no customer-initiated transaction for five years\nUnclaimed balances move under the existing regulation\nMatured deposits are paid out or rolled, not migrated as running","constraints":"No account closures in the week before go-live\nA zero-balance account marked for closure is excluded\nAlternate keys are mandatory for instance 2\nAccrual value date cannot be the original accrual date\nProduct mapping cannot change after Mock 2 without a new approval","risks_mitigations":"Matured deposit still carrying a balance at the freeze – Pay out or roll matured deposits before the freeze\nAccount numbers clashing across the two instances – 10-digit numbers with check digit and alternate keys\nRestriction narrative dropped in migration – Sample-check restriction narratives after each mock\nStatement sent to the wrong address – Address taken from the survivor customer record\nInterest accrued twice – Accrual reconciled by product after Mock 3","roles_and_responsibilities":"Delivery lead – Owns delivery and the plan – Catherine Mwangi\nBusiness owner – Accepts the scope and the result – Nomvula Khumalo\nExecutive sponsor – Funds the work and decides escalations – Olivia Banda\nTechnical lead – Owns the technical design – Brian Otieno\nProduct analyst – Maps products to the target core – Amina Diallo\nFinance partner – Agrees accounting and control totals – Daniel Okafor","glossary":"Target core\tThe new core banking platform that replaces both legacy cores\nMock\tA full rehearsal load of migrated data into the target core\nHypercare\tThe four weeks of extra support after go-live\nNon-functional requirement\tA quality the solution must have, such as speed or availability\nRecovery time objective\tHow long the service may be down after a failure","appendices":"Deposits and accounts delivery overview\tDelivery Overview – Deposits and accounts\nDeposits and accounts roadmap\tNRB-RM-04\nProgramme architecture principles\tNRB-EA-PR-01","version_history":"0.1\t2026-05-11\tCatherine Mwangi\tFirst draft\n0.5\t2026-07-19\tBrian Otieno\tComments from Deposits product forum\n0.9\t2026-09-26\tCatherine Mwangi\tReady for review","related_documents":"NRB-RM-04 – Deposits and accounts roadmap\nDelivery Overview – Deposits and accounts\nNRB-ADR – Architecture decision log","solution_architect":"Brian Otieno","solution_name":"Current, savings and term deposit accounts","deployment_model":"on_premises","business_requirements":"Current account\nSavings account\nTerm deposit\nBalance and accrual capture\nRestriction\nStatement frequency","stakeholders":"Catherine Mwangi (Delivery lead)\nNomvula Khumalo (Business owner)\nOlivia Banda (Executive sponsor)\nBrian Otieno (Technical lead)\nAmina Diallo (Product analyst)\nDaniel Okafor (Finance partner)","architecture_overview":"Current, savings and term deposit accounts uses account service, interest accrual, term deposit maturity on the target core. Channels reach it through the API gateway; batch and file flows run through the integration platform.","components":"Account service\nInterest accrual\nTerm deposit maturity\nRestriction service\nStatement scheduler\nDormancy processing","technology_stack":"Target core banking platform – accounts module\nStatement engine\nRelational database for accounts\nIntegration platform\nObject store for statements","non_functional_requirements":"Accuracy – Balances by product and currency – Agree to the trial balance\nPerformance – Balance enquiry – Under 1 second\nAvailability – Account enquiry – 99.9% monthly\nRetention – Statements – Kept 7 years","availability_target":99.9,"recovery_point_objective":1,"recovery_time_objective":4,"interfaces":"Balance enquiry\nStatement generation\nDormant account report\nAccount migration load\nGeneral ledger postings","data_flows":"Target core to Internet banking (real-time api)\nTarget core to Statement engine (batch)\nTarget core to Operations (batch)\nMigration staging to Target core (batch)\nTarget core to Finance ledger (batch)","security_controls":"Mutual TLS between services\nRole-based access from the recertified role catalogue\nEncryption at rest for customer and account data\nSecurity events sent to central monitoring","architecture_decisions":"NRB-ADR-04 – 10-digit account numbers with a check digit","technical_debt":"Two legacy instances kept read-only during hypercare\nManual reconciliation steps still in spreadsheets\nSome interfaces still file based"}$j$),
  ('00000000-0000-4000-a01c-000000000005', '00000000-0000-4000-9003-000000000006', 'Data migration and quality solution architecture', 'Solution Architecture for data migration and quality on the Northbridge Bank technology programme. Owner: Priya Naidoo.', 'draft', $j${"document_reference":"NRB-SA-05","document_version":"0.9","document_owner":"Priya Naidoo","next_review_date":"2026-11-13","purpose":"Describes the solution architecture for data migration and quality on the Northbridge Bank technology programme. Cross-cutting delivery of extraction, cleansing, transformation, mock runs and reconciliation for the programme.","objectives":"Mock 2 static data loads inside the window\nMock 3 financial data reconciles\nDress rehearsal finishes with no severity-1 defect open\nTake-over and suspense accounts are zero\nEach population has a named data owner\nControl totals tie to the trial balance","scope":"Source profiling\nExtraction from both legacy instances\nCleansing at source\nTransformation rules\nMock runs\nDress rehearsal","out_of_scope":"Building the target platform\nCard scheme certification\nGeneral ledger replacement\nStaff identity directory rebuild\nA new data warehouse","assumptions":"Three mock runs and one dress rehearsal are enough\nCleansing is done in the source, not in the load\nThe file layout is plain text, one record per line\nDates travel as YYYYMMDD\nControl totals come from the final close of business","constraints":"The April 2027 weekend is fixed\nPersonal data stays in the residency region\nA population cannot load before its predecessor\nSeverity-1 defects block the next mock\nTake-over accounts must finish at zero","risks_mitigations":"Production data copied into a shared workbook – Remove samples from shared workbooks; extracts stay in the staging store\nExtract taken before close of business – Extract after close of business, checked on the mock entry list\nTake-over accounts not at zero – Reconcile take-over accounts to zero before sign-off\nUnmasked data in a lower environment – Masking applied before any refresh\nLoad window overrun – Three mocks with the window measured each time","roles_and_responsibilities":"Delivery lead – Owns delivery and the plan – Priya Naidoo\nBusiness data owner – Signs off the data population – Amina Diallo\nExecutive sponsor – Funds the work and decides escalations – Olivia Banda\nTechnical lead – Owns the technical design – Brian Otieno\nReconciliation lead – Proves control totals after each load – Olivia Banda\nFinance partner – Agrees accounting and control totals – Daniel Okafor","glossary":"Target core\tThe new core banking platform that replaces both legacy cores\nMock\tA full rehearsal load of migrated data into the target core\nHypercare\tThe four weeks of extra support after go-live\nNon-functional requirement\tA quality the solution must have, such as speed or availability\nRecovery time objective\tHow long the service may be down after a failure","appendices":"Data migration and quality delivery overview\tDelivery Overview – Data migration and quality\nData migration and quality roadmap\tNRB-RM-05\nProgramme architecture principles\tNRB-EA-PR-01","version_history":"0.1\t2026-03-23\tPriya Naidoo\tFirst draft\n0.5\t2026-05-31\tBrian Otieno\tComments from Data migration design authority\n0.9\t2026-08-11\tPriya Naidoo\tReady for review","related_documents":"NRB-RM-05 – Data migration and quality roadmap\nDelivery Overview – Data migration and quality\nNRB-ADR – Architecture decision log","solution_architect":"Brian Otieno","solution_name":"Migration extract, transform, load and reconciliation","deployment_model":"hybrid","business_requirements":"Profiling\nExtraction\nCleansing tracking\nTransformation\nMock run\nReconciliation","stakeholders":"Priya Naidoo (Delivery lead)\nAmina Diallo (Business data owner)\nOlivia Banda (Executive sponsor)\nBrian Otieno (Technical lead)\nOlivia Banda (Reconciliation lead)\nDaniel Okafor (Finance partner)","architecture_overview":"Migration extract, transform, load and reconciliation uses source extract jobs, staging area, transformation rules on the target core. Channels reach it through the API gateway; batch and file flows run through the integration platform.","components":"Source extract jobs\nStaging area\nTransformation rules\nLoad adapters\nReconciliation engine\nDefect and cleansing tracker","technology_stack":"Extract tooling for both legacy instances\nStaging database\nTransformation engine\nTarget core load utilities\nReconciliation reporting","non_functional_requirements":"Throughput – Static data load – Inside the 14-hour window\nAccuracy – Take-over and suspense accounts – Zero after reconciliation\nTraceability – Every migrated record – Traceable to its source key\nSecurity – Migration extracts – Encrypted at rest and in transit","availability_target":99,"recovery_point_objective":2,"recovery_time_objective":6,"interfaces":"Legacy instance 1 extract\nLegacy instance 2 extract\nTarget load\nControl totals\nTrial balance feed","data_flows":"Legacy core 1 to Staging (file transfer)\nLegacy core 2 to Staging (file transfer)\nStaging to Target core (batch)\nTarget core to Reconciliation engine (batch)\nFinance ledger to Reconciliation engine (file transfer)","security_controls":"Mutual TLS between services\nRole-based access from the recertified role catalogue\nEncryption at rest for customer and account data\nSecurity events sent to central monitoring","architecture_decisions":"NRB-ADR-01 – Survivor rule for duplicate customers\nNRB-ADR-07 – Three mock migrations and one dress rehearsal","technical_debt":"Two legacy instances kept read-only during hypercare\nManual reconciliation steps still in spreadsheets\nSome interfaces still file based"}$j$),
  ('00000000-0000-4000-a01c-000000000006', '00000000-0000-4000-9003-000000000006', 'Integration and interfaces solution architecture', 'Solution Architecture for integration and interfaces on the Northbridge Bank technology programme. Owner: Brian Otieno.', 'draft', $j${"document_reference":"NRB-SA-06","document_version":"0.9","document_owner":"Brian Otieno","next_review_date":"2026-11-19","purpose":"Describes the solution architecture for integration and interfaces on the Northbridge Bank technology programme. Delivery of the interfaces the target platform needs from channels, cards, finance, documents and the user store.","objectives":"Each in-scope interface has a contract, a test and an owner\nFailed messages are visible on one dashboard\nCard status cross-check agrees active cards\nTrial-balance file balances before it is used\nImage retrieval works for a mandate\nChannels no longer call the legacy cores after go-live","scope":"Internet banking interface\nMobile banking interface\nBranch teller interface\nContact centre interface\nCard status cross-check\nDocument image retrieval","out_of_scope":"A new integration platform product selection\nOpen-banking directory build\nCard scheme certification\nATM switch replacement\nPoint of sale acquiring","assumptions":"Existing channels are reused and pointed at the target\nThe card system is not migrated; only status is cross-checked\nThe finance system stays and sends a file\nCertificates can be renewed without a scheme change\nOne dashboard covers every in-scope interface","constraints":"SIT entry dates are fixed on the integration plan\nA missing certificate blocks that interface\nCard numbers are not stored on the dashboard\nThe trial-balance file is after close of business\nReplay cannot create a second payment","risks_mitigations":"Silent message loss – Every interface reports to one dashboard with alerts\nCertificate expiring in hypercare – Certificates valid through hypercare, renewed before the freeze\nReplay creating a duplicate payment – Idempotent replay keyed on the message identifier\nA channel still calling the legacy core – Remove legacy addresses and test from each channel\nUnauthenticated internal API – Mutual TLS on every internal API","roles_and_responsibilities":"Delivery lead – Owns delivery and the plan – Brian Otieno\nBusiness owner – Accepts the scope and the result – Ravi Pillai\nExecutive sponsor – Funds the work and decides escalations – Daniel Okafor\nTechnical lead – Owns the technical design – Ravi Pillai\nInterface analyst – Writes and tests interface contracts – Priya Naidoo\nTest lead – Owns test entry, exit and evidence – Catherine Mwangi","glossary":"Target core\tThe new core banking platform that replaces both legacy cores\nMock\tA full rehearsal load of migrated data into the target core\nHypercare\tThe four weeks of extra support after go-live\nNon-functional requirement\tA quality the solution must have, such as speed or availability\nRecovery time objective\tHow long the service may be down after a failure","appendices":"Integration and interfaces delivery overview\tDelivery Overview – Integration and interfaces\nIntegration and interfaces roadmap\tNRB-RM-06\nProgramme architecture principles\tNRB-EA-PR-01","version_history":"0.1\t2026-06-22\tBrian Otieno\tFirst draft\n0.5\t2026-08-30\tRavi Pillai\tComments from Integration design authority\n0.9\t2026-11-13\tBrian Otieno\tReady for review","related_documents":"NRB-RM-06 – Integration and interfaces roadmap\nDelivery Overview – Integration and interfaces\nNRB-ADR – Architecture decision log","solution_architect":"Ravi Pillai","solution_name":"Integration platform and interface estate","deployment_model":"hybrid","business_requirements":"Channel interface\nCard status cross-check\nImage retrieval\nTrial-balance file\nUser-store link\nNotification dispatch","stakeholders":"Brian Otieno (Delivery lead)\nRavi Pillai (Business owner)\nDaniel Okafor (Executive sponsor)\nRavi Pillai (Technical lead)\nPriya Naidoo (Interface analyst)\nCatherine Mwangi (Test lead)","architecture_overview":"Integration platform and interface estate uses api gateway, event broker, file transfer service on the target core. Channels reach it through the API gateway; batch and file flows run through the integration platform.","components":"API gateway\nEvent broker\nFile transfer service\nMessage transformation\nInterface monitoring dashboard\nReplay and repair","technology_stack":"Integration platform\nAPI gateway\nEvent broker\nManaged file transfer\nMonitoring and alerting service","non_functional_requirements":"Reliability – Message delivery – No silent loss; every failure visible\nRecovery – Failed message repair – Under 30 minutes\nAvailability – Integration platform – 99.95% monthly\nSecurity – Service-to-service calls – Mutual TLS on every internal call","availability_target":99.95,"recovery_point_objective":0.25,"recovery_time_objective":1,"interfaces":"Card status cross-check\nFinance trial balance\nDocument image retrieval\nDigital user store link\nNotification dispatch","data_flows":"Card platform to Target core (file transfer)\nTarget core to Finance ledger (file transfer)\nObject store to Channels (real-time api)\nIdentity provider to Target core (real-time api)\nTarget core to Notification service (event streaming)","security_controls":"Mutual TLS between services\nRole-based access from the recertified role catalogue\nEncryption at rest for customer and account data\nSecurity events sent to central monitoring","architecture_decisions":"NRB-ADR-09 – One dashboard for every interface\nNRB-ADR-02 – Store mandate and signature images in a file store","technical_debt":"Two legacy instances kept read-only during hypercare\nManual reconciliation steps still in spreadsheets\nSome interfaces still file based"}$j$),
  ('00000000-0000-4000-a01c-000000000007', '00000000-0000-4000-9003-000000000006', 'Cybersecurity and access solution architecture', 'Solution Architecture for cybersecurity and access on the Northbridge Bank technology programme. Owner: Nadia Rahman.', 'draft', $j${"document_reference":"NRB-SA-07","document_version":"0.9","document_owner":"Nadia Rahman","next_review_date":"2026-11-24","purpose":"Describes the solution architecture for cybersecurity and access on the Northbridge Bank technology programme. Delivery of user access, recertification and the security controls required before go-live. Currently on hold.","objectives":"Every loaded user has a recertified entitlement\nLeavers are absent from the load\nPrivileged access is listed and approved\nStaff can sign in on day one\nLogging meets the agreed control\nAudit can see who approved each role","scope":"Bank user profiles\nUser groups and roles\nLine-manager recertification\nPrivileged access\nJoiner, mover and leaver handling\nAuthentication for staff","out_of_scope":"Customer authentication redesign\nA new identity product selection\nBuilding access\nCard PIN platform\nEndpoint replacement","assumptions":"Line managers recertify their own staff\nThe identity directory is a source, not a system being replaced\nPrivileged access is a separate list\nLeavers are removed in the source before extract\nCustomer sign-in is owned by the channels delivery","constraints":"User load cannot start before recertification\nThe freeze date does not move for this workstream alone\nPrivileged access requires two approvers\nPersonal data in access logs follows the retention schedule\nA leaver cannot be loaded","risks_mitigations":"Leaver loaded into the target platform – Leaver extract applied before every user load\nShared identity created to save time – Named identities only; shared accounts refused\nPrivileged access copied unchanged – Privileged roles rebuilt and approved, not copied\nLogging weaker than the agreed control – Logging checked against the control before go-live\nSame-day revocation not possible in hypercare – Same-day revocation process tested with the service desk","roles_and_responsibilities":"Delivery lead – Owns delivery and the plan – Nadia Rahman\nBusiness owner – Accepts the scope and the result – Daniel Okafor\nExecutive sponsor – Funds the work and decides escalations – Grace Moyo\nTechnical lead – Owns the technical design – Nadia Rahman\nAccess analyst – Builds the role catalogue and access reviews – Ravi Pillai\nAudit partner – Checks evidence for audit – Olivia Banda","glossary":"Target core\tThe new core banking platform that replaces both legacy cores\nMock\tA full rehearsal load of migrated data into the target core\nHypercare\tThe four weeks of extra support after go-live\nNon-functional requirement\tA quality the solution must have, such as speed or availability\nRecovery time objective\tHow long the service may be down after a failure","appendices":"Cybersecurity and access delivery overview\tDelivery Overview – Cybersecurity and access\nCybersecurity and access roadmap\tNRB-RM-07\nProgramme architecture principles\tNRB-EA-PR-01","version_history":"0.1\t2026-07-06\tNadia Rahman\tFirst draft\n0.5\t2026-09-13\tNadia Rahman\tComments from Security design authority\n0.9\t2026-11-30\tNadia Rahman\tReady for review","related_documents":"NRB-RM-07 – Cybersecurity and access roadmap\nDelivery Overview – Cybersecurity and access\nNRB-ADR – Architecture decision log","solution_architect":"Nadia Rahman","solution_name":"Staff identity, access and security logging","deployment_model":"hybrid","business_requirements":"User profile load\nRole recertification\nPrivileged access list\nLeaver removal\nStaff sign-in\nSecurity logging","stakeholders":"Nadia Rahman (Delivery lead)\nDaniel Okafor (Business owner)\nGrace Moyo (Executive sponsor)\nNadia Rahman (Technical lead)\nRavi Pillai (Access analyst)\nOlivia Banda (Audit partner)","architecture_overview":"Staff identity, access and security logging uses identity provider, role catalogue, recertification workflow on the target core. Channels reach it through the API gateway; batch and file flows run through the integration platform.","components":"Identity provider\nRole catalogue\nRecertification workflow\nPrivileged access vault\nSecurity log collection\nJoiner, mover and leaver feed","technology_stack":"Identity provider\nPrivileged access vault\nSecurity information and event monitoring\nDirectory service\nAccess recertification tool","non_functional_requirements":"Security – Leaver revocation – Same day\nAuditability – Role approvals – Approver recorded for every role\nAvailability – Staff sign-in – 99.9% in business hours\nLogging – Security events – Kept 12 months, searchable 90 days","availability_target":99.9,"recovery_point_objective":1,"recovery_time_objective":4,"interfaces":"Joiner, mover and leaver feed\nRole provisioning\nSecurity events\nRecertification evidence\nPrivileged session logs","data_flows":"HR system to Identity provider (batch)\nIdentity provider to Target core (real-time api)\nTarget core to Security monitoring (event streaming)\nRecertification tool to Audit store (batch)\nAccess vault to Security monitoring (event streaming)","security_controls":"Mutual TLS between services\nRole-based access from the recertified role catalogue\nEncryption at rest for customer and account data\nSecurity events sent to central monitoring","architecture_decisions":"NRB-ADR-08 – Masked production-like data in lower environments","technical_debt":"Two legacy instances kept read-only during hypercare\nManual reconciliation steps still in spreadsheets\nSome interfaces still file based"}$j$),
  ('00000000-0000-4000-a01c-000000000008', '00000000-0000-4000-9003-000000000006', 'Environments and release solution architecture', 'Solution Architecture for environments and release on the Northbridge Bank technology programme. Owner: Ravi Pillai.', 'draft', $j${"document_reference":"NRB-SA-08","document_version":"0.9","document_owner":"Ravi Pillai","next_review_date":"2026-11-18","purpose":"Describes the solution architecture for environments and release on the Northbridge Bank technology programme. Delivery of the environment path from development through dress rehearsal, production and recovery, and the release calendar that uses it.","objectives":"Every test stage has a booked environment\nDress rehearsal uses a production-like path\nRefresh is requested and logged\nThe release calendar is the only source of release dates\nRecovery is restored and checked before go-live\nNo two mocks share an environment","scope":"Development environment\nTest environment\nSystem integration environment\nUser acceptance environment\nPre-production\nProduction cutover runbook","out_of_scope":"A new data centre build\nEnd-user device replacement\nNetwork redesign\nCloud provider selection\nProduction support model","assumptions":"Existing hosting is reused\nProduction-like data is masked except in dress rehearsal under approval\nOne calendar is enough\nRecovery is a restore test, not a second data centre project\nTeams will book if the booking is easier than asking in a chat","constraints":"The dress rehearsal date is fixed once booked\nMasked data is the default\nProduction access is named people only\nTwo mocks cannot share an environment\nA refresh during execution is refused","risks_mitigations":"Refresh using unmasked production data – Masking approved and applied before refresh\nTwo mocks booked on one environment – One booking register, mandatory from SIT\nRecovery backup that cannot be restored – Recovery restore rehearsed before go-live\nProduction access wider than the named list – Named production access list reviewed monthly\nConfiguration drift between environments – One configuration baseline promoted through every environment","roles_and_responsibilities":"Delivery lead – Owns delivery and the plan – Ravi Pillai\nBusiness owner – Accepts the scope and the result – Brian Otieno\nExecutive sponsor – Funds the work and decides escalations – Daniel Okafor\nTechnical lead – Owns the technical design – Ravi Pillai\nEnvironment analyst – Books and refreshes environments – Priya Naidoo\nRelease manager – Owns the release calendar – Linda Zhou","glossary":"Target core\tThe new core banking platform that replaces both legacy cores\nMock\tA full rehearsal load of migrated data into the target core\nHypercare\tThe four weeks of extra support after go-live\nNon-functional requirement\tA quality the solution must have, such as speed or availability\nRecovery time objective\tHow long the service may be down after a failure","appendices":"Environments and release delivery overview\tDelivery Overview – Environments and release\nEnvironments and release roadmap\tNRB-RM-08\nProgramme architecture principles\tNRB-EA-PR-01","version_history":"0.1\t2026-04-06\tRavi Pillai\tFirst draft\n0.5\t2026-06-14\tRavi Pillai\tComments from Environment and release forum\n0.9\t2026-09-03\tRavi Pillai\tReady for review","related_documents":"NRB-RM-08 – Environments and release roadmap\nDelivery Overview – Environments and release\nNRB-ADR – Architecture decision log","solution_architect":"Ravi Pillai","solution_name":"Environment path and release calendar","deployment_model":"hybrid","business_requirements":"Environment booking\nData refresh\nRelease calendar\nMasked data\nDress rehearsal path\nProduction runbook","stakeholders":"Ravi Pillai (Delivery lead)\nBrian Otieno (Business owner)\nDaniel Okafor (Executive sponsor)\nRavi Pillai (Technical lead)\nPriya Naidoo (Environment analyst)\nLinda Zhou (Release manager)","architecture_overview":"Environment path and release calendar uses environment booking, masked data refresh, release calendar on the target core. Channels reach it through the API gateway; batch and file flows run through the integration platform.","components":"Environment booking\nMasked data refresh\nRelease calendar\nDeployment pipeline\nRecovery environment\nProduction runbook","technology_stack":"Deployment pipeline\nConfiguration management\nData masking tooling\nEnvironment booking register\nBackup and restore service","non_functional_requirements":"Recovery – Recovery environment – Restored and checked before go-live\nAvailability – Pre-production – 99% during dress rehearsal\nSecurity – Lower environments – Masked data only\nConsistency – Configuration – Same baseline from SIT to production","availability_target":99,"recovery_point_objective":4,"recovery_time_objective":8,"interfaces":"Masked data refresh\nDeployment events\nBackup copy\nBooking feed\nConfiguration baseline","data_flows":"Production to Test environments (replication)\nPipeline to Release calendar (event streaming)\nProduction to Recovery environment (replication)\nBooking register to Programme dashboard (batch)\nConfiguration repository to All environments (batch)","security_controls":"Mutual TLS between services\nRole-based access from the recertified role catalogue\nEncryption at rest for customer and account data\nSecurity events sent to central monitoring","architecture_decisions":"NRB-ADR-07 – Three mock migrations and one dress rehearsal\nNRB-ADR-08 – Masked production-like data in lower environments","technical_debt":"Two legacy instances kept read-only during hypercare\nManual reconciliation steps still in spreadsheets\nSome interfaces still file based"}$j$),
  ('00000000-0000-4000-a01c-000000000009', '00000000-0000-4000-9003-000000000006', 'Operational readiness and hypercare solution architecture', 'Solution Architecture for operational readiness and hypercare on the Northbridge Bank technology programme. Owner: Linda Zhou.', 'draft', $j${"document_reference":"NRB-SA-09","document_version":"0.9","document_owner":"Linda Zhou","next_review_date":"2026-11-20","purpose":"Describes the solution architecture for operational readiness and hypercare on the Northbridge Bank technology programme. Delivery of the support model, runbooks, monitoring handover and the hypercare period after go-live.","objectives":"Every cutover step has a runbook someone has walked through\nHypercare shifts are named, including nights\nThe daily bridge has an agenda and a chair\nSeverity scale matches the defect scale\nMonitoring alerts reach the roster\nKnown errors are written down before go-live","scope":"Support model\nRunbooks for the cutover weekend\nHypercare roster\nDaily hypercare bridge\nSeverity scale for hypercare\nMonitoring handover","out_of_scope":"A new service-desk product\nBranch refurbishment\nA 24-hour contact centre build\nVendor contract renegotiation\nProduction data centre build","assumptions":"Hypercare lasts four weeks\nThe existing service desk is the front door\nRunbooks are steps with an expected result\nNight shifts are required for the first week only\nMonitoring is handed over, not rebuilt","constraints":"Hypercare cannot be staffed by unnamed roles\nA runbook that has not been walked through does not count\nThe first week has night cover\nExit criteria are set before go-live\nThe bridge is every business day in hypercare","risks_mitigations":"Alerts going to a mailbox nobody reads – Alerts routed to the named roster, not a mailbox\nNight shifts left unnamed – Name every shift, including nights, before the dress rehearsal\nRunbooks never walked through – Walk through every runbook in the dress rehearsal\nKnown errors found by customers – Publish the known-error list before go-live\nSeverity 1 response slower than 30 minutes – Severity 1 bridge opened within 15 minutes","roles_and_responsibilities":"Delivery lead – Owns delivery and the plan – Linda Zhou\nBusiness owner – Accepts the scope and the result – Catherine Mwangi\nExecutive sponsor – Funds the work and decides escalations – Grace Moyo\nTechnical lead – Owns the technical design – Ahmed Hassan\nService desk lead – Prepares the service desk for go-live – Brian Otieno\nOperations lead – Owns run procedures after go-live – Ravi Pillai","glossary":"Target core\tThe new core banking platform that replaces both legacy cores\nMock\tA full rehearsal load of migrated data into the target core\nHypercare\tThe four weeks of extra support after go-live\nNon-functional requirement\tA quality the solution must have, such as speed or availability\nRecovery time objective\tHow long the service may be down after a failure","appendices":"Operational readiness and hypercare delivery overview\tDelivery Overview – Operational readiness and hypercare\nOperational readiness and hypercare roadmap\tNRB-RM-09\nProgramme architecture principles\tNRB-EA-PR-01","version_history":"0.1\t2026-09-22\tLinda Zhou\tFirst draft\n0.5\t2026-11-30\tAhmed Hassan\tComments from Operational readiness forum\n0.9\t2027-02-22\tLinda Zhou\tReady for review","related_documents":"NRB-RM-09 – Operational readiness and hypercare roadmap\nDelivery Overview – Operational readiness and hypercare\nNRB-ADR – Architecture decision log","solution_architect":"Ahmed Hassan","solution_name":"Support model, monitoring and hypercare","deployment_model":"hybrid","business_requirements":"Support model\nCutover runbook\nHypercare roster\nDaily bridge\nSeverity handling\nMonitoring handover","stakeholders":"Linda Zhou (Delivery lead)\nCatherine Mwangi (Business owner)\nGrace Moyo (Executive sponsor)\nAhmed Hassan (Technical lead)\nBrian Otieno (Service desk lead)\nRavi Pillai (Operations lead)","architecture_overview":"Support model, monitoring and hypercare uses service desk routing, monitoring handover, hypercare bridge on the target core. Channels reach it through the API gateway; batch and file flows run through the integration platform.","components":"Service desk routing\nMonitoring handover\nHypercare bridge\nKnown-error list\nRunbook library\nSeverity scale","technology_stack":"Service management tool\nMonitoring and alerting service\nCollaboration bridge\nKnowledge base\nOn-call roster","non_functional_requirements":"Responsiveness – Severity 1 response – Within 30 minutes\nCoverage – Hypercare roster – Every shift named, including nights\nAvailability – Service desk – 24 hours during hypercare\nExit – Hypercare exit criteria – Numeric and agreed with the sponsor","availability_target":99.5,"recovery_point_objective":4,"recovery_time_objective":4,"interfaces":"Alert routing\nIncident updates\nKnown-error publishing\nRoster feed\nStatus page","data_flows":"Monitoring to Service management (event streaming)\nService management to Hypercare bridge (real-time api)\nKnowledge base to Service desk (batch)\nRoster store to Alert routing (batch)\nService management to Staff intranet (real-time api)","security_controls":"Mutual TLS between services\nRole-based access from the recertified role catalogue\nEncryption at rest for customer and account data\nSecurity events sent to central monitoring","architecture_decisions":"NRB-ADR-09 – One dashboard for every interface","technical_debt":"Two legacy instances kept read-only during hypercare\nManual reconciliation steps still in spreadsheets\nSome interfaces still file based"}$j$),
  ('00000000-0000-4000-a01c-000000000010', '00000000-0000-4000-9003-000000000006', 'Regulatory reporting solution architecture', 'Solution Architecture for regulatory reporting. Superseded: the reporting workstream closed on 30 September 2026; kept for reference.', 'superseded', $j${"document_reference":"NRB-SA-10","document_version":"1.0","document_owner":"Olivia Banda","next_review_date":"2027-03-31","purpose":"Describes the solution architecture for regulatory reporting on the Northbridge Bank technology programme. Completed delivery of the report-line mapping that lets finance keep the existing reporting tool across the migration.","objectives":"Every report line used in the last year has a mapped source\nThe mock cross-check agreed\nDifferences go to the agreed difference account\nThe financial controller has signed\nFinance did not change tool\nEvidence is in the go-live pack","scope":"Report-line map from the trial balance\nCurrency and company mapping\nFirst mock cross-check\nEvidence pack for finance\nNamed owner per report family\nDifference account treatment","out_of_scope":"A new reporting tool\nPrudential return redesign\nTax engine replacement\nManagement information warehouse\nBoard pack redesign","assumptions":"The finance system stays\nThe chart of accounts does not change for go-live\nLast year of report lines is the scope\nDifferences use account 14918 as already agreed for the journals\nThe controller is the signer","constraints":"No new reporting tool\nThe map cannot drop a line used in the last year\nDifferences have one account\nSign-off is the controller, not the project\nThe guide stays short","risks_mitigations":"A report line missed in the map – Check every report line used in the last year against the map\nA mapped line changing meaning – Reopen rule limited to the affected report\nThe difference account used for something else – Account 14918 reserved for differences only\nCustomer-level data in the evidence pack – Remove customer-level rows from the pack\nController signature on the wrong version – Controller signs the version number on the pack","roles_and_responsibilities":"Delivery lead – Owns delivery and the plan – Olivia Banda\nBusiness owner – Accepts the scope and the result – Olivia Banda\nExecutive sponsor – Funds the work and decides escalations – Grace Moyo\nTechnical lead – Owns the technical design – Priya Naidoo\nFinance analyst – Maps ledger accounts and report lines – Daniel Okafor\nMapping analyst – Maintains the report-line map – Amina Diallo","glossary":"Target core\tThe new core banking platform that replaces both legacy cores\nMock\tA full rehearsal load of migrated data into the target core\nHypercare\tThe four weeks of extra support after go-live\nNon-functional requirement\tA quality the solution must have, such as speed or availability\nRecovery time objective\tHow long the service may be down after a failure","appendices":"Regulatory reporting delivery overview\tDelivery Overview – Regulatory reporting\nRegulatory reporting roadmap\tNRB-RM-10\nProgramme architecture principles\tNRB-EA-PR-01","version_history":"0.1\t2026-02-23\tOlivia Banda\tFirst draft\n0.5\t2026-05-03\tPriya Naidoo\tComments from Finance and regulatory forum\n1.0\t2026-09-28\tOlivia Banda\tFinal; workstream closed","related_documents":"NRB-RM-10 – Regulatory reporting roadmap\nDelivery Overview – Regulatory reporting\nNRB-ADR – Architecture decision log","solution_architect":"Priya Naidoo","solution_name":"Report-line mapping for the existing reporting tool","deployment_model":"on_premises","business_requirements":"Report-line map\nCurrency mapping\nCompany mapping\nMock cross-check\nDifference account\nEvidence pack","stakeholders":"Olivia Banda (Delivery lead)\nOlivia Banda (Business owner)\nGrace Moyo (Executive sponsor)\nPriya Naidoo (Technical lead)\nDaniel Okafor (Finance analyst)\nAmina Diallo (Mapping analyst)","architecture_overview":"Report-line mapping for the existing reporting tool uses report-line map, currency mapping, company mapping on the target core. Channels reach it through the API gateway; batch and file flows run through the integration platform.","components":"Report-line map\nCurrency mapping\nCompany mapping\nDifference account\nEvidence pack\nReopen rule","technology_stack":"Existing reporting tool\nFinance ledger\nMapping workbook\nEvidence store\nReconciliation reporting","non_functional_requirements":"Completeness – Report lines used in the last year – Every line mapped\nAccuracy – Mock cross-check – Agrees\nRetention – Evidence pack – Kept 7 years\nChange control – Mapped lines – Reopen only the affected report","availability_target":99,"recovery_point_objective":24,"recovery_time_objective":24,"interfaces":"Trial balance\nReport-line lookup\nDifference postings\nEvidence filing\nMock cross-check","data_flows":"Target core to Finance ledger (file transfer)\nMapping workbook to Reporting tool (batch)\nFinance ledger to Difference account 14918 (batch)\nReporting tool to Evidence store (batch)\nMigration staging to Reporting tool (batch)","security_controls":"Mutual TLS between services\nRole-based access from the recertified role catalogue\nEncryption at rest for customer and account data\nSecurity events sent to central monitoring","architecture_decisions":"NRB-ADR-07 – Three mock migrations and one dress rehearsal","technical_debt":"Two legacy instances kept read-only during hypercare\nManual reconciliation steps still in spreadsheets\nSome interfaces still file based"}$j$),
  ('00000000-0000-4000-a01d-000000000001', '00000000-0000-4000-9003-000000000007', 'Customer and digital channels application architecture', 'Application Architecture for customer and digital channels on the Northbridge Bank technology programme. Owner: Amina Diallo.', 'draft', $j${"document_reference":"NRB-AA-01","document_version":"0.9","document_owner":"Amina Diallo","next_review_date":"2026-11-16","purpose":"Describes the application architecture for customer and digital channels on the Northbridge Bank technology programme. Delivery of customer master data and the internet, mobile and branch channels for the Northbridge Bank technology programme.","objectives":"Every active customer has one surviving customer number\nAddress completeness at or above 85%\nInternet and mobile users can sign in on day one\nDuplicate customers reduced below 1%\nMandate images linked to the surviving customer\nBranch search returns the customer in under 3 seconds","scope":"Retail and SME customer master\nCorporate customer master from the second legacy instance\nInternet banking registration\nMobile banking registration\nBranch teller customer search\nContact centre customer view","out_of_scope":"Card plastic personalisation\nMarketing campaign tool\nLoyalty scheme\nInsurance product origination\nWealth advisory portal","assumptions":"Both legacy instances are profiled before Mock 2\nThe surviving record is the one with the most complete KYC data\nCustomers accept a new customer number where numbers clash\nBranch staff are trained before the dress rehearsal\nStatement templates are approved by the business","constraints":"Customer numbers must be unique across both legacy instances\nKYC fields are mandatory before a customer can be loaded\nAddress completeness target is 85%\nImages must be linked before the channel is opened\nThe load window is the weekend of 10–12 April 2027","risks_mitigations":"Account takeover through weak registration checks – Two-factor registration and device binding\nDuplicate customer merged onto the wrong survivor – Survivor rule signed by the business data owner and sample-checked\nMandate images exposed through a direct link – Images served only through the authenticated retrieval API\nCredential stuffing on internet banking sign-in – Rate limits and lock-out on sign-in\nPersonal data copied into test environments – Masked data only in lower environments","roles_and_responsibilities":"Delivery lead – Owns delivery and the plan – Amina Diallo\nBusiness owner – Accepts the scope and the result – Nomvula Khumalo\nExecutive sponsor – Funds the work and decides escalations – Grace Moyo\nTechnical lead – Owns the technical design – Ravi Pillai\nData analyst – Profiles and maps the data – Priya Naidoo\nChannel analyst – Designs channel journeys and entitlements – Brian Otieno","glossary":"Target core\tThe new core banking platform that replaces both legacy cores\nMock\tA full rehearsal load of migrated data into the target core\nHypercare\tThe four weeks of extra support after go-live\nComponent\tA deployable part of an application with one clear job\nAPI\tA published way for one application to call another","appendices":"Customer and digital channels delivery overview\tDelivery Overview – Customer and digital channels\nCustomer and digital channels roadmap\tNRB-RM-01\nProgramme architecture principles\tNRB-EA-PR-01","version_history":"0.1\t2026-04-27\tAmina Diallo\tFirst draft\n0.5\t2026-07-05\tRavi Pillai\tComments from Channels steering group\n0.9\t2026-09-03\tAmina Diallo\tReady for review","related_documents":"NRB-RM-01 – Customer and digital channels roadmap\nDelivery Overview – Customer and digital channels\nNRB-ADR – Architecture decision log","application_architect":"Ravi Pillai","architecture_style":"modular_monolith","applications_in_scope":"Legacy core – retail and SME instance\nLegacy core – corporate instance\nInternet banking\nMobile banking\nBranch teller\nContact centre desktop","application_components":"Customer master service\nDeduplication and survivorship engine\nInternet banking front end\nMobile banking back end\nBranch customer search\nContact centre customer view","design_patterns":"Layered services\nAnti-corruption layer towards the legacy cores\nRetry with back-off on outbound calls","technology_stack":"Target core banking platform – customer module\nAPI gateway\nIdentity provider for customer sign-in\nRelational database for the customer master\nObject store for mandate images","apis":"Customer search API\nCustomer profile API\nRegistration API\nMandate image retrieval API\nPreference update API","dependencies":"Customer deduplication rules signed off\nKYC repository extract granted\nDocument image storage decision\nTarget customer products configured\n8-digit numbering agreed","deployment_model":"hybrid","hosting_environments":["development","test","sit","uat","pre_production","production","dr"],"scalability_approach":"Scale out the stateless services behind the API gateway; size the database for 600 customer searches per minute at branch peak.","non_functional_requirements":"Branch customer search response: Under 3 seconds at peak\nInternet and mobile sign-in: 99.9% monthly\nAddress completeness: 85% or higher\nStrong customer sign-in: Two factors on every new device"}$j$),
  ('00000000-0000-4000-a01d-000000000002', '00000000-0000-4000-9003-000000000007', 'Payments and transfers application architecture', 'Application Architecture for payments and transfers on the Northbridge Bank technology programme. Owner: Ahmed Hassan.', 'draft', $j${"document_reference":"NRB-AA-02","document_version":"0.9","document_owner":"Ahmed Hassan","next_review_date":"2026-11-18","purpose":"Describes the application architecture for payments and transfers on the Northbridge Bank technology programme. Delivery of domestic payments, standing orders and internal transfers onto the target platform.","objectives":"Every active standing order is recreated before go-live\nSettlement totals agree to the cent\nReturned payments land on the repair queue\nChannel limits match the signed matrix\nNo duplicate payment on the cutover weekend\nCut-off calendar loaded for the next 18 months","scope":"Domestic credit transfers\nInternal account transfers\nStanding orders\nFuture-dated payments\nPayment limits by channel\nSettlement timetable","out_of_scope":"Card authorisation\nATM cash\nCheque clearing replacement\nCross-border correspondent banking rebuild\nCash-in-transit","assumptions":"The scheme timetable does not change before go-live\nStanding orders are recreated, not replayed from history\nBoth legacy instances use the same value-date rule\nPayment limits are signed by the business before UAT\nThe repair queue is staffed for hypercare","constraints":"Scheme cut-off cannot move\nSettlement must balance on the night\nStanding orders with an end date in the past are excluded\nDual control stays on the repair queue\nPayment files are not accepted during the freeze","risks_mitigations":"Duplicate payment on the cutover weekend – Idempotent posting keyed on the payment reference\nChannel limits looser than the signed matrix – Load limits from the signed matrix and test every band\nScheme certificate expiry – Certificate inventory with 60-day expiry alerts\nTampered payment file in transit – Signed and encrypted payment files\nRepair actions without dual control – Dual control enforced on every repair action","roles_and_responsibilities":"Delivery lead – Owns delivery and the plan – Ahmed Hassan\nBusiness owner – Accepts the scope and the result – Catherine Mwangi\nExecutive sponsor – Funds the work and decides escalations – Daniel Okafor\nTechnical lead – Owns the technical design – Brian Otieno\nSettlement analyst – Designs settlement and reconciliation – Olivia Banda\nTest lead – Owns test entry, exit and evidence – Priya Naidoo","glossary":"Target core\tThe new core banking platform that replaces both legacy cores\nMock\tA full rehearsal load of migrated data into the target core\nHypercare\tThe four weeks of extra support after go-live\nComponent\tA deployable part of an application with one clear job\nAPI\tA published way for one application to call another","appendices":"Payments and transfers delivery overview\tDelivery Overview – Payments and transfers\nPayments and transfers roadmap\tNRB-RM-02\nProgramme architecture principles\tNRB-EA-PR-01","version_history":"0.1\t2026-05-25\tAhmed Hassan\tFirst draft\n0.5\t2026-08-02\tBrian Otieno\tComments from Payments working group\n0.9\t2026-10-04\tAhmed Hassan\tReady for review","related_documents":"NRB-RM-02 – Payments and transfers roadmap\nDelivery Overview – Payments and transfers\nNRB-ADR – Architecture decision log","application_architect":"Brian Otieno","architecture_style":"event_driven","applications_in_scope":"Legacy core – both instances\nTarget payments engine\nScheme gateway\nChannel payment screens\nStanding order store\nRepair workflow","application_components":"Payment initiation service\nStanding order scheduler\nLimit check service\nSettlement posting\nRepair queue\nScheme gateway adapter","design_patterns":"Publish and subscribe for status events\nIdempotent consumers\nOutbox for reliable events","technology_stack":"Target core banking platform – payments module\nEvent broker\nScheme gateway\nRelational database for payment state\nIntegration platform","apis":"Payment initiation API\nStanding order API\nLimit check API\nPayment status API\nRepair action API","dependencies":"Customer and account numbers mapped\nScheme gateway certificate renewed\nLimit matrix signed\nSettlement accounts configured\nCut-off calendar agreed with operations","deployment_model":"hybrid","hosting_environments":["development","test","sit","uat","pre_production","production","dr"],"scalability_approach":"Scale out the stateless services behind the API gateway; size the database for 250 payments per second at month-end peak.","non_functional_requirements":"Payment initiation: Under 2 seconds end to end\nPayment initiation: 99.95% monthly\nSettlement totals: Agree to the cent every cycle\nPayment state: No lost or duplicated payment after failover"}$j$),
  ('00000000-0000-4000-a01d-000000000003', '00000000-0000-4000-9003-000000000007', 'Lending, limits and collateral application architecture', 'Application Architecture for lending, limits and collateral on the Northbridge Bank technology programme. Owner: Joy Akinyi.', 'draft', $j${"document_reference":"NRB-AA-03","document_version":"0.9","document_owner":"Joy Akinyi","next_review_date":"2026-11-11","purpose":"Describes the application architecture for lending, limits and collateral on the Northbridge Bank technology programme. Delivery of loans, limits and collateral, including overdue bills and the expired-limit rule.","objectives":"Every live loan has an arrangement, a balance and a schedule\nAgeing continues from the legacy past-due date\nExpired limits follow the signed rule\nCollateral is linked before the loan is loaded\nOne repayment account per customer per currency\nTake-over accounts return to zero","scope":"Retail loan arrangements\nCorporate loan arrangements\nOverdue and due bills\nAccrued interest on loans\nLimit records\nExpired limits still linked to a contract","out_of_scope":"New scorecard build\nDebt collection agency files\nSecuritisation\nSyndicated loan agency\nTrade finance instruments","assumptions":"Schedules are regenerated from the migrated frequency\nThe expired-limit rule is expiry plus one day, with the original date kept\nOne liquidation account is allowed per customer per currency\nCollateral rights load before collateral items\nPast-due date becomes the bill date","constraints":"A loan cannot load before its customer and account\nCollateral cannot load before its right\nAgeing must not reset to zero\nExpired limits cannot be dropped while a contract is live\nTake-over accounts must be zero after reconciliation","risks_mitigations":"Expired limit left securing a live contract – Expired-limit rule signed and every case on a credit review queue\nCollateral loaded before its right and rejected – Load rights before items, rehearsed in Mock 2\nAccrual counted twice after migration – Accrual value date set to the migration date\nUnauthorised limit override – Limit overrides need a second approver\nCredit data exposed to non-credit staff – Credit screens limited to credit roles","roles_and_responsibilities":"Delivery lead – Owns delivery and the plan – Joy Akinyi\nBusiness owner – Accepts the scope and the result – Daniel Okafor\nExecutive sponsor – Funds the work and decides escalations – Grace Moyo\nTechnical lead – Owns the technical design – Priya Naidoo\nCredit analyst – Defines lending and limit rules – Ahmed Hassan\nCollateral analyst – Maps collateral rights and items – Linda Zhou","glossary":"Target core\tThe new core banking platform that replaces both legacy cores\nMock\tA full rehearsal load of migrated data into the target core\nHypercare\tThe four weeks of extra support after go-live\nComponent\tA deployable part of an application with one clear job\nAPI\tA published way for one application to call another","appendices":"Lending, limits and collateral delivery overview\tDelivery Overview – Lending, limits and collateral\nLending, limits and collateral roadmap\tNRB-RM-03\nProgramme architecture principles\tNRB-EA-PR-01","version_history":"0.1\t2026-06-08\tJoy Akinyi\tFirst draft\n0.5\t2026-08-16\tPriya Naidoo\tComments from Credit design authority\n0.9\t2026-10-21\tJoy Akinyi\tReady for review","related_documents":"NRB-RM-03 – Lending, limits and collateral roadmap\nDelivery Overview – Lending, limits and collateral\nNRB-ADR – Architecture decision log","application_architect":"Priya Naidoo","architecture_style":"layered","applications_in_scope":"Legacy core – both instances\nTarget lending module\nLimits service\nCollateral register\nCredit workflow\nTake-over accounts","application_components":"Loan arrangement service\nRepayment schedule engine\nLimit hierarchy\nCollateral register\nAgeing and arrears\nCredit enquiry","design_patterns":"Layered services\nAnti-corruption layer towards the legacy cores\nRetry with back-off on outbound calls","technology_stack":"Target core banking platform – lending module\nCollateral register\nRelational database for limits\nIntegration platform\nReporting database","apis":"Loan enquiry API\nLimit utilisation API\nCollateral link API\nRepayment schedule API\nArrears status API","dependencies":"Customer numbers mapped\nExpired-limit rule signed by credit\nRepayment account rule signed\nCollateral identifier format agreed\nTake-over accounts opened","deployment_model":"on_premises","hosting_environments":["development","test","sit","uat","pre_production","production","dr"],"scalability_approach":"Scale out the stateless services behind the API gateway; size the database for 180,000 loans scheduled overnight.","non_functional_requirements":"Loan balance after migration: Agrees to legacy to the cent\nOvernight schedule run: Completes inside 3 hours\nCredit enquiry: 99.5% in business hours\nLimit changes: Every change has an approver"}$j$),
  ('00000000-0000-4000-a01d-000000000004', '00000000-0000-4000-9003-000000000007', 'Deposits and accounts application architecture', 'Application Architecture for deposits and accounts on the Northbridge Bank technology programme. Owner: Catherine Mwangi.', 'draft', $j${"document_reference":"NRB-AA-04","document_version":"0.9","document_owner":"Catherine Mwangi","next_review_date":"2026-11-17","purpose":"Describes the application architecture for deposits and accounts on the Northbridge Bank technology programme. Delivery of current accounts, savings and term deposits, including balances and accruals.","objectives":"Every open account has a product, a balance and an owner\nInstance 2 account numbers are kept as alternate keys\nDormant accounts over five years are closed or transferred\nMatured deposits no longer carry a balance at the freeze\nRestrictions match the legacy narrative\nStatement frequency is remapped","scope":"Current accounts\nSavings accounts\nTerm deposits\nDeposit balances and accruals\nDormant accounts over five years\nMatured deposits that still hold a balance","out_of_scope":"Safe custody\nNew savings product launch\nPrize-linked savings\nChildren account campaign\nBrokerage cash accounts","assumptions":"Three legacy current-account products become one target product\nInstance 2 numbers become 10 digits with a check digit\nDormant means no customer-initiated transaction for five years\nUnclaimed balances move under the existing regulation\nMatured deposits are paid out or rolled, not migrated as running","constraints":"No account closures in the week before go-live\nA zero-balance account marked for closure is excluded\nAlternate keys are mandatory for instance 2\nAccrual value date cannot be the original accrual date\nProduct mapping cannot change after Mock 2 without a new approval","risks_mitigations":"Matured deposit still carrying a balance at the freeze – Pay out or roll matured deposits before the freeze\nAccount numbers clashing across the two instances – 10-digit numbers with check digit and alternate keys\nRestriction narrative dropped in migration – Sample-check restriction narratives after each mock\nStatement sent to the wrong address – Address taken from the survivor customer record\nInterest accrued twice – Accrual reconciled by product after Mock 3","roles_and_responsibilities":"Delivery lead – Owns delivery and the plan – Catherine Mwangi\nBusiness owner – Accepts the scope and the result – Nomvula Khumalo\nExecutive sponsor – Funds the work and decides escalations – Olivia Banda\nTechnical lead – Owns the technical design – Brian Otieno\nProduct analyst – Maps products to the target core – Amina Diallo\nFinance partner – Agrees accounting and control totals – Daniel Okafor","glossary":"Target core\tThe new core banking platform that replaces both legacy cores\nMock\tA full rehearsal load of migrated data into the target core\nHypercare\tThe four weeks of extra support after go-live\nComponent\tA deployable part of an application with one clear job\nAPI\tA published way for one application to call another","appendices":"Deposits and accounts delivery overview\tDelivery Overview – Deposits and accounts\nDeposits and accounts roadmap\tNRB-RM-04\nProgramme architecture principles\tNRB-EA-PR-01","version_history":"0.1\t2026-05-11\tCatherine Mwangi\tFirst draft\n0.5\t2026-07-19\tBrian Otieno\tComments from Deposits product forum\n0.9\t2026-09-26\tCatherine Mwangi\tReady for review","related_documents":"NRB-RM-04 – Deposits and accounts roadmap\nDelivery Overview – Deposits and accounts\nNRB-ADR – Architecture decision log","application_architect":"Brian Otieno","architecture_style":"modular_monolith","applications_in_scope":"Legacy core – both instances\nTarget accounts module\nTarget deposits module\nRestrictions service\nStatement engine\nTake-over accounts","application_components":"Account service\nInterest accrual\nTerm deposit maturity\nRestriction service\nStatement scheduler\nDormancy processing","design_patterns":"Layered services\nAnti-corruption layer towards the legacy cores\nRetry with back-off on outbound calls","technology_stack":"Target core banking platform – accounts module\nStatement engine\nRelational database for accounts\nIntegration platform\nObject store for statements","apis":"Account enquiry API\nBalance API\nRestriction API\nStatement request API\nTerm deposit maturity API","dependencies":"Product mapping approved\n10-digit account standard agreed\nDormant population identified\nMatured-deposit population identified\nTake-over accounts opened","deployment_model":"on_premises","hosting_environments":["development","test","sit","uat","pre_production","production","dr"],"scalability_approach":"Scale out the stateless services behind the API gateway; size the database for 2.4 million accounts accrued overnight.","non_functional_requirements":"Balances by product and currency: Agree to the trial balance\nBalance enquiry: Under 1 second\nAccount enquiry: 99.9% monthly\nStatements: Kept 7 years"}$j$),
  ('00000000-0000-4000-a01d-000000000005', '00000000-0000-4000-9003-000000000007', 'Data migration and quality application architecture', 'Application Architecture for data migration and quality on the Northbridge Bank technology programme. Owner: Priya Naidoo.', 'draft', $j${"document_reference":"NRB-AA-05","document_version":"0.9","document_owner":"Priya Naidoo","next_review_date":"2026-11-13","purpose":"Describes the application architecture for data migration and quality on the Northbridge Bank technology programme. Cross-cutting delivery of extraction, cleansing, transformation, mock runs and reconciliation for the programme.","objectives":"Mock 2 static data loads inside the window\nMock 3 financial data reconciles\nDress rehearsal finishes with no severity-1 defect open\nTake-over and suspense accounts are zero\nEach population has a named data owner\nControl totals tie to the trial balance","scope":"Source profiling\nExtraction from both legacy instances\nCleansing at source\nTransformation rules\nMock runs\nDress rehearsal","out_of_scope":"Building the target platform\nCard scheme certification\nGeneral ledger replacement\nStaff identity directory rebuild\nA new data warehouse","assumptions":"Three mock runs and one dress rehearsal are enough\nCleansing is done in the source, not in the load\nThe file layout is plain text, one record per line\nDates travel as YYYYMMDD\nControl totals come from the final close of business","constraints":"The April 2027 weekend is fixed\nPersonal data stays in the residency region\nA population cannot load before its predecessor\nSeverity-1 defects block the next mock\nTake-over accounts must finish at zero","risks_mitigations":"Production data copied into a shared workbook – Remove samples from shared workbooks; extracts stay in the staging store\nExtract taken before close of business – Extract after close of business, checked on the mock entry list\nTake-over accounts not at zero – Reconcile take-over accounts to zero before sign-off\nUnmasked data in a lower environment – Masking applied before any refresh\nLoad window overrun – Three mocks with the window measured each time","roles_and_responsibilities":"Delivery lead – Owns delivery and the plan – Priya Naidoo\nBusiness data owner – Signs off the data population – Amina Diallo\nExecutive sponsor – Funds the work and decides escalations – Olivia Banda\nTechnical lead – Owns the technical design – Brian Otieno\nReconciliation lead – Proves control totals after each load – Olivia Banda\nFinance partner – Agrees accounting and control totals – Daniel Okafor","glossary":"Target core\tThe new core banking platform that replaces both legacy cores\nMock\tA full rehearsal load of migrated data into the target core\nHypercare\tThe four weeks of extra support after go-live\nComponent\tA deployable part of an application with one clear job\nAPI\tA published way for one application to call another","appendices":"Data migration and quality delivery overview\tDelivery Overview – Data migration and quality\nData migration and quality roadmap\tNRB-RM-05\nProgramme architecture principles\tNRB-EA-PR-01","version_history":"0.1\t2026-03-23\tPriya Naidoo\tFirst draft\n0.5\t2026-05-31\tBrian Otieno\tComments from Data migration design authority\n0.9\t2026-08-11\tPriya Naidoo\tReady for review","related_documents":"NRB-RM-05 – Data migration and quality roadmap\nDelivery Overview – Data migration and quality\nNRB-ADR – Architecture decision log","application_architect":"Brian Otieno","architecture_style":"layered","applications_in_scope":"Legacy core – both instances\nDocument imaging system\nFinance and general ledger system\nCustomer due diligence repository\nMigration tool\nTarget platform","application_components":"Source extract jobs\nStaging area\nTransformation rules\nLoad adapters\nReconciliation engine\nDefect and cleansing tracker","design_patterns":"Layered services\nAnti-corruption layer towards the legacy cores\nRetry with back-off on outbound calls","technology_stack":"Extract tooling for both legacy instances\nStaging database\nTransformation engine\nTarget core load utilities\nReconciliation reporting","apis":"Load status API\nReconciliation result API\nCleansing backlog API\nControl total API\nDefect feed API","dependencies":"Source access granted\nFile layout signed\nTake-over accounts opened\nData owners named\nMock calendar held","deployment_model":"hybrid","hosting_environments":["development","test","sit","uat","pre_production","production","dr"],"scalability_approach":"Scale out the stateless services behind the API gateway; size the database for 4.8 million static records inside 14 hours.","non_functional_requirements":"Static data load: Inside the 14-hour window\nTake-over and suspense accounts: Zero after reconciliation\nEvery migrated record: Traceable to its source key\nMigration extracts: Encrypted at rest and in transit"}$j$),
  ('00000000-0000-4000-a01d-000000000006', '00000000-0000-4000-9003-000000000007', 'Integration and interfaces application architecture', 'Application Architecture for integration and interfaces on the Northbridge Bank technology programme. Owner: Brian Otieno.', 'draft', $j${"document_reference":"NRB-AA-06","document_version":"0.9","document_owner":"Brian Otieno","next_review_date":"2026-11-19","purpose":"Describes the application architecture for integration and interfaces on the Northbridge Bank technology programme. Delivery of the interfaces the target platform needs from channels, cards, finance, documents and the user store.","objectives":"Each in-scope interface has a contract, a test and an owner\nFailed messages are visible on one dashboard\nCard status cross-check agrees active cards\nTrial-balance file balances before it is used\nImage retrieval works for a mandate\nChannels no longer call the legacy cores after go-live","scope":"Internet banking interface\nMobile banking interface\nBranch teller interface\nContact centre interface\nCard status cross-check\nDocument image retrieval","out_of_scope":"A new integration platform product selection\nOpen-banking directory build\nCard scheme certification\nATM switch replacement\nPoint of sale acquiring","assumptions":"Existing channels are reused and pointed at the target\nThe card system is not migrated; only status is cross-checked\nThe finance system stays and sends a file\nCertificates can be renewed without a scheme change\nOne dashboard covers every in-scope interface","constraints":"SIT entry dates are fixed on the integration plan\nA missing certificate blocks that interface\nCard numbers are not stored on the dashboard\nThe trial-balance file is after close of business\nReplay cannot create a second payment","risks_mitigations":"Silent message loss – Every interface reports to one dashboard with alerts\nCertificate expiring in hypercare – Certificates valid through hypercare, renewed before the freeze\nReplay creating a duplicate payment – Idempotent replay keyed on the message identifier\nA channel still calling the legacy core – Remove legacy addresses and test from each channel\nUnauthenticated internal API – Mutual TLS on every internal API","roles_and_responsibilities":"Delivery lead – Owns delivery and the plan – Brian Otieno\nBusiness owner – Accepts the scope and the result – Ravi Pillai\nExecutive sponsor – Funds the work and decides escalations – Daniel Okafor\nTechnical lead – Owns the technical design – Ravi Pillai\nInterface analyst – Writes and tests interface contracts – Priya Naidoo\nTest lead – Owns test entry, exit and evidence – Catherine Mwangi","glossary":"Target core\tThe new core banking platform that replaces both legacy cores\nMock\tA full rehearsal load of migrated data into the target core\nHypercare\tThe four weeks of extra support after go-live\nComponent\tA deployable part of an application with one clear job\nAPI\tA published way for one application to call another","appendices":"Integration and interfaces delivery overview\tDelivery Overview – Integration and interfaces\nIntegration and interfaces roadmap\tNRB-RM-06\nProgramme architecture principles\tNRB-EA-PR-01","version_history":"0.1\t2026-06-22\tBrian Otieno\tFirst draft\n0.5\t2026-08-30\tRavi Pillai\tComments from Integration design authority\n0.9\t2026-11-13\tBrian Otieno\tReady for review","related_documents":"NRB-RM-06 – Integration and interfaces roadmap\nDelivery Overview – Integration and interfaces\nNRB-ADR – Architecture decision log","application_architect":"Ravi Pillai","architecture_style":"event_driven","applications_in_scope":"Target platform\nInternet banking\nMobile banking\nBranch teller\nContact centre\nCard management platform","application_components":"API gateway\nEvent broker\nFile transfer service\nMessage transformation\nInterface monitoring dashboard\nReplay and repair","design_patterns":"Publish and subscribe for status events\nIdempotent consumers\nOutbox for reliable events","technology_stack":"Integration platform\nAPI gateway\nEvent broker\nManaged file transfer\nMonitoring and alerting service","apis":"Channel API set\nCard status API\nDocument image API\nUser store API\nNotification API","dependencies":"Interface contracts approved\nSIT slots booked\nCertificates inventoried\nDashboard built\nRepair roles assigned","deployment_model":"hybrid","hosting_environments":["development","test","sit","uat","pre_production","production","dr"],"scalability_approach":"Scale out the stateless services behind the API gateway; size the database for 3,000 API calls per second at peak.","non_functional_requirements":"Message delivery: No silent loss; every failure visible\nFailed message repair: Under 30 minutes\nIntegration platform: 99.95% monthly\nService-to-service calls: Mutual TLS on every internal call"}$j$),
  ('00000000-0000-4000-a01d-000000000007', '00000000-0000-4000-9003-000000000007', 'Cybersecurity and access application architecture', 'Application Architecture for cybersecurity and access on the Northbridge Bank technology programme. Owner: Nadia Rahman.', 'draft', $j${"document_reference":"NRB-AA-07","document_version":"0.9","document_owner":"Nadia Rahman","next_review_date":"2026-11-24","purpose":"Describes the application architecture for cybersecurity and access on the Northbridge Bank technology programme. Delivery of user access, recertification and the security controls required before go-live. Currently on hold.","objectives":"Every loaded user has a recertified entitlement\nLeavers are absent from the load\nPrivileged access is listed and approved\nStaff can sign in on day one\nLogging meets the agreed control\nAudit can see who approved each role","scope":"Bank user profiles\nUser groups and roles\nLine-manager recertification\nPrivileged access\nJoiner, mover and leaver handling\nAuthentication for staff","out_of_scope":"Customer authentication redesign\nA new identity product selection\nBuilding access\nCard PIN platform\nEndpoint replacement","assumptions":"Line managers recertify their own staff\nThe identity directory is a source, not a system being replaced\nPrivileged access is a separate list\nLeavers are removed in the source before extract\nCustomer sign-in is owned by the channels delivery","constraints":"User load cannot start before recertification\nThe freeze date does not move for this workstream alone\nPrivileged access requires two approvers\nPersonal data in access logs follows the retention schedule\nA leaver cannot be loaded","risks_mitigations":"Leaver loaded into the target platform – Leaver extract applied before every user load\nShared identity created to save time – Named identities only; shared accounts refused\nPrivileged access copied unchanged – Privileged roles rebuilt and approved, not copied\nLogging weaker than the agreed control – Logging checked against the control before go-live\nSame-day revocation not possible in hypercare – Same-day revocation process tested with the service desk","roles_and_responsibilities":"Delivery lead – Owns delivery and the plan – Nadia Rahman\nBusiness owner – Accepts the scope and the result – Daniel Okafor\nExecutive sponsor – Funds the work and decides escalations – Grace Moyo\nTechnical lead – Owns the technical design – Nadia Rahman\nAccess analyst – Builds the role catalogue and access reviews – Ravi Pillai\nAudit partner – Checks evidence for audit – Olivia Banda","glossary":"Target core\tThe new core banking platform that replaces both legacy cores\nMock\tA full rehearsal load of migrated data into the target core\nHypercare\tThe four weeks of extra support after go-live\nComponent\tA deployable part of an application with one clear job\nAPI\tA published way for one application to call another","appendices":"Cybersecurity and access delivery overview\tDelivery Overview – Cybersecurity and access\nCybersecurity and access roadmap\tNRB-RM-07\nProgramme architecture principles\tNRB-EA-PR-01","version_history":"0.1\t2026-07-06\tNadia Rahman\tFirst draft\n0.5\t2026-09-13\tNadia Rahman\tComments from Security design authority\n0.9\t2026-11-30\tNadia Rahman\tReady for review","related_documents":"NRB-RM-07 – Cybersecurity and access roadmap\nDelivery Overview – Cybersecurity and access\nNRB-ADR – Architecture decision log","application_architect":"Nadia Rahman","architecture_style":"layered","applications_in_scope":"Identity and access management directory\nTarget platform access\nLine-manager workflow\nPrivileged access register\nSecurity logging\nStaff directory","application_components":"Identity provider\nRole catalogue\nRecertification workflow\nPrivileged access vault\nSecurity log collection\nJoiner, mover and leaver feed","design_patterns":"Layered services\nAnti-corruption layer towards the legacy cores\nRetry with back-off on outbound calls","technology_stack":"Identity provider\nPrivileged access vault\nSecurity information and event monitoring\nDirectory service\nAccess recertification tool","apis":"User provisioning API\nRole assignment API\nAccess review API\nSecurity event API\nLeaver feed API","dependencies":"Recertification date agreed\nLine-manager list confirmed\nPrivileged roles listed\nLeaver extract defined\nLogging requirements signed","deployment_model":"hybrid","hosting_environments":["development","test","sit","uat","pre_production","production","dr"],"scalability_approach":"Scale out the stateless services behind the API gateway; size the database for 4,200 staff identities.","non_functional_requirements":"Leaver revocation: Same day\nRole approvals: Approver recorded for every role\nStaff sign-in: 99.9% in business hours\nSecurity events: Kept 12 months, searchable 90 days"}$j$),
  ('00000000-0000-4000-a01d-000000000008', '00000000-0000-4000-9003-000000000007', 'Environments and release application architecture', 'Application Architecture for environments and release on the Northbridge Bank technology programme. Owner: Ravi Pillai.', 'draft', $j${"document_reference":"NRB-AA-08","document_version":"0.9","document_owner":"Ravi Pillai","next_review_date":"2026-11-18","purpose":"Describes the application architecture for environments and release on the Northbridge Bank technology programme. Delivery of the environment path from development through dress rehearsal, production and recovery, and the release calendar that uses it.","objectives":"Every test stage has a booked environment\nDress rehearsal uses a production-like path\nRefresh is requested and logged\nThe release calendar is the only source of release dates\nRecovery is restored and checked before go-live\nNo two mocks share an environment","scope":"Development environment\nTest environment\nSystem integration environment\nUser acceptance environment\nPre-production\nProduction cutover runbook","out_of_scope":"A new data centre build\nEnd-user device replacement\nNetwork redesign\nCloud provider selection\nProduction support model","assumptions":"Existing hosting is reused\nProduction-like data is masked except in dress rehearsal under approval\nOne calendar is enough\nRecovery is a restore test, not a second data centre project\nTeams will book if the booking is easier than asking in a chat","constraints":"The dress rehearsal date is fixed once booked\nMasked data is the default\nProduction access is named people only\nTwo mocks cannot share an environment\nA refresh during execution is refused","risks_mitigations":"Refresh using unmasked production data – Masking approved and applied before refresh\nTwo mocks booked on one environment – One booking register, mandatory from SIT\nRecovery backup that cannot be restored – Recovery restore rehearsed before go-live\nProduction access wider than the named list – Named production access list reviewed monthly\nConfiguration drift between environments – One configuration baseline promoted through every environment","roles_and_responsibilities":"Delivery lead – Owns delivery and the plan – Ravi Pillai\nBusiness owner – Accepts the scope and the result – Brian Otieno\nExecutive sponsor – Funds the work and decides escalations – Daniel Okafor\nTechnical lead – Owns the technical design – Ravi Pillai\nEnvironment analyst – Books and refreshes environments – Priya Naidoo\nRelease manager – Owns the release calendar – Linda Zhou","glossary":"Target core\tThe new core banking platform that replaces both legacy cores\nMock\tA full rehearsal load of migrated data into the target core\nHypercare\tThe four weeks of extra support after go-live\nComponent\tA deployable part of an application with one clear job\nAPI\tA published way for one application to call another","appendices":"Environments and release delivery overview\tDelivery Overview – Environments and release\nEnvironments and release roadmap\tNRB-RM-08\nProgramme architecture principles\tNRB-EA-PR-01","version_history":"0.1\t2026-04-06\tRavi Pillai\tFirst draft\n0.5\t2026-06-14\tRavi Pillai\tComments from Environment and release forum\n0.9\t2026-09-03\tRavi Pillai\tReady for review","related_documents":"NRB-RM-08 – Environments and release roadmap\nDelivery Overview – Environments and release\nNRB-ADR – Architecture decision log","application_architect":"Ravi Pillai","architecture_style":"layered","applications_in_scope":"Development environment\nTest environment\nSystem integration environment\nUser acceptance environment\nPre-production\nProduction","application_components":"Environment booking\nMasked data refresh\nRelease calendar\nDeployment pipeline\nRecovery environment\nProduction runbook","design_patterns":"Layered services\nAnti-corruption layer towards the legacy cores\nRetry with back-off on outbound calls","technology_stack":"Deployment pipeline\nConfiguration management\nData masking tooling\nEnvironment booking register\nBackup and restore service","apis":"Environment booking API\nDeployment status API\nRefresh request API\nRelease calendar feed\nBackup status API","dependencies":"Hosting capacity confirmed\nMasking approach agreed\nApril weekend reserved\nDress rehearsal slot requested\nRefresh process written","deployment_model":"hybrid","hosting_environments":["development","test","sit","uat","pre_production","production","dr"],"scalability_approach":"Scale out the stateless services behind the API gateway; size the database for 7 environments on one booking register.","non_functional_requirements":"Recovery environment: Restored and checked before go-live\nPre-production: 99% during dress rehearsal\nLower environments: Masked data only\nConfiguration: Same baseline from SIT to production"}$j$),
  ('00000000-0000-4000-a01d-000000000009', '00000000-0000-4000-9003-000000000007', 'Operational readiness and hypercare application architecture', 'Application Architecture for operational readiness and hypercare on the Northbridge Bank technology programme. Owner: Linda Zhou.', 'draft', $j${"document_reference":"NRB-AA-09","document_version":"0.9","document_owner":"Linda Zhou","next_review_date":"2026-11-20","purpose":"Describes the application architecture for operational readiness and hypercare on the Northbridge Bank technology programme. Delivery of the support model, runbooks, monitoring handover and the hypercare period after go-live.","objectives":"Every cutover step has a runbook someone has walked through\nHypercare shifts are named, including nights\nThe daily bridge has an agenda and a chair\nSeverity scale matches the defect scale\nMonitoring alerts reach the roster\nKnown errors are written down before go-live","scope":"Support model\nRunbooks for the cutover weekend\nHypercare roster\nDaily hypercare bridge\nSeverity scale for hypercare\nMonitoring handover","out_of_scope":"A new service-desk product\nBranch refurbishment\nA 24-hour contact centre build\nVendor contract renegotiation\nProduction data centre build","assumptions":"Hypercare lasts four weeks\nThe existing service desk is the front door\nRunbooks are steps with an expected result\nNight shifts are required for the first week only\nMonitoring is handed over, not rebuilt","constraints":"Hypercare cannot be staffed by unnamed roles\nA runbook that has not been walked through does not count\nThe first week has night cover\nExit criteria are set before go-live\nThe bridge is every business day in hypercare","risks_mitigations":"Alerts going to a mailbox nobody reads – Alerts routed to the named roster, not a mailbox\nNight shifts left unnamed – Name every shift, including nights, before the dress rehearsal\nRunbooks never walked through – Walk through every runbook in the dress rehearsal\nKnown errors found by customers – Publish the known-error list before go-live\nSeverity 1 response slower than 30 minutes – Severity 1 bridge opened within 15 minutes","roles_and_responsibilities":"Delivery lead – Owns delivery and the plan – Linda Zhou\nBusiness owner – Accepts the scope and the result – Catherine Mwangi\nExecutive sponsor – Funds the work and decides escalations – Grace Moyo\nTechnical lead – Owns the technical design – Ahmed Hassan\nService desk lead – Prepares the service desk for go-live – Brian Otieno\nOperations lead – Owns run procedures after go-live – Ravi Pillai","glossary":"Target core\tThe new core banking platform that replaces both legacy cores\nMock\tA full rehearsal load of migrated data into the target core\nHypercare\tThe four weeks of extra support after go-live\nComponent\tA deployable part of an application with one clear job\nAPI\tA published way for one application to call another","appendices":"Operational readiness and hypercare delivery overview\tDelivery Overview – Operational readiness and hypercare\nOperational readiness and hypercare roadmap\tNRB-RM-09\nProgramme architecture principles\tNRB-EA-PR-01","version_history":"0.1\t2026-09-22\tLinda Zhou\tFirst draft\n0.5\t2026-11-30\tAhmed Hassan\tComments from Operational readiness forum\n0.9\t2027-02-22\tLinda Zhou\tReady for review","related_documents":"NRB-RM-09 – Operational readiness and hypercare roadmap\nDelivery Overview – Operational readiness and hypercare\nNRB-ADR – Architecture decision log","application_architect":"Ahmed Hassan","architecture_style":"layered","applications_in_scope":"Service desk\nMonitoring dashboard\nRunbook store\nRoster\nBridge conference\nKnown-error list","application_components":"Service desk routing\nMonitoring handover\nHypercare bridge\nKnown-error list\nRunbook library\nSeverity scale","design_patterns":"Layered services\nAnti-corruption layer towards the legacy cores\nRetry with back-off on outbound calls","technology_stack":"Service management tool\nMonitoring and alerting service\nCollaboration bridge\nKnowledge base\nOn-call roster","apis":"Incident API\nAlert routing API\nKnown-error feed\nRoster API\nStatus page feed","dependencies":"Support model drafted\nRunbook template agreed\nRoster owners identified\nMonitoring owner named\nSeverity scale reused from defects","deployment_model":"hybrid","hosting_environments":["development","test","sit","uat","pre_production","production","dr"],"scalability_approach":"Scale out the stateless services behind the API gateway; size the database for Up to 600 incidents in the first week.","non_functional_requirements":"Severity 1 response: Within 30 minutes\nHypercare roster: Every shift named, including nights\nService desk: 24 hours during hypercare\nHypercare exit criteria: Numeric and agreed with the sponsor"}$j$),
  ('00000000-0000-4000-a01d-000000000010', '00000000-0000-4000-9003-000000000007', 'Regulatory reporting application architecture', 'Application Architecture for regulatory reporting. Superseded: the reporting workstream closed on 30 September 2026; kept for reference.', 'superseded', $j${"document_reference":"NRB-AA-10","document_version":"1.0","document_owner":"Olivia Banda","next_review_date":"2027-03-31","purpose":"Describes the application architecture for regulatory reporting on the Northbridge Bank technology programme. Completed delivery of the report-line mapping that lets finance keep the existing reporting tool across the migration.","objectives":"Every report line used in the last year has a mapped source\nThe mock cross-check agreed\nDifferences go to the agreed difference account\nThe financial controller has signed\nFinance did not change tool\nEvidence is in the go-live pack","scope":"Report-line map from the trial balance\nCurrency and company mapping\nFirst mock cross-check\nEvidence pack for finance\nNamed owner per report family\nDifference account treatment","out_of_scope":"A new reporting tool\nPrudential return redesign\nTax engine replacement\nManagement information warehouse\nBoard pack redesign","assumptions":"The finance system stays\nThe chart of accounts does not change for go-live\nLast year of report lines is the scope\nDifferences use account 14918 as already agreed for the journals\nThe controller is the signer","constraints":"No new reporting tool\nThe map cannot drop a line used in the last year\nDifferences have one account\nSign-off is the controller, not the project\nThe guide stays short","risks_mitigations":"A report line missed in the map – Check every report line used in the last year against the map\nA mapped line changing meaning – Reopen rule limited to the affected report\nThe difference account used for something else – Account 14918 reserved for differences only\nCustomer-level data in the evidence pack – Remove customer-level rows from the pack\nController signature on the wrong version – Controller signs the version number on the pack","roles_and_responsibilities":"Delivery lead – Owns delivery and the plan – Olivia Banda\nBusiness owner – Accepts the scope and the result – Olivia Banda\nExecutive sponsor – Funds the work and decides escalations – Grace Moyo\nTechnical lead – Owns the technical design – Priya Naidoo\nFinance analyst – Maps ledger accounts and report lines – Daniel Okafor\nMapping analyst – Maintains the report-line map – Amina Diallo","glossary":"Target core\tThe new core banking platform that replaces both legacy cores\nMock\tA full rehearsal load of migrated data into the target core\nHypercare\tThe four weeks of extra support after go-live\nComponent\tA deployable part of an application with one clear job\nAPI\tA published way for one application to call another","appendices":"Regulatory reporting delivery overview\tDelivery Overview – Regulatory reporting\nRegulatory reporting roadmap\tNRB-RM-10\nProgramme architecture principles\tNRB-EA-PR-01","version_history":"0.1\t2026-02-23\tOlivia Banda\tFirst draft\n0.5\t2026-05-03\tPriya Naidoo\tComments from Finance and regulatory forum\n1.0\t2026-09-28\tOlivia Banda\tFinal; workstream closed","related_documents":"NRB-RM-10 – Regulatory reporting roadmap\nDelivery Overview – Regulatory reporting\nNRB-ADR – Architecture decision log","application_architect":"Priya Naidoo","architecture_style":"layered","applications_in_scope":"Finance and general ledger system\nReporting tool\nTrial balance\nMapping sheet\nEvidence store\nDifference account","application_components":"Report-line map\nCurrency mapping\nCompany mapping\nDifference account\nEvidence pack\nReopen rule","design_patterns":"Layered services\nAnti-corruption layer towards the legacy cores\nRetry with back-off on outbound calls","technology_stack":"Existing reporting tool\nFinance ledger\nMapping workbook\nEvidence store\nReconciliation reporting","apis":"Trial balance extract\nMapping lookup\nDifference account feed\nEvidence index\nReport run status","dependencies":"Trial balance owner\nList of report lines from the last year\nDifference account agreed\nController availability\nMapping sheet tool","deployment_model":"on_premises","hosting_environments":["development","test","sit","uat","pre_production","production","dr"],"scalability_approach":"Scale out the stateless services behind the API gateway; size the database for 1,240 report lines mapped.","non_functional_requirements":"Report lines used in the last year: Every line mapped\nMock cross-check: Agrees\nEvidence pack: Kept 7 years\nMapped lines: Reopen only the affected report"}$j$),
  ('00000000-0000-4000-a01e-000000000001', '00000000-0000-4000-9003-000000000008', 'Customer and digital channels data architecture', 'Data Architecture for customer and digital channels on the Northbridge Bank technology programme. Owner: Amina Diallo.', 'draft', $j${"document_reference":"NRB-DA-01","document_version":"0.9","document_owner":"Amina Diallo","next_review_date":"2026-11-16","purpose":"Describes the data architecture for customer and digital channels on the Northbridge Bank technology programme. Delivery of customer master data and the internet, mobile and branch channels for the Northbridge Bank technology programme.","objectives":"Every active customer has one surviving customer number\nAddress completeness at or above 85%\nInternet and mobile users can sign in on day one\nDuplicate customers reduced below 1%\nMandate images linked to the surviving customer\nBranch search returns the customer in under 3 seconds","scope":"Retail and SME customer master\nCorporate customer master from the second legacy instance\nInternet banking registration\nMobile banking registration\nBranch teller customer search\nContact centre customer view","out_of_scope":"Card plastic personalisation\nMarketing campaign tool\nLoyalty scheme\nInsurance product origination\nWealth advisory portal","assumptions":"Both legacy instances are profiled before Mock 2\nThe surviving record is the one with the most complete KYC data\nCustomers accept a new customer number where numbers clash\nBranch staff are trained before the dress rehearsal\nStatement templates are approved by the business","constraints":"Customer numbers must be unique across both legacy instances\nKYC fields are mandatory before a customer can be loaded\nAddress completeness target is 85%\nImages must be linked before the channel is opened\nThe load window is the weekend of 10–12 April 2027","risks_mitigations":"Account takeover through weak registration checks – Two-factor registration and device binding\nDuplicate customer merged onto the wrong survivor – Survivor rule signed by the business data owner and sample-checked\nMandate images exposed through a direct link – Images served only through the authenticated retrieval API\nCredential stuffing on internet banking sign-in – Rate limits and lock-out on sign-in\nPersonal data copied into test environments – Masked data only in lower environments","roles_and_responsibilities":"Delivery lead – Owns delivery and the plan – Amina Diallo\nBusiness owner – Accepts the scope and the result – Nomvula Khumalo\nExecutive sponsor – Funds the work and decides escalations – Grace Moyo\nTechnical lead – Owns the technical design – Ravi Pillai\nData analyst – Profiles and maps the data – Priya Naidoo\nChannel analyst – Designs channel journeys and entitlements – Brian Otieno","glossary":"Target core\tThe new core banking platform that replaces both legacy cores\nMock\tA full rehearsal load of migrated data into the target core\nHypercare\tThe four weeks of extra support after go-live\nSurvivor record\tThe record kept when duplicates are merged\nControl total\tA count or sum used to prove a load is complete","appendices":"Customer and digital channels delivery overview\tDelivery Overview – Customer and digital channels\nCustomer and digital channels roadmap\tNRB-RM-01\nProgramme architecture principles\tNRB-EA-PR-01","version_history":"0.1\t2026-04-27\tAmina Diallo\tFirst draft\n0.5\t2026-07-05\tRavi Pillai\tComments from Channels steering group\n0.9\t2026-09-03\tAmina Diallo\tReady for review","related_documents":"NRB-RM-01 – Customer and digital channels roadmap\nDelivery Overview – Customer and digital channels\nNRB-ADR – Architecture decision log","data_architect":"Ravi Pillai","data_domains":"Customer\nParty relationship\nContact preference\nMandate and signature\nChannel entitlement","data_sources":"Legacy core instance 1\nLegacy core instance 2\nLegacy core – retail and SME instance\nLegacy core – corporate instance","data_stores":"Customer master database\nMandate image object store\nChannel session store\nCustomer cross-reference table","conceptual_model":"Customer is the central entity. Customer address, Mandate, Signature image, Channel user hang off it, each keyed by the target core identifier with the legacy key kept as an alternate key.","logical_model_reference":"NRB-DA-LM-01","master_data_entities":"Customer\nCustomer address\nMandate\nSignature image\nChannel user","data_flows":"Customer profile sync: Target core to Internet banking\nMandate image retrieval: Object store to Branch teller\nRegistration events: Internet banking to Target core\nCustomer cross-reference load: Migration staging to Target core\nContact centre lookup: Target core to Contact centre desktop","integration_patterns":["real_time_api","event_streaming","batch"],"data_owners":"Amina Diallo (Delivery lead)\nNomvula Khumalo (Business owner)\nRavi Pillai (Technical lead)","data_quality_rules":"Every active customer has one surviving customer number\nAddress completeness at or above 85%\nInternet and mobile users can sign in on day one\nDuplicate customers reduced below 1%","retention_rules":"Customer and account records kept 7 years after closure\nMigration extracts deleted 90 days after go-live\nReconciliation evidence kept with the go-live pack","classification_levels":["internal","confidential","restricted"],"personal_data_processed":true,"privacy_controls":"Masked data only in lower environments\nAccess to personal data on a need-to-know role\nPersonal data stays in the agreed region","encryption_requirements":"Encrypted at rest in every store\nTLS 1.2 or higher in transit\nMigration extracts encrypted with a programme key"}$j$),
  ('00000000-0000-4000-a01e-000000000002', '00000000-0000-4000-9003-000000000008', 'Payments and transfers data architecture', 'Data Architecture for payments and transfers on the Northbridge Bank technology programme. Owner: Ahmed Hassan.', 'draft', $j${"document_reference":"NRB-DA-02","document_version":"0.9","document_owner":"Ahmed Hassan","next_review_date":"2026-11-18","purpose":"Describes the data architecture for payments and transfers on the Northbridge Bank technology programme. Delivery of domestic payments, standing orders and internal transfers onto the target platform.","objectives":"Every active standing order is recreated before go-live\nSettlement totals agree to the cent\nReturned payments land on the repair queue\nChannel limits match the signed matrix\nNo duplicate payment on the cutover weekend\nCut-off calendar loaded for the next 18 months","scope":"Domestic credit transfers\nInternal account transfers\nStanding orders\nFuture-dated payments\nPayment limits by channel\nSettlement timetable","out_of_scope":"Card authorisation\nATM cash\nCheque clearing replacement\nCross-border correspondent banking rebuild\nCash-in-transit","assumptions":"The scheme timetable does not change before go-live\nStanding orders are recreated, not replayed from history\nBoth legacy instances use the same value-date rule\nPayment limits are signed by the business before UAT\nThe repair queue is staffed for hypercare","constraints":"Scheme cut-off cannot move\nSettlement must balance on the night\nStanding orders with an end date in the past are excluded\nDual control stays on the repair queue\nPayment files are not accepted during the freeze","risks_mitigations":"Duplicate payment on the cutover weekend – Idempotent posting keyed on the payment reference\nChannel limits looser than the signed matrix – Load limits from the signed matrix and test every band\nScheme certificate expiry – Certificate inventory with 60-day expiry alerts\nTampered payment file in transit – Signed and encrypted payment files\nRepair actions without dual control – Dual control enforced on every repair action","roles_and_responsibilities":"Delivery lead – Owns delivery and the plan – Ahmed Hassan\nBusiness owner – Accepts the scope and the result – Catherine Mwangi\nExecutive sponsor – Funds the work and decides escalations – Daniel Okafor\nTechnical lead – Owns the technical design – Brian Otieno\nSettlement analyst – Designs settlement and reconciliation – Olivia Banda\nTest lead – Owns test entry, exit and evidence – Priya Naidoo","glossary":"Target core\tThe new core banking platform that replaces both legacy cores\nMock\tA full rehearsal load of migrated data into the target core\nHypercare\tThe four weeks of extra support after go-live\nSurvivor record\tThe record kept when duplicates are merged\nControl total\tA count or sum used to prove a load is complete","appendices":"Payments and transfers delivery overview\tDelivery Overview – Payments and transfers\nPayments and transfers roadmap\tNRB-RM-02\nProgramme architecture principles\tNRB-EA-PR-01","version_history":"0.1\t2026-05-25\tAhmed Hassan\tFirst draft\n0.5\t2026-08-02\tBrian Otieno\tComments from Payments working group\n0.9\t2026-10-04\tAhmed Hassan\tReady for review","related_documents":"NRB-RM-02 – Payments and transfers roadmap\nDelivery Overview – Payments and transfers\nNRB-ADR – Architecture decision log","data_architect":"Brian Otieno","data_domains":"Payment order\nStanding order\nLimit\nSettlement\nScheme calendar","data_sources":"Legacy core instance 1\nLegacy core instance 2\nLegacy core – both instances\nTarget payments engine","data_stores":"Payment state database\nStanding order store\nSettlement ledger\nRepair queue store","conceptual_model":"Payment is the central entity. Standing order, Beneficiary, Channel limit, Settlement account hang off it, each keyed by the target core identifier with the legacy key kept as an alternate key.","logical_model_reference":"NRB-DA-LM-02","master_data_entities":"Payment\nStanding order\nBeneficiary\nChannel limit\nSettlement account","data_flows":"Outbound credit transfers: Target core to Scheme gateway\nInbound credits: Scheme gateway to Target core\nPayment status events: Target core to Internet banking\nReturned items: Scheme gateway to Repair queue\nNotification dispatch: Target core to Notification service","integration_patterns":["event_streaming","file_transfer","real_time_api"],"data_owners":"Ahmed Hassan (Delivery lead)\nCatherine Mwangi (Business owner)\nBrian Otieno (Technical lead)","data_quality_rules":"Every active standing order is recreated before go-live\nSettlement totals agree to the cent\nReturned payments land on the repair queue\nChannel limits match the signed matrix","retention_rules":"Customer and account records kept 7 years after closure\nMigration extracts deleted 90 days after go-live\nReconciliation evidence kept with the go-live pack","classification_levels":["internal","confidential","restricted"],"personal_data_processed":true,"privacy_controls":"Masked data only in lower environments\nAccess to personal data on a need-to-know role\nPersonal data stays in the agreed region","encryption_requirements":"Encrypted at rest in every store\nTLS 1.2 or higher in transit\nMigration extracts encrypted with a programme key"}$j$),
  ('00000000-0000-4000-a01e-000000000003', '00000000-0000-4000-9003-000000000008', 'Lending, limits and collateral data architecture', 'Data Architecture for lending, limits and collateral on the Northbridge Bank technology programme. Owner: Joy Akinyi.', 'draft', $j${"document_reference":"NRB-DA-03","document_version":"0.9","document_owner":"Joy Akinyi","next_review_date":"2026-11-11","purpose":"Describes the data architecture for lending, limits and collateral on the Northbridge Bank technology programme. Delivery of loans, limits and collateral, including overdue bills and the expired-limit rule.","objectives":"Every live loan has an arrangement, a balance and a schedule\nAgeing continues from the legacy past-due date\nExpired limits follow the signed rule\nCollateral is linked before the loan is loaded\nOne repayment account per customer per currency\nTake-over accounts return to zero","scope":"Retail loan arrangements\nCorporate loan arrangements\nOverdue and due bills\nAccrued interest on loans\nLimit records\nExpired limits still linked to a contract","out_of_scope":"New scorecard build\nDebt collection agency files\nSecuritisation\nSyndicated loan agency\nTrade finance instruments","assumptions":"Schedules are regenerated from the migrated frequency\nThe expired-limit rule is expiry plus one day, with the original date kept\nOne liquidation account is allowed per customer per currency\nCollateral rights load before collateral items\nPast-due date becomes the bill date","constraints":"A loan cannot load before its customer and account\nCollateral cannot load before its right\nAgeing must not reset to zero\nExpired limits cannot be dropped while a contract is live\nTake-over accounts must be zero after reconciliation","risks_mitigations":"Expired limit left securing a live contract – Expired-limit rule signed and every case on a credit review queue\nCollateral loaded before its right and rejected – Load rights before items, rehearsed in Mock 2\nAccrual counted twice after migration – Accrual value date set to the migration date\nUnauthorised limit override – Limit overrides need a second approver\nCredit data exposed to non-credit staff – Credit screens limited to credit roles","roles_and_responsibilities":"Delivery lead – Owns delivery and the plan – Joy Akinyi\nBusiness owner – Accepts the scope and the result – Daniel Okafor\nExecutive sponsor – Funds the work and decides escalations – Grace Moyo\nTechnical lead – Owns the technical design – Priya Naidoo\nCredit analyst – Defines lending and limit rules – Ahmed Hassan\nCollateral analyst – Maps collateral rights and items – Linda Zhou","glossary":"Target core\tThe new core banking platform that replaces both legacy cores\nMock\tA full rehearsal load of migrated data into the target core\nHypercare\tThe four weeks of extra support after go-live\nSurvivor record\tThe record kept when duplicates are merged\nControl total\tA count or sum used to prove a load is complete","appendices":"Lending, limits and collateral delivery overview\tDelivery Overview – Lending, limits and collateral\nLending, limits and collateral roadmap\tNRB-RM-03\nProgramme architecture principles\tNRB-EA-PR-01","version_history":"0.1\t2026-06-08\tJoy Akinyi\tFirst draft\n0.5\t2026-08-16\tPriya Naidoo\tComments from Credit design authority\n0.9\t2026-10-21\tJoy Akinyi\tReady for review","related_documents":"NRB-RM-03 – Lending, limits and collateral roadmap\nDelivery Overview – Lending, limits and collateral\nNRB-ADR – Architecture decision log","data_architect":"Priya Naidoo","data_domains":"Loan arrangement\nLimit\nCollateral\nRepayment schedule\nArrears","data_sources":"Legacy core instance 1\nLegacy core instance 2\nLegacy core – both instances\nTarget lending module","data_stores":"Lending database\nCollateral register\nSchedule store\nArrears history","conceptual_model":"Loan is the central entity. Limit, Collateral right, Collateral item, Repayment account hang off it, each keyed by the target core identifier with the legacy key kept as an alternate key.","logical_model_reference":"NRB-DA-LM-03","master_data_entities":"Loan\nLimit\nCollateral right\nCollateral item\nRepayment account","data_flows":"Collateral to loan link: Collateral register to Target core\nLoan balances: Target core to Finance ledger\nArrears status: Target core to Collections system\nLimit utilisation: Target core to Credit risk reporting\nLoan migration load: Migration staging to Target core","integration_patterns":["batch","real_time_api"],"data_owners":"Joy Akinyi (Delivery lead)\nDaniel Okafor (Business owner)\nPriya Naidoo (Technical lead)","data_quality_rules":"Every live loan has an arrangement, a balance and a schedule\nAgeing continues from the legacy past-due date\nExpired limits follow the signed rule\nCollateral is linked before the loan is loaded","retention_rules":"Customer and account records kept 7 years after closure\nMigration extracts deleted 90 days after go-live\nReconciliation evidence kept with the go-live pack","classification_levels":["internal","confidential","restricted"],"personal_data_processed":true,"privacy_controls":"Masked data only in lower environments\nAccess to personal data on a need-to-know role\nPersonal data stays in the agreed region","encryption_requirements":"Encrypted at rest in every store\nTLS 1.2 or higher in transit\nMigration extracts encrypted with a programme key"}$j$),
  ('00000000-0000-4000-a01e-000000000004', '00000000-0000-4000-9003-000000000008', 'Deposits and accounts data architecture', 'Data Architecture for deposits and accounts on the Northbridge Bank technology programme. Owner: Catherine Mwangi.', 'draft', $j${"document_reference":"NRB-DA-04","document_version":"0.9","document_owner":"Catherine Mwangi","next_review_date":"2026-11-17","purpose":"Describes the data architecture for deposits and accounts on the Northbridge Bank technology programme. Delivery of current accounts, savings and term deposits, including balances and accruals.","objectives":"Every open account has a product, a balance and an owner\nInstance 2 account numbers are kept as alternate keys\nDormant accounts over five years are closed or transferred\nMatured deposits no longer carry a balance at the freeze\nRestrictions match the legacy narrative\nStatement frequency is remapped","scope":"Current accounts\nSavings accounts\nTerm deposits\nDeposit balances and accruals\nDormant accounts over five years\nMatured deposits that still hold a balance","out_of_scope":"Safe custody\nNew savings product launch\nPrize-linked savings\nChildren account campaign\nBrokerage cash accounts","assumptions":"Three legacy current-account products become one target product\nInstance 2 numbers become 10 digits with a check digit\nDormant means no customer-initiated transaction for five years\nUnclaimed balances move under the existing regulation\nMatured deposits are paid out or rolled, not migrated as running","constraints":"No account closures in the week before go-live\nA zero-balance account marked for closure is excluded\nAlternate keys are mandatory for instance 2\nAccrual value date cannot be the original accrual date\nProduct mapping cannot change after Mock 2 without a new approval","risks_mitigations":"Matured deposit still carrying a balance at the freeze – Pay out or roll matured deposits before the freeze\nAccount numbers clashing across the two instances – 10-digit numbers with check digit and alternate keys\nRestriction narrative dropped in migration – Sample-check restriction narratives after each mock\nStatement sent to the wrong address – Address taken from the survivor customer record\nInterest accrued twice – Accrual reconciled by product after Mock 3","roles_and_responsibilities":"Delivery lead – Owns delivery and the plan – Catherine Mwangi\nBusiness owner – Accepts the scope and the result – Nomvula Khumalo\nExecutive sponsor – Funds the work and decides escalations – Olivia Banda\nTechnical lead – Owns the technical design – Brian Otieno\nProduct analyst – Maps products to the target core – Amina Diallo\nFinance partner – Agrees accounting and control totals – Daniel Okafor","glossary":"Target core\tThe new core banking platform that replaces both legacy cores\nMock\tA full rehearsal load of migrated data into the target core\nHypercare\tThe four weeks of extra support after go-live\nSurvivor record\tThe record kept when duplicates are merged\nControl total\tA count or sum used to prove a load is complete","appendices":"Deposits and accounts delivery overview\tDelivery Overview – Deposits and accounts\nDeposits and accounts roadmap\tNRB-RM-04\nProgramme architecture principles\tNRB-EA-PR-01","version_history":"0.1\t2026-05-11\tCatherine Mwangi\tFirst draft\n0.5\t2026-07-19\tBrian Otieno\tComments from Deposits product forum\n0.9\t2026-09-26\tCatherine Mwangi\tReady for review","related_documents":"NRB-RM-04 – Deposits and accounts roadmap\nDelivery Overview – Deposits and accounts\nNRB-ADR – Architecture decision log","data_architect":"Brian Otieno","data_domains":"Account\nBalance and accrual\nRestriction\nStatement\nDormancy","data_sources":"Legacy core instance 1\nLegacy core instance 2\nLegacy core – both instances\nTarget accounts module","data_stores":"Accounts database\nAccrual store\nStatement archive\nAlternate account key table","conceptual_model":"Account is the central entity. Account balance, Restriction, Term deposit, Statement preference hang off it, each keyed by the target core identifier with the legacy key kept as an alternate key.","logical_model_reference":"NRB-DA-LM-04","master_data_entities":"Account\nAccount balance\nRestriction\nTerm deposit\nStatement preference","data_flows":"Balance enquiry: Target core to Internet banking\nStatement generation: Target core to Statement engine\nDormant account report: Target core to Operations\nAccount migration load: Migration staging to Target core\nGeneral ledger postings: Target core to Finance ledger","integration_patterns":["batch","real_time_api"],"data_owners":"Catherine Mwangi (Delivery lead)\nNomvula Khumalo (Business owner)\nBrian Otieno (Technical lead)","data_quality_rules":"Every open account has a product, a balance and an owner\nInstance 2 account numbers are kept as alternate keys\nDormant accounts over five years are closed or transferred\nMatured deposits no longer carry a balance at the freeze","retention_rules":"Customer and account records kept 7 years after closure\nMigration extracts deleted 90 days after go-live\nReconciliation evidence kept with the go-live pack","classification_levels":["internal","confidential","restricted"],"personal_data_processed":true,"privacy_controls":"Masked data only in lower environments\nAccess to personal data on a need-to-know role\nPersonal data stays in the agreed region","encryption_requirements":"Encrypted at rest in every store\nTLS 1.2 or higher in transit\nMigration extracts encrypted with a programme key"}$j$),
  ('00000000-0000-4000-a01e-000000000005', '00000000-0000-4000-9003-000000000008', 'Data migration and quality data architecture', 'Data Architecture for data migration and quality on the Northbridge Bank technology programme. Owner: Priya Naidoo.', 'draft', $j${"document_reference":"NRB-DA-05","document_version":"0.9","document_owner":"Priya Naidoo","next_review_date":"2026-11-13","purpose":"Describes the data architecture for data migration and quality on the Northbridge Bank technology programme. Cross-cutting delivery of extraction, cleansing, transformation, mock runs and reconciliation for the programme.","objectives":"Mock 2 static data loads inside the window\nMock 3 financial data reconciles\nDress rehearsal finishes with no severity-1 defect open\nTake-over and suspense accounts are zero\nEach population has a named data owner\nControl totals tie to the trial balance","scope":"Source profiling\nExtraction from both legacy instances\nCleansing at source\nTransformation rules\nMock runs\nDress rehearsal","out_of_scope":"Building the target platform\nCard scheme certification\nGeneral ledger replacement\nStaff identity directory rebuild\nA new data warehouse","assumptions":"Three mock runs and one dress rehearsal are enough\nCleansing is done in the source, not in the load\nThe file layout is plain text, one record per line\nDates travel as YYYYMMDD\nControl totals come from the final close of business","constraints":"The April 2027 weekend is fixed\nPersonal data stays in the residency region\nA population cannot load before its predecessor\nSeverity-1 defects block the next mock\nTake-over accounts must finish at zero","risks_mitigations":"Production data copied into a shared workbook – Remove samples from shared workbooks; extracts stay in the staging store\nExtract taken before close of business – Extract after close of business, checked on the mock entry list\nTake-over accounts not at zero – Reconcile take-over accounts to zero before sign-off\nUnmasked data in a lower environment – Masking applied before any refresh\nLoad window overrun – Three mocks with the window measured each time","roles_and_responsibilities":"Delivery lead – Owns delivery and the plan – Priya Naidoo\nBusiness data owner – Signs off the data population – Amina Diallo\nExecutive sponsor – Funds the work and decides escalations – Olivia Banda\nTechnical lead – Owns the technical design – Brian Otieno\nReconciliation lead – Proves control totals after each load – Olivia Banda\nFinance partner – Agrees accounting and control totals – Daniel Okafor","glossary":"Target core\tThe new core banking platform that replaces both legacy cores\nMock\tA full rehearsal load of migrated data into the target core\nHypercare\tThe four weeks of extra support after go-live\nSurvivor record\tThe record kept when duplicates are merged\nControl total\tA count or sum used to prove a load is complete","appendices":"Data migration and quality delivery overview\tDelivery Overview – Data migration and quality\nData migration and quality roadmap\tNRB-RM-05\nProgramme architecture principles\tNRB-EA-PR-01","version_history":"0.1\t2026-03-23\tPriya Naidoo\tFirst draft\n0.5\t2026-05-31\tBrian Otieno\tComments from Data migration design authority\n0.9\t2026-08-11\tPriya Naidoo\tReady for review","related_documents":"NRB-RM-05 – Data migration and quality roadmap\nDelivery Overview – Data migration and quality\nNRB-ADR – Architecture decision log","data_architect":"Brian Otieno","data_domains":"Customer\nAccount\nLoan\nPayment\nControl total","data_sources":"Legacy core instance 1\nLegacy core instance 2\nLegacy core – both instances\nDocument imaging system","data_stores":"Staging database\nTransformation rule store\nReconciliation results\nCleansing backlog","conceptual_model":"Source record is the central entity. Mapping rule, Control total, Reconciliation break, Cleansing item hang off it, each keyed by the target core identifier with the legacy key kept as an alternate key.","logical_model_reference":"NRB-DA-LM-05","master_data_entities":"Source record\nMapping rule\nControl total\nReconciliation break\nCleansing item","data_flows":"Legacy instance 1 extract: Legacy core 1 to Staging\nLegacy instance 2 extract: Legacy core 2 to Staging\nTarget load: Staging to Target core\nControl totals: Target core to Reconciliation engine\nTrial balance feed: Finance ledger to Reconciliation engine","integration_patterns":["etl_elt","file_transfer","batch"],"data_owners":"Priya Naidoo (Delivery lead)\nAmina Diallo (Business data owner)\nBrian Otieno (Technical lead)","data_quality_rules":"Mock 2 static data loads inside the window\nMock 3 financial data reconciles\nDress rehearsal finishes with no severity-1 defect open\nTake-over and suspense accounts are zero","retention_rules":"Customer and account records kept 7 years after closure\nMigration extracts deleted 90 days after go-live\nReconciliation evidence kept with the go-live pack","classification_levels":["internal","confidential","restricted"],"personal_data_processed":true,"privacy_controls":"Masked data only in lower environments\nAccess to personal data on a need-to-know role\nPersonal data stays in the agreed region","encryption_requirements":"Encrypted at rest in every store\nTLS 1.2 or higher in transit\nMigration extracts encrypted with a programme key"}$j$),
  ('00000000-0000-4000-a01e-000000000006', '00000000-0000-4000-9003-000000000008', 'Integration and interfaces data architecture', 'Data Architecture for integration and interfaces on the Northbridge Bank technology programme. Owner: Brian Otieno.', 'draft', $j${"document_reference":"NRB-DA-06","document_version":"0.9","document_owner":"Brian Otieno","next_review_date":"2026-11-19","purpose":"Describes the data architecture for integration and interfaces on the Northbridge Bank technology programme. Delivery of the interfaces the target platform needs from channels, cards, finance, documents and the user store.","objectives":"Each in-scope interface has a contract, a test and an owner\nFailed messages are visible on one dashboard\nCard status cross-check agrees active cards\nTrial-balance file balances before it is used\nImage retrieval works for a mandate\nChannels no longer call the legacy cores after go-live","scope":"Internet banking interface\nMobile banking interface\nBranch teller interface\nContact centre interface\nCard status cross-check\nDocument image retrieval","out_of_scope":"A new integration platform product selection\nOpen-banking directory build\nCard scheme certification\nATM switch replacement\nPoint of sale acquiring","assumptions":"Existing channels are reused and pointed at the target\nThe card system is not migrated; only status is cross-checked\nThe finance system stays and sends a file\nCertificates can be renewed without a scheme change\nOne dashboard covers every in-scope interface","constraints":"SIT entry dates are fixed on the integration plan\nA missing certificate blocks that interface\nCard numbers are not stored on the dashboard\nThe trial-balance file is after close of business\nReplay cannot create a second payment","risks_mitigations":"Silent message loss – Every interface reports to one dashboard with alerts\nCertificate expiring in hypercare – Certificates valid through hypercare, renewed before the freeze\nReplay creating a duplicate payment – Idempotent replay keyed on the message identifier\nA channel still calling the legacy core – Remove legacy addresses and test from each channel\nUnauthenticated internal API – Mutual TLS on every internal API","roles_and_responsibilities":"Delivery lead – Owns delivery and the plan – Brian Otieno\nBusiness owner – Accepts the scope and the result – Ravi Pillai\nExecutive sponsor – Funds the work and decides escalations – Daniel Okafor\nTechnical lead – Owns the technical design – Ravi Pillai\nInterface analyst – Writes and tests interface contracts – Priya Naidoo\nTest lead – Owns test entry, exit and evidence – Catherine Mwangi","glossary":"Target core\tThe new core banking platform that replaces both legacy cores\nMock\tA full rehearsal load of migrated data into the target core\nHypercare\tThe four weeks of extra support after go-live\nSurvivor record\tThe record kept when duplicates are merged\nControl total\tA count or sum used to prove a load is complete","appendices":"Integration and interfaces delivery overview\tDelivery Overview – Integration and interfaces\nIntegration and interfaces roadmap\tNRB-RM-06\nProgramme architecture principles\tNRB-EA-PR-01","version_history":"0.1\t2026-06-22\tBrian Otieno\tFirst draft\n0.5\t2026-08-30\tRavi Pillai\tComments from Integration design authority\n0.9\t2026-11-13\tBrian Otieno\tReady for review","related_documents":"NRB-RM-06 – Integration and interfaces roadmap\nDelivery Overview – Integration and interfaces\nNRB-ADR – Architecture decision log","data_architect":"Ravi Pillai","data_domains":"Interface contract\nMessage\nEvent\nCertificate\nInterface owner","data_sources":"Legacy core instance 1\nLegacy core instance 2\nTarget platform\nInternet banking","data_stores":"Message store\nReplay store\nInterface register\nCertificate inventory","conceptual_model":"Interface is the central entity. Message, Event subscription, Certificate, Repair item hang off it, each keyed by the target core identifier with the legacy key kept as an alternate key.","logical_model_reference":"NRB-DA-LM-06","master_data_entities":"Interface\nMessage\nEvent subscription\nCertificate\nRepair item","data_flows":"Card status cross-check: Card platform to Target core\nFinance trial balance: Target core to Finance ledger\nDocument image retrieval: Object store to Channels\nDigital user store link: Identity provider to Target core\nNotification dispatch: Target core to Notification service","integration_patterns":["real_time_api","event_streaming","file_transfer"],"data_owners":"Brian Otieno (Delivery lead)\nRavi Pillai (Business owner)\nRavi Pillai (Technical lead)","data_quality_rules":"Each in-scope interface has a contract, a test and an owner\nFailed messages are visible on one dashboard\nCard status cross-check agrees active cards\nTrial-balance file balances before it is used","retention_rules":"Customer and account records kept 7 years after closure\nMigration extracts deleted 90 days after go-live\nReconciliation evidence kept with the go-live pack","classification_levels":["internal","confidential","restricted"],"personal_data_processed":true,"privacy_controls":"Masked data only in lower environments\nAccess to personal data on a need-to-know role\nPersonal data stays in the agreed region","encryption_requirements":"Encrypted at rest in every store\nTLS 1.2 or higher in transit\nMigration extracts encrypted with a programme key"}$j$),
  ('00000000-0000-4000-a01e-000000000007', '00000000-0000-4000-9003-000000000008', 'Cybersecurity and access data architecture', 'Data Architecture for cybersecurity and access on the Northbridge Bank technology programme. Owner: Nadia Rahman.', 'draft', $j${"document_reference":"NRB-DA-07","document_version":"0.9","document_owner":"Nadia Rahman","next_review_date":"2026-11-24","purpose":"Describes the data architecture for cybersecurity and access on the Northbridge Bank technology programme. Delivery of user access, recertification and the security controls required before go-live. Currently on hold.","objectives":"Every loaded user has a recertified entitlement\nLeavers are absent from the load\nPrivileged access is listed and approved\nStaff can sign in on day one\nLogging meets the agreed control\nAudit can see who approved each role","scope":"Bank user profiles\nUser groups and roles\nLine-manager recertification\nPrivileged access\nJoiner, mover and leaver handling\nAuthentication for staff","out_of_scope":"Customer authentication redesign\nA new identity product selection\nBuilding access\nCard PIN platform\nEndpoint replacement","assumptions":"Line managers recertify their own staff\nThe identity directory is a source, not a system being replaced\nPrivileged access is a separate list\nLeavers are removed in the source before extract\nCustomer sign-in is owned by the channels delivery","constraints":"User load cannot start before recertification\nThe freeze date does not move for this workstream alone\nPrivileged access requires two approvers\nPersonal data in access logs follows the retention schedule\nA leaver cannot be loaded","risks_mitigations":"Leaver loaded into the target platform – Leaver extract applied before every user load\nShared identity created to save time – Named identities only; shared accounts refused\nPrivileged access copied unchanged – Privileged roles rebuilt and approved, not copied\nLogging weaker than the agreed control – Logging checked against the control before go-live\nSame-day revocation not possible in hypercare – Same-day revocation process tested with the service desk","roles_and_responsibilities":"Delivery lead – Owns delivery and the plan – Nadia Rahman\nBusiness owner – Accepts the scope and the result – Daniel Okafor\nExecutive sponsor – Funds the work and decides escalations – Grace Moyo\nTechnical lead – Owns the technical design – Nadia Rahman\nAccess analyst – Builds the role catalogue and access reviews – Ravi Pillai\nAudit partner – Checks evidence for audit – Olivia Banda","glossary":"Target core\tThe new core banking platform that replaces both legacy cores\nMock\tA full rehearsal load of migrated data into the target core\nHypercare\tThe four weeks of extra support after go-live\nSurvivor record\tThe record kept when duplicates are merged\nControl total\tA count or sum used to prove a load is complete","appendices":"Cybersecurity and access delivery overview\tDelivery Overview – Cybersecurity and access\nCybersecurity and access roadmap\tNRB-RM-07\nProgramme architecture principles\tNRB-EA-PR-01","version_history":"0.1\t2026-07-06\tNadia Rahman\tFirst draft\n0.5\t2026-09-13\tNadia Rahman\tComments from Security design authority\n0.9\t2026-11-30\tNadia Rahman\tReady for review","related_documents":"NRB-RM-07 – Cybersecurity and access roadmap\nDelivery Overview – Cybersecurity and access\nNRB-ADR – Architecture decision log","data_architect":"Nadia Rahman","data_domains":"User identity\nRole\nEntitlement\nPrivileged account\nSecurity event","data_sources":"Legacy core instance 1\nLegacy core instance 2\nIdentity and access management directory\nTarget platform access","data_stores":"Directory\nRole catalogue\nRecertification evidence store\nSecurity log store","conceptual_model":"User is the central entity. Role, Entitlement, Privileged account, Access review hang off it, each keyed by the target core identifier with the legacy key kept as an alternate key.","logical_model_reference":"NRB-DA-LM-07","master_data_entities":"User\nRole\nEntitlement\nPrivileged account\nAccess review","data_flows":"Joiner, mover and leaver feed: HR system to Identity provider\nRole provisioning: Identity provider to Target core\nSecurity events: Target core to Security monitoring\nRecertification evidence: Recertification tool to Audit store\nPrivileged session logs: Access vault to Security monitoring","integration_patterns":["batch","real_time_api","event_streaming"],"data_owners":"Nadia Rahman (Delivery lead)\nDaniel Okafor (Business owner)\nNadia Rahman (Technical lead)","data_quality_rules":"Every loaded user has a recertified entitlement\nLeavers are absent from the load\nPrivileged access is listed and approved\nStaff can sign in on day one","retention_rules":"Customer and account records kept 7 years after closure\nMigration extracts deleted 90 days after go-live\nReconciliation evidence kept with the go-live pack","classification_levels":["internal","confidential","restricted"],"personal_data_processed":true,"privacy_controls":"Masked data only in lower environments\nAccess to personal data on a need-to-know role\nPersonal data stays in the agreed region","encryption_requirements":"Encrypted at rest in every store\nTLS 1.2 or higher in transit\nMigration extracts encrypted with a programme key"}$j$),
  ('00000000-0000-4000-a01e-000000000008', '00000000-0000-4000-9003-000000000008', 'Environments and release data architecture', 'Data Architecture for environments and release on the Northbridge Bank technology programme. Owner: Ravi Pillai.', 'draft', $j${"document_reference":"NRB-DA-08","document_version":"0.9","document_owner":"Ravi Pillai","next_review_date":"2026-11-18","purpose":"Describes the data architecture for environments and release on the Northbridge Bank technology programme. Delivery of the environment path from development through dress rehearsal, production and recovery, and the release calendar that uses it.","objectives":"Every test stage has a booked environment\nDress rehearsal uses a production-like path\nRefresh is requested and logged\nThe release calendar is the only source of release dates\nRecovery is restored and checked before go-live\nNo two mocks share an environment","scope":"Development environment\nTest environment\nSystem integration environment\nUser acceptance environment\nPre-production\nProduction cutover runbook","out_of_scope":"A new data centre build\nEnd-user device replacement\nNetwork redesign\nCloud provider selection\nProduction support model","assumptions":"Existing hosting is reused\nProduction-like data is masked except in dress rehearsal under approval\nOne calendar is enough\nRecovery is a restore test, not a second data centre project\nTeams will book if the booking is easier than asking in a chat","constraints":"The dress rehearsal date is fixed once booked\nMasked data is the default\nProduction access is named people only\nTwo mocks cannot share an environment\nA refresh during execution is refused","risks_mitigations":"Refresh using unmasked production data – Masking approved and applied before refresh\nTwo mocks booked on one environment – One booking register, mandatory from SIT\nRecovery backup that cannot be restored – Recovery restore rehearsed before go-live\nProduction access wider than the named list – Named production access list reviewed monthly\nConfiguration drift between environments – One configuration baseline promoted through every environment","roles_and_responsibilities":"Delivery lead – Owns delivery and the plan – Ravi Pillai\nBusiness owner – Accepts the scope and the result – Brian Otieno\nExecutive sponsor – Funds the work and decides escalations – Daniel Okafor\nTechnical lead – Owns the technical design – Ravi Pillai\nEnvironment analyst – Books and refreshes environments – Priya Naidoo\nRelease manager – Owns the release calendar – Linda Zhou","glossary":"Target core\tThe new core banking platform that replaces both legacy cores\nMock\tA full rehearsal load of migrated data into the target core\nHypercare\tThe four weeks of extra support after go-live\nSurvivor record\tThe record kept when duplicates are merged\nControl total\tA count or sum used to prove a load is complete","appendices":"Environments and release delivery overview\tDelivery Overview – Environments and release\nEnvironments and release roadmap\tNRB-RM-08\nProgramme architecture principles\tNRB-EA-PR-01","version_history":"0.1\t2026-04-06\tRavi Pillai\tFirst draft\n0.5\t2026-06-14\tRavi Pillai\tComments from Environment and release forum\n0.9\t2026-09-03\tRavi Pillai\tReady for review","related_documents":"NRB-RM-08 – Environments and release roadmap\nDelivery Overview – Environments and release\nNRB-ADR – Architecture decision log","data_architect":"Ravi Pillai","data_domains":"Environment\nBooking\nRelease\nRefresh\nBackup","data_sources":"Legacy core instance 1\nLegacy core instance 2\nDevelopment environment\nTest environment","data_stores":"Booking register\nRelease calendar\nConfiguration repository\nBackup catalogue","conceptual_model":"Environment is the central entity. Booking, Release, Refresh request, Backup set hang off it, each keyed by the target core identifier with the legacy key kept as an alternate key.","logical_model_reference":"NRB-DA-LM-08","master_data_entities":"Environment\nBooking\nRelease\nRefresh request\nBackup set","data_flows":"Masked data refresh: Production to Test environments\nDeployment events: Pipeline to Release calendar\nBackup copy: Production to Recovery environment\nBooking feed: Booking register to Programme dashboard\nConfiguration baseline: Configuration repository to All environments","integration_patterns":["replication","batch","event_streaming"],"data_owners":"Ravi Pillai (Delivery lead)\nBrian Otieno (Business owner)\nRavi Pillai (Technical lead)","data_quality_rules":"Every test stage has a booked environment\nDress rehearsal uses a production-like path\nRefresh is requested and logged\nThe release calendar is the only source of release dates","retention_rules":"Customer and account records kept 7 years after closure\nMigration extracts deleted 90 days after go-live\nReconciliation evidence kept with the go-live pack","classification_levels":["internal","confidential","restricted"],"personal_data_processed":false,"privacy_controls":"Masked data only in lower environments\nAccess to personal data on a need-to-know role\nPersonal data stays in the agreed region","encryption_requirements":"Encrypted at rest in every store\nTLS 1.2 or higher in transit\nMigration extracts encrypted with a programme key"}$j$),
  ('00000000-0000-4000-a01e-000000000009', '00000000-0000-4000-9003-000000000008', 'Operational readiness and hypercare data architecture', 'Data Architecture for operational readiness and hypercare on the Northbridge Bank technology programme. Owner: Linda Zhou.', 'draft', $j${"document_reference":"NRB-DA-09","document_version":"0.9","document_owner":"Linda Zhou","next_review_date":"2026-11-20","purpose":"Describes the data architecture for operational readiness and hypercare on the Northbridge Bank technology programme. Delivery of the support model, runbooks, monitoring handover and the hypercare period after go-live.","objectives":"Every cutover step has a runbook someone has walked through\nHypercare shifts are named, including nights\nThe daily bridge has an agenda and a chair\nSeverity scale matches the defect scale\nMonitoring alerts reach the roster\nKnown errors are written down before go-live","scope":"Support model\nRunbooks for the cutover weekend\nHypercare roster\nDaily hypercare bridge\nSeverity scale for hypercare\nMonitoring handover","out_of_scope":"A new service-desk product\nBranch refurbishment\nA 24-hour contact centre build\nVendor contract renegotiation\nProduction data centre build","assumptions":"Hypercare lasts four weeks\nThe existing service desk is the front door\nRunbooks are steps with an expected result\nNight shifts are required for the first week only\nMonitoring is handed over, not rebuilt","constraints":"Hypercare cannot be staffed by unnamed roles\nA runbook that has not been walked through does not count\nThe first week has night cover\nExit criteria are set before go-live\nThe bridge is every business day in hypercare","risks_mitigations":"Alerts going to a mailbox nobody reads – Alerts routed to the named roster, not a mailbox\nNight shifts left unnamed – Name every shift, including nights, before the dress rehearsal\nRunbooks never walked through – Walk through every runbook in the dress rehearsal\nKnown errors found by customers – Publish the known-error list before go-live\nSeverity 1 response slower than 30 minutes – Severity 1 bridge opened within 15 minutes","roles_and_responsibilities":"Delivery lead – Owns delivery and the plan – Linda Zhou\nBusiness owner – Accepts the scope and the result – Catherine Mwangi\nExecutive sponsor – Funds the work and decides escalations – Grace Moyo\nTechnical lead – Owns the technical design – Ahmed Hassan\nService desk lead – Prepares the service desk for go-live – Brian Otieno\nOperations lead – Owns run procedures after go-live – Ravi Pillai","glossary":"Target core\tThe new core banking platform that replaces both legacy cores\nMock\tA full rehearsal load of migrated data into the target core\nHypercare\tThe four weeks of extra support after go-live\nSurvivor record\tThe record kept when duplicates are merged\nControl total\tA count or sum used to prove a load is complete","appendices":"Operational readiness and hypercare delivery overview\tDelivery Overview – Operational readiness and hypercare\nOperational readiness and hypercare roadmap\tNRB-RM-09\nProgramme architecture principles\tNRB-EA-PR-01","version_history":"0.1\t2026-09-22\tLinda Zhou\tFirst draft\n0.5\t2026-11-30\tAhmed Hassan\tComments from Operational readiness forum\n0.9\t2027-02-22\tLinda Zhou\tReady for review","related_documents":"NRB-RM-09 – Operational readiness and hypercare roadmap\nDelivery Overview – Operational readiness and hypercare\nNRB-ADR – Architecture decision log","data_architect":"Ahmed Hassan","data_domains":"Incident\nAlert\nKnown error\nRunbook\nRoster","data_sources":"Legacy core instance 1\nLegacy core instance 2\nService desk\nMonitoring dashboard","data_stores":"Service management database\nMonitoring store\nKnowledge base\nRoster store","conceptual_model":"Incident is the central entity. Alert rule, Known error, Runbook, Shift hang off it, each keyed by the target core identifier with the legacy key kept as an alternate key.","logical_model_reference":"NRB-DA-LM-09","master_data_entities":"Incident\nAlert rule\nKnown error\nRunbook\nShift","data_flows":"Alert routing: Monitoring to Service management\nIncident updates: Service management to Hypercare bridge\nKnown-error publishing: Knowledge base to Service desk\nRoster feed: Roster store to Alert routing\nStatus page: Service management to Staff intranet","integration_patterns":["event_streaming","real_time_api","batch"],"data_owners":"Linda Zhou (Delivery lead)\nCatherine Mwangi (Business owner)\nAhmed Hassan (Technical lead)","data_quality_rules":"Every cutover step has a runbook someone has walked through\nHypercare shifts are named, including nights\nThe daily bridge has an agenda and a chair\nSeverity scale matches the defect scale","retention_rules":"Customer and account records kept 7 years after closure\nMigration extracts deleted 90 days after go-live\nReconciliation evidence kept with the go-live pack","classification_levels":["internal","confidential","restricted"],"personal_data_processed":true,"privacy_controls":"Masked data only in lower environments\nAccess to personal data on a need-to-know role\nPersonal data stays in the agreed region","encryption_requirements":"Encrypted at rest in every store\nTLS 1.2 or higher in transit\nMigration extracts encrypted with a programme key"}$j$),
  ('00000000-0000-4000-a01e-000000000010', '00000000-0000-4000-9003-000000000008', 'Regulatory reporting data architecture', 'Data Architecture for regulatory reporting. Superseded: the reporting workstream closed on 30 September 2026; kept for reference.', 'superseded', $j${"document_reference":"NRB-DA-10","document_version":"1.0","document_owner":"Olivia Banda","next_review_date":"2027-03-31","purpose":"Describes the data architecture for regulatory reporting on the Northbridge Bank technology programme. Completed delivery of the report-line mapping that lets finance keep the existing reporting tool across the migration.","objectives":"Every report line used in the last year has a mapped source\nThe mock cross-check agreed\nDifferences go to the agreed difference account\nThe financial controller has signed\nFinance did not change tool\nEvidence is in the go-live pack","scope":"Report-line map from the trial balance\nCurrency and company mapping\nFirst mock cross-check\nEvidence pack for finance\nNamed owner per report family\nDifference account treatment","out_of_scope":"A new reporting tool\nPrudential return redesign\nTax engine replacement\nManagement information warehouse\nBoard pack redesign","assumptions":"The finance system stays\nThe chart of accounts does not change for go-live\nLast year of report lines is the scope\nDifferences use account 14918 as already agreed for the journals\nThe controller is the signer","constraints":"No new reporting tool\nThe map cannot drop a line used in the last year\nDifferences have one account\nSign-off is the controller, not the project\nThe guide stays short","risks_mitigations":"A report line missed in the map – Check every report line used in the last year against the map\nA mapped line changing meaning – Reopen rule limited to the affected report\nThe difference account used for something else – Account 14918 reserved for differences only\nCustomer-level data in the evidence pack – Remove customer-level rows from the pack\nController signature on the wrong version – Controller signs the version number on the pack","roles_and_responsibilities":"Delivery lead – Owns delivery and the plan – Olivia Banda\nBusiness owner – Accepts the scope and the result – Olivia Banda\nExecutive sponsor – Funds the work and decides escalations – Grace Moyo\nTechnical lead – Owns the technical design – Priya Naidoo\nFinance analyst – Maps ledger accounts and report lines – Daniel Okafor\nMapping analyst – Maintains the report-line map – Amina Diallo","glossary":"Target core\tThe new core banking platform that replaces both legacy cores\nMock\tA full rehearsal load of migrated data into the target core\nHypercare\tThe four weeks of extra support after go-live\nSurvivor record\tThe record kept when duplicates are merged\nControl total\tA count or sum used to prove a load is complete","appendices":"Regulatory reporting delivery overview\tDelivery Overview – Regulatory reporting\nRegulatory reporting roadmap\tNRB-RM-10\nProgramme architecture principles\tNRB-EA-PR-01","version_history":"0.1\t2026-02-23\tOlivia Banda\tFirst draft\n0.5\t2026-05-03\tPriya Naidoo\tComments from Finance and regulatory forum\n1.0\t2026-09-28\tOlivia Banda\tFinal; workstream closed","related_documents":"NRB-RM-10 – Regulatory reporting roadmap\nDelivery Overview – Regulatory reporting\nNRB-ADR – Architecture decision log","data_architect":"Priya Naidoo","data_domains":"Report line\nGeneral ledger account\nCurrency\nCompany\nEvidence","data_sources":"Legacy core instance 1\nLegacy core instance 2\nFinance and general ledger system\nReporting tool","data_stores":"Mapping workbook\nFinance ledger\nEvidence store\nReport archive","conceptual_model":"Report line is the central entity. Ledger account, Currency code, Company code, Evidence item hang off it, each keyed by the target core identifier with the legacy key kept as an alternate key.","logical_model_reference":"NRB-DA-LM-10","master_data_entities":"Report line\nLedger account\nCurrency code\nCompany code\nEvidence item","data_flows":"Trial balance: Target core to Finance ledger\nReport-line lookup: Mapping workbook to Reporting tool\nDifference postings: Finance ledger to Difference account 14918\nEvidence filing: Reporting tool to Evidence store\nMock cross-check: Migration staging to Reporting tool","integration_patterns":["batch","file_transfer"],"data_owners":"Olivia Banda (Delivery lead)\nOlivia Banda (Business owner)\nPriya Naidoo (Technical lead)","data_quality_rules":"Every report line used in the last year has a mapped source\nThe mock cross-check agreed\nDifferences go to the agreed difference account\nThe financial controller has signed","retention_rules":"Customer and account records kept 7 years after closure\nMigration extracts deleted 90 days after go-live\nReconciliation evidence kept with the go-live pack","classification_levels":["internal","confidential","restricted"],"personal_data_processed":false,"privacy_controls":"Masked data only in lower environments\nAccess to personal data on a need-to-know role\nPersonal data stays in the agreed region","encryption_requirements":"Encrypted at rest in every store\nTLS 1.2 or higher in transit\nMigration extracts encrypted with a programme key"}$j$),
  ('00000000-0000-4000-a01f-000000000001', '00000000-0000-4000-9003-000000000009', 'Customer and digital channels integration architecture', 'Integration Architecture for customer and digital channels on the Northbridge Bank technology programme. Owner: Amina Diallo.', 'draft', $j${"document_reference":"NRB-IA-01","document_version":"0.9","document_owner":"Amina Diallo","next_review_date":"2026-11-16","purpose":"Describes the integration architecture for customer and digital channels on the Northbridge Bank technology programme. Delivery of customer master data and the internet, mobile and branch channels for the Northbridge Bank technology programme.","objectives":"Every active customer has one surviving customer number\nAddress completeness at or above 85%\nInternet and mobile users can sign in on day one\nDuplicate customers reduced below 1%\nMandate images linked to the surviving customer\nBranch search returns the customer in under 3 seconds","scope":"Retail and SME customer master\nCorporate customer master from the second legacy instance\nInternet banking registration\nMobile banking registration\nBranch teller customer search\nContact centre customer view","out_of_scope":"Card plastic personalisation\nMarketing campaign tool\nLoyalty scheme\nInsurance product origination\nWealth advisory portal","assumptions":"Both legacy instances are profiled before Mock 2\nThe surviving record is the one with the most complete KYC data\nCustomers accept a new customer number where numbers clash\nBranch staff are trained before the dress rehearsal\nStatement templates are approved by the business","constraints":"Customer numbers must be unique across both legacy instances\nKYC fields are mandatory before a customer can be loaded\nAddress completeness target is 85%\nImages must be linked before the channel is opened\nThe load window is the weekend of 10–12 April 2027","risks_mitigations":"Account takeover through weak registration checks – Two-factor registration and device binding\nDuplicate customer merged onto the wrong survivor – Survivor rule signed by the business data owner and sample-checked\nMandate images exposed through a direct link – Images served only through the authenticated retrieval API\nCredential stuffing on internet banking sign-in – Rate limits and lock-out on sign-in\nPersonal data copied into test environments – Masked data only in lower environments","roles_and_responsibilities":"Delivery lead – Owns delivery and the plan – Amina Diallo\nBusiness owner – Accepts the scope and the result – Nomvula Khumalo\nExecutive sponsor – Funds the work and decides escalations – Grace Moyo\nTechnical lead – Owns the technical design – Ravi Pillai\nData analyst – Profiles and maps the data – Priya Naidoo\nChannel analyst – Designs channel journeys and entitlements – Brian Otieno","glossary":"Target core\tThe new core banking platform that replaces both legacy cores\nMock\tA full rehearsal load of migrated data into the target core\nHypercare\tThe four weeks of extra support after go-live\nInterface contract\tThe agreed format, timing and owner of one interface\nReplay\tRe-sending a failed message after it has been repaired","appendices":"Customer and digital channels delivery overview\tDelivery Overview – Customer and digital channels\nCustomer and digital channels roadmap\tNRB-RM-01\nProgramme architecture principles\tNRB-EA-PR-01","version_history":"0.1\t2026-04-27\tAmina Diallo\tFirst draft\n0.5\t2026-07-05\tRavi Pillai\tComments from Channels steering group\n0.9\t2026-09-03\tAmina Diallo\tReady for review","related_documents":"NRB-RM-01 – Customer and digital channels roadmap\nDelivery Overview – Customer and digital channels\nNRB-ADR – Architecture decision log","integration_architect":"Ravi Pillai","middleware_integration_platform":"Integration platform with API gateway and event broker","systems_integrated":"Target core\nInternet banking\nObject store\nBranch teller\nMigration staging\nContact centre desktop","integration_patterns":["real_time_api","event_streaming","batch"],"interfaces":"Customer profile sync – Target core – Internet banking – Real-time API – On change\nMandate image retrieval – Object store – Branch teller – Real-time API – On request\nRegistration events – Internet banking – Target core – Event streaming – On event\nCustomer cross-reference load – Migration staging – Target core – Batch – Each mock\nContact centre lookup – Target core – Contact centre desktop – Real-time API – On request","message_formats":["json","csv"],"api_standards":"Versioned REST resources\nOne error format across all APIs\nCorrelation identifier on every message\nContract approved before build","error_handling":"Failed messages go to a repair queue with the original payload; operations repair and replay them, and every replay is idempotent so it cannot create a duplicate.","throughput_targets":"600 customer searches per minute at branch peak\n120 registrations per minute on day one","availability_target":99.9,"monitoring_approach":"Every interface reports success, failure and latency to one dashboard; a failure raises an alert to the interface owner within five minutes.","authentication_methods":["oauth_2_0","mutual_tls"],"security_controls":"Mutual TLS on service-to-service calls\nCertificates inventoried with expiry alerts\nNo shared service accounts\nPayloads with personal data encrypted in transit"}$j$),
  ('00000000-0000-4000-a01f-000000000002', '00000000-0000-4000-9003-000000000009', 'Payments and transfers integration architecture', 'Integration Architecture for payments and transfers on the Northbridge Bank technology programme. Owner: Ahmed Hassan.', 'draft', $j${"document_reference":"NRB-IA-02","document_version":"0.9","document_owner":"Ahmed Hassan","next_review_date":"2026-11-18","purpose":"Describes the integration architecture for payments and transfers on the Northbridge Bank technology programme. Delivery of domestic payments, standing orders and internal transfers onto the target platform.","objectives":"Every active standing order is recreated before go-live\nSettlement totals agree to the cent\nReturned payments land on the repair queue\nChannel limits match the signed matrix\nNo duplicate payment on the cutover weekend\nCut-off calendar loaded for the next 18 months","scope":"Domestic credit transfers\nInternal account transfers\nStanding orders\nFuture-dated payments\nPayment limits by channel\nSettlement timetable","out_of_scope":"Card authorisation\nATM cash\nCheque clearing replacement\nCross-border correspondent banking rebuild\nCash-in-transit","assumptions":"The scheme timetable does not change before go-live\nStanding orders are recreated, not replayed from history\nBoth legacy instances use the same value-date rule\nPayment limits are signed by the business before UAT\nThe repair queue is staffed for hypercare","constraints":"Scheme cut-off cannot move\nSettlement must balance on the night\nStanding orders with an end date in the past are excluded\nDual control stays on the repair queue\nPayment files are not accepted during the freeze","risks_mitigations":"Duplicate payment on the cutover weekend – Idempotent posting keyed on the payment reference\nChannel limits looser than the signed matrix – Load limits from the signed matrix and test every band\nScheme certificate expiry – Certificate inventory with 60-day expiry alerts\nTampered payment file in transit – Signed and encrypted payment files\nRepair actions without dual control – Dual control enforced on every repair action","roles_and_responsibilities":"Delivery lead – Owns delivery and the plan – Ahmed Hassan\nBusiness owner – Accepts the scope and the result – Catherine Mwangi\nExecutive sponsor – Funds the work and decides escalations – Daniel Okafor\nTechnical lead – Owns the technical design – Brian Otieno\nSettlement analyst – Designs settlement and reconciliation – Olivia Banda\nTest lead – Owns test entry, exit and evidence – Priya Naidoo","glossary":"Target core\tThe new core banking platform that replaces both legacy cores\nMock\tA full rehearsal load of migrated data into the target core\nHypercare\tThe four weeks of extra support after go-live\nInterface contract\tThe agreed format, timing and owner of one interface\nReplay\tRe-sending a failed message after it has been repaired","appendices":"Payments and transfers delivery overview\tDelivery Overview – Payments and transfers\nPayments and transfers roadmap\tNRB-RM-02\nProgramme architecture principles\tNRB-EA-PR-01","version_history":"0.1\t2026-05-25\tAhmed Hassan\tFirst draft\n0.5\t2026-08-02\tBrian Otieno\tComments from Payments working group\n0.9\t2026-10-04\tAhmed Hassan\tReady for review","related_documents":"NRB-RM-02 – Payments and transfers roadmap\nDelivery Overview – Payments and transfers\nNRB-ADR – Architecture decision log","integration_architect":"Brian Otieno","middleware_integration_platform":"Integration platform with API gateway and event broker","systems_integrated":"Target core\nScheme gateway\nInternet banking\nRepair queue\nNotification service","integration_patterns":["event_streaming","file_transfer","real_time_api"],"interfaces":"Outbound credit transfers – Target core – Scheme gateway – File transfer – Every settlement cycle\nInbound credits – Scheme gateway – Target core – File transfer – Every settlement cycle\nPayment status events – Target core – Internet banking – Event streaming – On event\nReturned items – Scheme gateway – Repair queue – Batch – Daily\nNotification dispatch – Target core – Notification service – Event streaming – On event","message_formats":["iso_20022","json"],"api_standards":"Versioned REST resources\nOne error format across all APIs\nCorrelation identifier on every message\nContract approved before build","error_handling":"Failed messages go to a repair queue with the original payload; operations repair and replay them, and every replay is idempotent so it cannot create a duplicate.","throughput_targets":"250 payments per second at month-end peak\n1.2 million standing orders processed in one run","availability_target":99.95,"monitoring_approach":"Every interface reports success, failure and latency to one dashboard; a failure raises an alert to the interface owner within five minutes.","authentication_methods":["mutual_tls","certificates"],"security_controls":"Mutual TLS on service-to-service calls\nCertificates inventoried with expiry alerts\nNo shared service accounts\nPayloads with personal data encrypted in transit"}$j$),
  ('00000000-0000-4000-a01f-000000000003', '00000000-0000-4000-9003-000000000009', 'Lending, limits and collateral integration architecture', 'Integration Architecture for lending, limits and collateral on the Northbridge Bank technology programme. Owner: Joy Akinyi.', 'draft', $j${"document_reference":"NRB-IA-03","document_version":"0.9","document_owner":"Joy Akinyi","next_review_date":"2026-11-11","purpose":"Describes the integration architecture for lending, limits and collateral on the Northbridge Bank technology programme. Delivery of loans, limits and collateral, including overdue bills and the expired-limit rule.","objectives":"Every live loan has an arrangement, a balance and a schedule\nAgeing continues from the legacy past-due date\nExpired limits follow the signed rule\nCollateral is linked before the loan is loaded\nOne repayment account per customer per currency\nTake-over accounts return to zero","scope":"Retail loan arrangements\nCorporate loan arrangements\nOverdue and due bills\nAccrued interest on loans\nLimit records\nExpired limits still linked to a contract","out_of_scope":"New scorecard build\nDebt collection agency files\nSecuritisation\nSyndicated loan agency\nTrade finance instruments","assumptions":"Schedules are regenerated from the migrated frequency\nThe expired-limit rule is expiry plus one day, with the original date kept\nOne liquidation account is allowed per customer per currency\nCollateral rights load before collateral items\nPast-due date becomes the bill date","constraints":"A loan cannot load before its customer and account\nCollateral cannot load before its right\nAgeing must not reset to zero\nExpired limits cannot be dropped while a contract is live\nTake-over accounts must be zero after reconciliation","risks_mitigations":"Expired limit left securing a live contract – Expired-limit rule signed and every case on a credit review queue\nCollateral loaded before its right and rejected – Load rights before items, rehearsed in Mock 2\nAccrual counted twice after migration – Accrual value date set to the migration date\nUnauthorised limit override – Limit overrides need a second approver\nCredit data exposed to non-credit staff – Credit screens limited to credit roles","roles_and_responsibilities":"Delivery lead – Owns delivery and the plan – Joy Akinyi\nBusiness owner – Accepts the scope and the result – Daniel Okafor\nExecutive sponsor – Funds the work and decides escalations – Grace Moyo\nTechnical lead – Owns the technical design – Priya Naidoo\nCredit analyst – Defines lending and limit rules – Ahmed Hassan\nCollateral analyst – Maps collateral rights and items – Linda Zhou","glossary":"Target core\tThe new core banking platform that replaces both legacy cores\nMock\tA full rehearsal load of migrated data into the target core\nHypercare\tThe four weeks of extra support after go-live\nInterface contract\tThe agreed format, timing and owner of one interface\nReplay\tRe-sending a failed message after it has been repaired","appendices":"Lending, limits and collateral delivery overview\tDelivery Overview – Lending, limits and collateral\nLending, limits and collateral roadmap\tNRB-RM-03\nProgramme architecture principles\tNRB-EA-PR-01","version_history":"0.1\t2026-06-08\tJoy Akinyi\tFirst draft\n0.5\t2026-08-16\tPriya Naidoo\tComments from Credit design authority\n0.9\t2026-10-21\tJoy Akinyi\tReady for review","related_documents":"NRB-RM-03 – Lending, limits and collateral roadmap\nDelivery Overview – Lending, limits and collateral\nNRB-ADR – Architecture decision log","integration_architect":"Priya Naidoo","middleware_integration_platform":"Integration platform with API gateway and event broker","systems_integrated":"Collateral register\nTarget core\nFinance ledger\nCollections system\nCredit risk reporting\nMigration staging","integration_patterns":["batch","real_time_api"],"interfaces":"Collateral to loan link – Collateral register – Target core – Real-time API – On change\nLoan balances – Target core – Finance ledger – Batch – Daily\nArrears status – Target core – Collections system – Batch – Daily\nLimit utilisation – Target core – Credit risk reporting – Batch – Daily\nLoan migration load – Migration staging – Target core – Batch – Each mock","message_formats":["csv","json"],"api_standards":"Versioned REST resources\nOne error format across all APIs\nCorrelation identifier on every message\nContract approved before build","error_handling":"Failed messages go to a repair queue with the original payload; operations repair and replay them, and every replay is idempotent so it cannot create a duplicate.","throughput_targets":"180,000 loans scheduled overnight\n2,000 credit enquiries per hour","availability_target":99.5,"monitoring_approach":"Every interface reports success, failure and latency to one dashboard; a failure raises an alert to the interface owner within five minutes.","authentication_methods":["mutual_tls","oauth_2_0"],"security_controls":"Mutual TLS on service-to-service calls\nCertificates inventoried with expiry alerts\nNo shared service accounts\nPayloads with personal data encrypted in transit"}$j$),
  ('00000000-0000-4000-a01f-000000000004', '00000000-0000-4000-9003-000000000009', 'Deposits and accounts integration architecture', 'Integration Architecture for deposits and accounts on the Northbridge Bank technology programme. Owner: Catherine Mwangi.', 'draft', $j${"document_reference":"NRB-IA-04","document_version":"0.9","document_owner":"Catherine Mwangi","next_review_date":"2026-11-17","purpose":"Describes the integration architecture for deposits and accounts on the Northbridge Bank technology programme. Delivery of current accounts, savings and term deposits, including balances and accruals.","objectives":"Every open account has a product, a balance and an owner\nInstance 2 account numbers are kept as alternate keys\nDormant accounts over five years are closed or transferred\nMatured deposits no longer carry a balance at the freeze\nRestrictions match the legacy narrative\nStatement frequency is remapped","scope":"Current accounts\nSavings accounts\nTerm deposits\nDeposit balances and accruals\nDormant accounts over five years\nMatured deposits that still hold a balance","out_of_scope":"Safe custody\nNew savings product launch\nPrize-linked savings\nChildren account campaign\nBrokerage cash accounts","assumptions":"Three legacy current-account products become one target product\nInstance 2 numbers become 10 digits with a check digit\nDormant means no customer-initiated transaction for five years\nUnclaimed balances move under the existing regulation\nMatured deposits are paid out or rolled, not migrated as running","constraints":"No account closures in the week before go-live\nA zero-balance account marked for closure is excluded\nAlternate keys are mandatory for instance 2\nAccrual value date cannot be the original accrual date\nProduct mapping cannot change after Mock 2 without a new approval","risks_mitigations":"Matured deposit still carrying a balance at the freeze – Pay out or roll matured deposits before the freeze\nAccount numbers clashing across the two instances – 10-digit numbers with check digit and alternate keys\nRestriction narrative dropped in migration – Sample-check restriction narratives after each mock\nStatement sent to the wrong address – Address taken from the survivor customer record\nInterest accrued twice – Accrual reconciled by product after Mock 3","roles_and_responsibilities":"Delivery lead – Owns delivery and the plan – Catherine Mwangi\nBusiness owner – Accepts the scope and the result – Nomvula Khumalo\nExecutive sponsor – Funds the work and decides escalations – Olivia Banda\nTechnical lead – Owns the technical design – Brian Otieno\nProduct analyst – Maps products to the target core – Amina Diallo\nFinance partner – Agrees accounting and control totals – Daniel Okafor","glossary":"Target core\tThe new core banking platform that replaces both legacy cores\nMock\tA full rehearsal load of migrated data into the target core\nHypercare\tThe four weeks of extra support after go-live\nInterface contract\tThe agreed format, timing and owner of one interface\nReplay\tRe-sending a failed message after it has been repaired","appendices":"Deposits and accounts delivery overview\tDelivery Overview – Deposits and accounts\nDeposits and accounts roadmap\tNRB-RM-04\nProgramme architecture principles\tNRB-EA-PR-01","version_history":"0.1\t2026-05-11\tCatherine Mwangi\tFirst draft\n0.5\t2026-07-19\tBrian Otieno\tComments from Deposits product forum\n0.9\t2026-09-26\tCatherine Mwangi\tReady for review","related_documents":"NRB-RM-04 – Deposits and accounts roadmap\nDelivery Overview – Deposits and accounts\nNRB-ADR – Architecture decision log","integration_architect":"Brian Otieno","middleware_integration_platform":"Integration platform with API gateway and event broker","systems_integrated":"Target core\nInternet banking\nStatement engine\nOperations\nMigration staging\nFinance ledger","integration_patterns":["batch","real_time_api"],"interfaces":"Balance enquiry – Target core – Internet banking – Real-time API – On request\nStatement generation – Target core – Statement engine – Batch – Monthly\nDormant account report – Target core – Operations – Batch – Monthly\nAccount migration load – Migration staging – Target core – Batch – Each mock\nGeneral ledger postings – Target core – Finance ledger – Batch – Daily","message_formats":["csv","json","fixed_width"],"api_standards":"Versioned REST resources\nOne error format across all APIs\nCorrelation identifier on every message\nContract approved before build","error_handling":"Failed messages go to a repair queue with the original payload; operations repair and replay them, and every replay is idempotent so it cannot create a duplicate.","throughput_targets":"2.4 million accounts accrued overnight\n900 balance enquiries per second at peak","availability_target":99.9,"monitoring_approach":"Every interface reports success, failure and latency to one dashboard; a failure raises an alert to the interface owner within five minutes.","authentication_methods":["mutual_tls","oauth_2_0"],"security_controls":"Mutual TLS on service-to-service calls\nCertificates inventoried with expiry alerts\nNo shared service accounts\nPayloads with personal data encrypted in transit"}$j$),
  ('00000000-0000-4000-a01f-000000000005', '00000000-0000-4000-9003-000000000009', 'Data migration and quality integration architecture', 'Integration Architecture for data migration and quality on the Northbridge Bank technology programme. Owner: Priya Naidoo.', 'draft', $j${"document_reference":"NRB-IA-05","document_version":"0.9","document_owner":"Priya Naidoo","next_review_date":"2026-11-13","purpose":"Describes the integration architecture for data migration and quality on the Northbridge Bank technology programme. Cross-cutting delivery of extraction, cleansing, transformation, mock runs and reconciliation for the programme.","objectives":"Mock 2 static data loads inside the window\nMock 3 financial data reconciles\nDress rehearsal finishes with no severity-1 defect open\nTake-over and suspense accounts are zero\nEach population has a named data owner\nControl totals tie to the trial balance","scope":"Source profiling\nExtraction from both legacy instances\nCleansing at source\nTransformation rules\nMock runs\nDress rehearsal","out_of_scope":"Building the target platform\nCard scheme certification\nGeneral ledger replacement\nStaff identity directory rebuild\nA new data warehouse","assumptions":"Three mock runs and one dress rehearsal are enough\nCleansing is done in the source, not in the load\nThe file layout is plain text, one record per line\nDates travel as YYYYMMDD\nControl totals come from the final close of business","constraints":"The April 2027 weekend is fixed\nPersonal data stays in the residency region\nA population cannot load before its predecessor\nSeverity-1 defects block the next mock\nTake-over accounts must finish at zero","risks_mitigations":"Production data copied into a shared workbook – Remove samples from shared workbooks; extracts stay in the staging store\nExtract taken before close of business – Extract after close of business, checked on the mock entry list\nTake-over accounts not at zero – Reconcile take-over accounts to zero before sign-off\nUnmasked data in a lower environment – Masking applied before any refresh\nLoad window overrun – Three mocks with the window measured each time","roles_and_responsibilities":"Delivery lead – Owns delivery and the plan – Priya Naidoo\nBusiness data owner – Signs off the data population – Amina Diallo\nExecutive sponsor – Funds the work and decides escalations – Olivia Banda\nTechnical lead – Owns the technical design – Brian Otieno\nReconciliation lead – Proves control totals after each load – Olivia Banda\nFinance partner – Agrees accounting and control totals – Daniel Okafor","glossary":"Target core\tThe new core banking platform that replaces both legacy cores\nMock\tA full rehearsal load of migrated data into the target core\nHypercare\tThe four weeks of extra support after go-live\nInterface contract\tThe agreed format, timing and owner of one interface\nReplay\tRe-sending a failed message after it has been repaired","appendices":"Data migration and quality delivery overview\tDelivery Overview – Data migration and quality\nData migration and quality roadmap\tNRB-RM-05\nProgramme architecture principles\tNRB-EA-PR-01","version_history":"0.1\t2026-03-23\tPriya Naidoo\tFirst draft\n0.5\t2026-05-31\tBrian Otieno\tComments from Data migration design authority\n0.9\t2026-08-11\tPriya Naidoo\tReady for review","related_documents":"NRB-RM-05 – Data migration and quality roadmap\nDelivery Overview – Data migration and quality\nNRB-ADR – Architecture decision log","integration_architect":"Brian Otieno","middleware_integration_platform":"Integration platform with API gateway and event broker","systems_integrated":"Legacy core 1\nStaging\nLegacy core 2\nTarget core\nReconciliation engine\nFinance ledger","integration_patterns":["etl_elt","file_transfer","batch"],"interfaces":"Legacy instance 1 extract – Legacy core 1 – Staging – File transfer – Each mock\nLegacy instance 2 extract – Legacy core 2 – Staging – File transfer – Each mock\nTarget load – Staging – Target core – Batch – Each mock\nControl totals – Target core – Reconciliation engine – Batch – Each mock\nTrial balance feed – Finance ledger – Reconciliation engine – File transfer – Each mock","message_formats":["csv","fixed_width"],"api_standards":"Versioned REST resources\nOne error format across all APIs\nCorrelation identifier on every message\nContract approved before build","error_handling":"Failed messages go to a repair queue with the original payload; operations repair and replay them, and every replay is idempotent so it cannot create a duplicate.","throughput_targets":"4.8 million static records inside 14 hours\n12 million financial records inside 10 hours","availability_target":99,"monitoring_approach":"Every interface reports success, failure and latency to one dashboard; a failure raises an alert to the interface owner within five minutes.","authentication_methods":["certificates","mutual_tls"],"security_controls":"Mutual TLS on service-to-service calls\nCertificates inventoried with expiry alerts\nNo shared service accounts\nPayloads with personal data encrypted in transit"}$j$),
  ('00000000-0000-4000-a01f-000000000006', '00000000-0000-4000-9003-000000000009', 'Integration and interfaces integration architecture', 'Integration Architecture for integration and interfaces on the Northbridge Bank technology programme. Owner: Brian Otieno.', 'draft', $j${"document_reference":"NRB-IA-06","document_version":"0.9","document_owner":"Brian Otieno","next_review_date":"2026-11-19","purpose":"Describes the integration architecture for integration and interfaces on the Northbridge Bank technology programme. Delivery of the interfaces the target platform needs from channels, cards, finance, documents and the user store.","objectives":"Each in-scope interface has a contract, a test and an owner\nFailed messages are visible on one dashboard\nCard status cross-check agrees active cards\nTrial-balance file balances before it is used\nImage retrieval works for a mandate\nChannels no longer call the legacy cores after go-live","scope":"Internet banking interface\nMobile banking interface\nBranch teller interface\nContact centre interface\nCard status cross-check\nDocument image retrieval","out_of_scope":"A new integration platform product selection\nOpen-banking directory build\nCard scheme certification\nATM switch replacement\nPoint of sale acquiring","assumptions":"Existing channels are reused and pointed at the target\nThe card system is not migrated; only status is cross-checked\nThe finance system stays and sends a file\nCertificates can be renewed without a scheme change\nOne dashboard covers every in-scope interface","constraints":"SIT entry dates are fixed on the integration plan\nA missing certificate blocks that interface\nCard numbers are not stored on the dashboard\nThe trial-balance file is after close of business\nReplay cannot create a second payment","risks_mitigations":"Silent message loss – Every interface reports to one dashboard with alerts\nCertificate expiring in hypercare – Certificates valid through hypercare, renewed before the freeze\nReplay creating a duplicate payment – Idempotent replay keyed on the message identifier\nA channel still calling the legacy core – Remove legacy addresses and test from each channel\nUnauthenticated internal API – Mutual TLS on every internal API","roles_and_responsibilities":"Delivery lead – Owns delivery and the plan – Brian Otieno\nBusiness owner – Accepts the scope and the result – Ravi Pillai\nExecutive sponsor – Funds the work and decides escalations – Daniel Okafor\nTechnical lead – Owns the technical design – Ravi Pillai\nInterface analyst – Writes and tests interface contracts – Priya Naidoo\nTest lead – Owns test entry, exit and evidence – Catherine Mwangi","glossary":"Target core\tThe new core banking platform that replaces both legacy cores\nMock\tA full rehearsal load of migrated data into the target core\nHypercare\tThe four weeks of extra support after go-live\nInterface contract\tThe agreed format, timing and owner of one interface\nReplay\tRe-sending a failed message after it has been repaired","appendices":"Integration and interfaces delivery overview\tDelivery Overview – Integration and interfaces\nIntegration and interfaces roadmap\tNRB-RM-06\nProgramme architecture principles\tNRB-EA-PR-01","version_history":"0.1\t2026-06-22\tBrian Otieno\tFirst draft\n0.5\t2026-08-30\tRavi Pillai\tComments from Integration design authority\n0.9\t2026-11-13\tBrian Otieno\tReady for review","related_documents":"NRB-RM-06 – Integration and interfaces roadmap\nDelivery Overview – Integration and interfaces\nNRB-ADR – Architecture decision log","integration_architect":"Ravi Pillai","middleware_integration_platform":"Integration platform with API gateway and event broker","systems_integrated":"Card platform\nTarget core\nFinance ledger\nObject store\nChannels\nIdentity provider\nNotification service","integration_patterns":["real_time_api","event_streaming","file_transfer"],"interfaces":"Card status cross-check – Card platform – Target core – File transfer – Daily\nFinance trial balance – Target core – Finance ledger – File transfer – Daily\nDocument image retrieval – Object store – Channels – Real-time API – On request\nDigital user store link – Identity provider – Target core – Real-time API – On change\nNotification dispatch – Target core – Notification service – Event streaming – On event","message_formats":["json","xml","iso_20022"],"api_standards":"Versioned REST resources\nOne error format across all APIs\nCorrelation identifier on every message\nContract approved before build","error_handling":"Failed messages go to a repair queue with the original payload; operations repair and replay them, and every replay is idempotent so it cannot create a duplicate.","throughput_targets":"3,000 API calls per second at peak\n400 events per second sustained","availability_target":99.95,"monitoring_approach":"Every interface reports success, failure and latency to one dashboard; a failure raises an alert to the interface owner within five minutes.","authentication_methods":["oauth_2_0","mutual_tls","certificates"],"security_controls":"Mutual TLS on service-to-service calls\nCertificates inventoried with expiry alerts\nNo shared service accounts\nPayloads with personal data encrypted in transit"}$j$),
  ('00000000-0000-4000-a01f-000000000007', '00000000-0000-4000-9003-000000000009', 'Cybersecurity and access integration architecture', 'Integration Architecture for cybersecurity and access on the Northbridge Bank technology programme. Owner: Nadia Rahman.', 'draft', $j${"document_reference":"NRB-IA-07","document_version":"0.9","document_owner":"Nadia Rahman","next_review_date":"2026-11-24","purpose":"Describes the integration architecture for cybersecurity and access on the Northbridge Bank technology programme. Delivery of user access, recertification and the security controls required before go-live. Currently on hold.","objectives":"Every loaded user has a recertified entitlement\nLeavers are absent from the load\nPrivileged access is listed and approved\nStaff can sign in on day one\nLogging meets the agreed control\nAudit can see who approved each role","scope":"Bank user profiles\nUser groups and roles\nLine-manager recertification\nPrivileged access\nJoiner, mover and leaver handling\nAuthentication for staff","out_of_scope":"Customer authentication redesign\nA new identity product selection\nBuilding access\nCard PIN platform\nEndpoint replacement","assumptions":"Line managers recertify their own staff\nThe identity directory is a source, not a system being replaced\nPrivileged access is a separate list\nLeavers are removed in the source before extract\nCustomer sign-in is owned by the channels delivery","constraints":"User load cannot start before recertification\nThe freeze date does not move for this workstream alone\nPrivileged access requires two approvers\nPersonal data in access logs follows the retention schedule\nA leaver cannot be loaded","risks_mitigations":"Leaver loaded into the target platform – Leaver extract applied before every user load\nShared identity created to save time – Named identities only; shared accounts refused\nPrivileged access copied unchanged – Privileged roles rebuilt and approved, not copied\nLogging weaker than the agreed control – Logging checked against the control before go-live\nSame-day revocation not possible in hypercare – Same-day revocation process tested with the service desk","roles_and_responsibilities":"Delivery lead – Owns delivery and the plan – Nadia Rahman\nBusiness owner – Accepts the scope and the result – Daniel Okafor\nExecutive sponsor – Funds the work and decides escalations – Grace Moyo\nTechnical lead – Owns the technical design – Nadia Rahman\nAccess analyst – Builds the role catalogue and access reviews – Ravi Pillai\nAudit partner – Checks evidence for audit – Olivia Banda","glossary":"Target core\tThe new core banking platform that replaces both legacy cores\nMock\tA full rehearsal load of migrated data into the target core\nHypercare\tThe four weeks of extra support after go-live\nInterface contract\tThe agreed format, timing and owner of one interface\nReplay\tRe-sending a failed message after it has been repaired","appendices":"Cybersecurity and access delivery overview\tDelivery Overview – Cybersecurity and access\nCybersecurity and access roadmap\tNRB-RM-07\nProgramme architecture principles\tNRB-EA-PR-01","version_history":"0.1\t2026-07-06\tNadia Rahman\tFirst draft\n0.5\t2026-09-13\tNadia Rahman\tComments from Security design authority\n0.9\t2026-11-30\tNadia Rahman\tReady for review","related_documents":"NRB-RM-07 – Cybersecurity and access roadmap\nDelivery Overview – Cybersecurity and access\nNRB-ADR – Architecture decision log","integration_architect":"Nadia Rahman","middleware_integration_platform":"Integration platform with API gateway and event broker","systems_integrated":"HR system\nIdentity provider\nTarget core\nSecurity monitoring\nRecertification tool\nAudit store\nAccess vault","integration_patterns":["batch","real_time_api","event_streaming"],"interfaces":"Joiner, mover and leaver feed – HR system – Identity provider – Batch – Daily\nRole provisioning – Identity provider – Target core – Real-time API – On change\nSecurity events – Target core – Security monitoring – Event streaming – On event\nRecertification evidence – Recertification tool – Audit store – Batch – Each campaign\nPrivileged session logs – Access vault – Security monitoring – Event streaming – On event","message_formats":["json","csv"],"api_standards":"Versioned REST resources\nOne error format across all APIs\nCorrelation identifier on every message\nContract approved before build","error_handling":"Failed messages go to a repair queue with the original payload; operations repair and replay them, and every replay is idempotent so it cannot create a duplicate.","throughput_targets":"4,200 staff identities\n1 million security events per day","availability_target":99.9,"monitoring_approach":"Every interface reports success, failure and latency to one dashboard; a failure raises an alert to the interface owner within five minutes.","authentication_methods":["saml","mutual_tls","oauth_2_0"],"security_controls":"Mutual TLS on service-to-service calls\nCertificates inventoried with expiry alerts\nNo shared service accounts\nPayloads with personal data encrypted in transit"}$j$),
  ('00000000-0000-4000-a01f-000000000008', '00000000-0000-4000-9003-000000000009', 'Environments and release integration architecture', 'Integration Architecture for environments and release on the Northbridge Bank technology programme. Owner: Ravi Pillai.', 'draft', $j${"document_reference":"NRB-IA-08","document_version":"0.9","document_owner":"Ravi Pillai","next_review_date":"2026-11-18","purpose":"Describes the integration architecture for environments and release on the Northbridge Bank technology programme. Delivery of the environment path from development through dress rehearsal, production and recovery, and the release calendar that uses it.","objectives":"Every test stage has a booked environment\nDress rehearsal uses a production-like path\nRefresh is requested and logged\nThe release calendar is the only source of release dates\nRecovery is restored and checked before go-live\nNo two mocks share an environment","scope":"Development environment\nTest environment\nSystem integration environment\nUser acceptance environment\nPre-production\nProduction cutover runbook","out_of_scope":"A new data centre build\nEnd-user device replacement\nNetwork redesign\nCloud provider selection\nProduction support model","assumptions":"Existing hosting is reused\nProduction-like data is masked except in dress rehearsal under approval\nOne calendar is enough\nRecovery is a restore test, not a second data centre project\nTeams will book if the booking is easier than asking in a chat","constraints":"The dress rehearsal date is fixed once booked\nMasked data is the default\nProduction access is named people only\nTwo mocks cannot share an environment\nA refresh during execution is refused","risks_mitigations":"Refresh using unmasked production data – Masking approved and applied before refresh\nTwo mocks booked on one environment – One booking register, mandatory from SIT\nRecovery backup that cannot be restored – Recovery restore rehearsed before go-live\nProduction access wider than the named list – Named production access list reviewed monthly\nConfiguration drift between environments – One configuration baseline promoted through every environment","roles_and_responsibilities":"Delivery lead – Owns delivery and the plan – Ravi Pillai\nBusiness owner – Accepts the scope and the result – Brian Otieno\nExecutive sponsor – Funds the work and decides escalations – Daniel Okafor\nTechnical lead – Owns the technical design – Ravi Pillai\nEnvironment analyst – Books and refreshes environments – Priya Naidoo\nRelease manager – Owns the release calendar – Linda Zhou","glossary":"Target core\tThe new core banking platform that replaces both legacy cores\nMock\tA full rehearsal load of migrated data into the target core\nHypercare\tThe four weeks of extra support after go-live\nInterface contract\tThe agreed format, timing and owner of one interface\nReplay\tRe-sending a failed message after it has been repaired","appendices":"Environments and release delivery overview\tDelivery Overview – Environments and release\nEnvironments and release roadmap\tNRB-RM-08\nProgramme architecture principles\tNRB-EA-PR-01","version_history":"0.1\t2026-04-06\tRavi Pillai\tFirst draft\n0.5\t2026-06-14\tRavi Pillai\tComments from Environment and release forum\n0.9\t2026-09-03\tRavi Pillai\tReady for review","related_documents":"NRB-RM-08 – Environments and release roadmap\nDelivery Overview – Environments and release\nNRB-ADR – Architecture decision log","integration_architect":"Ravi Pillai","middleware_integration_platform":"Integration platform with API gateway and event broker","systems_integrated":"Production\nTest environments\nPipeline\nRelease calendar\nRecovery environment\nBooking register\nProgramme dashboard\nConfiguration repository\nAll environments","integration_patterns":["replication","batch","event_streaming"],"interfaces":"Masked data refresh – Production – Test environments – Replication – On request\nDeployment events – Pipeline – Release calendar – Event streaming – On event\nBackup copy – Production – Recovery environment – Replication – Nightly\nBooking feed – Booking register – Programme dashboard – Batch – Daily\nConfiguration baseline – Configuration repository – All environments – Batch – Each release","message_formats":["json","csv"],"api_standards":"Versioned REST resources\nOne error format across all APIs\nCorrelation identifier on every message\nContract approved before build","error_handling":"Failed messages go to a repair queue with the original payload; operations repair and replay them, and every replay is idempotent so it cannot create a duplicate.","throughput_targets":"7 environments on one booking register\n2 releases per month until the freeze","availability_target":99,"monitoring_approach":"Every interface reports success, failure and latency to one dashboard; a failure raises an alert to the interface owner within five minutes.","authentication_methods":["certificates","oauth_2_0"],"security_controls":"Mutual TLS on service-to-service calls\nCertificates inventoried with expiry alerts\nNo shared service accounts\nPayloads with personal data encrypted in transit"}$j$),
  ('00000000-0000-4000-a01f-000000000009', '00000000-0000-4000-9003-000000000009', 'Operational readiness and hypercare integration architecture', 'Integration Architecture for operational readiness and hypercare on the Northbridge Bank technology programme. Owner: Linda Zhou.', 'draft', $j${"document_reference":"NRB-IA-09","document_version":"0.9","document_owner":"Linda Zhou","next_review_date":"2026-11-20","purpose":"Describes the integration architecture for operational readiness and hypercare on the Northbridge Bank technology programme. Delivery of the support model, runbooks, monitoring handover and the hypercare period after go-live.","objectives":"Every cutover step has a runbook someone has walked through\nHypercare shifts are named, including nights\nThe daily bridge has an agenda and a chair\nSeverity scale matches the defect scale\nMonitoring alerts reach the roster\nKnown errors are written down before go-live","scope":"Support model\nRunbooks for the cutover weekend\nHypercare roster\nDaily hypercare bridge\nSeverity scale for hypercare\nMonitoring handover","out_of_scope":"A new service-desk product\nBranch refurbishment\nA 24-hour contact centre build\nVendor contract renegotiation\nProduction data centre build","assumptions":"Hypercare lasts four weeks\nThe existing service desk is the front door\nRunbooks are steps with an expected result\nNight shifts are required for the first week only\nMonitoring is handed over, not rebuilt","constraints":"Hypercare cannot be staffed by unnamed roles\nA runbook that has not been walked through does not count\nThe first week has night cover\nExit criteria are set before go-live\nThe bridge is every business day in hypercare","risks_mitigations":"Alerts going to a mailbox nobody reads – Alerts routed to the named roster, not a mailbox\nNight shifts left unnamed – Name every shift, including nights, before the dress rehearsal\nRunbooks never walked through – Walk through every runbook in the dress rehearsal\nKnown errors found by customers – Publish the known-error list before go-live\nSeverity 1 response slower than 30 minutes – Severity 1 bridge opened within 15 minutes","roles_and_responsibilities":"Delivery lead – Owns delivery and the plan – Linda Zhou\nBusiness owner – Accepts the scope and the result – Catherine Mwangi\nExecutive sponsor – Funds the work and decides escalations – Grace Moyo\nTechnical lead – Owns the technical design – Ahmed Hassan\nService desk lead – Prepares the service desk for go-live – Brian Otieno\nOperations lead – Owns run procedures after go-live – Ravi Pillai","glossary":"Target core\tThe new core banking platform that replaces both legacy cores\nMock\tA full rehearsal load of migrated data into the target core\nHypercare\tThe four weeks of extra support after go-live\nInterface contract\tThe agreed format, timing and owner of one interface\nReplay\tRe-sending a failed message after it has been repaired","appendices":"Operational readiness and hypercare delivery overview\tDelivery Overview – Operational readiness and hypercare\nOperational readiness and hypercare roadmap\tNRB-RM-09\nProgramme architecture principles\tNRB-EA-PR-01","version_history":"0.1\t2026-09-22\tLinda Zhou\tFirst draft\n0.5\t2026-11-30\tAhmed Hassan\tComments from Operational readiness forum\n0.9\t2027-02-22\tLinda Zhou\tReady for review","related_documents":"NRB-RM-09 – Operational readiness and hypercare roadmap\nDelivery Overview – Operational readiness and hypercare\nNRB-ADR – Architecture decision log","integration_architect":"Ahmed Hassan","middleware_integration_platform":"Integration platform with API gateway and event broker","systems_integrated":"Monitoring\nService management\nHypercare bridge\nKnowledge base\nService desk\nRoster store\nAlert routing\nStaff intranet","integration_patterns":["event_streaming","real_time_api","batch"],"interfaces":"Alert routing – Monitoring – Service management – Event streaming – On event\nIncident updates – Service management – Hypercare bridge – Real-time API – On change\nKnown-error publishing – Knowledge base – Service desk – Batch – Daily\nRoster feed – Roster store – Alert routing – Batch – Weekly\nStatus page – Service management – Staff intranet – Real-time API – On change","message_formats":["json"],"api_standards":"Versioned REST resources\nOne error format across all APIs\nCorrelation identifier on every message\nContract approved before build","error_handling":"Failed messages go to a repair queue with the original payload; operations repair and replay them, and every replay is idempotent so it cannot create a duplicate.","throughput_targets":"Up to 600 incidents in the first week\n40 alert rules handed over","availability_target":99.5,"monitoring_approach":"Every interface reports success, failure and latency to one dashboard; a failure raises an alert to the interface owner within five minutes.","authentication_methods":["oauth_2_0","saml"],"security_controls":"Mutual TLS on service-to-service calls\nCertificates inventoried with expiry alerts\nNo shared service accounts\nPayloads with personal data encrypted in transit"}$j$),
  ('00000000-0000-4000-a01f-000000000010', '00000000-0000-4000-9003-000000000009', 'Regulatory reporting integration architecture', 'Integration Architecture for regulatory reporting. Superseded: the reporting workstream closed on 30 September 2026; kept for reference.', 'superseded', $j${"document_reference":"NRB-IA-10","document_version":"1.0","document_owner":"Olivia Banda","next_review_date":"2027-03-31","purpose":"Describes the integration architecture for regulatory reporting on the Northbridge Bank technology programme. Completed delivery of the report-line mapping that lets finance keep the existing reporting tool across the migration.","objectives":"Every report line used in the last year has a mapped source\nThe mock cross-check agreed\nDifferences go to the agreed difference account\nThe financial controller has signed\nFinance did not change tool\nEvidence is in the go-live pack","scope":"Report-line map from the trial balance\nCurrency and company mapping\nFirst mock cross-check\nEvidence pack for finance\nNamed owner per report family\nDifference account treatment","out_of_scope":"A new reporting tool\nPrudential return redesign\nTax engine replacement\nManagement information warehouse\nBoard pack redesign","assumptions":"The finance system stays\nThe chart of accounts does not change for go-live\nLast year of report lines is the scope\nDifferences use account 14918 as already agreed for the journals\nThe controller is the signer","constraints":"No new reporting tool\nThe map cannot drop a line used in the last year\nDifferences have one account\nSign-off is the controller, not the project\nThe guide stays short","risks_mitigations":"A report line missed in the map – Check every report line used in the last year against the map\nA mapped line changing meaning – Reopen rule limited to the affected report\nThe difference account used for something else – Account 14918 reserved for differences only\nCustomer-level data in the evidence pack – Remove customer-level rows from the pack\nController signature on the wrong version – Controller signs the version number on the pack","roles_and_responsibilities":"Delivery lead – Owns delivery and the plan – Olivia Banda\nBusiness owner – Accepts the scope and the result – Olivia Banda\nExecutive sponsor – Funds the work and decides escalations – Grace Moyo\nTechnical lead – Owns the technical design – Priya Naidoo\nFinance analyst – Maps ledger accounts and report lines – Daniel Okafor\nMapping analyst – Maintains the report-line map – Amina Diallo","glossary":"Target core\tThe new core banking platform that replaces both legacy cores\nMock\tA full rehearsal load of migrated data into the target core\nHypercare\tThe four weeks of extra support after go-live\nInterface contract\tThe agreed format, timing and owner of one interface\nReplay\tRe-sending a failed message after it has been repaired","appendices":"Regulatory reporting delivery overview\tDelivery Overview – Regulatory reporting\nRegulatory reporting roadmap\tNRB-RM-10\nProgramme architecture principles\tNRB-EA-PR-01","version_history":"0.1\t2026-02-23\tOlivia Banda\tFirst draft\n0.5\t2026-05-03\tPriya Naidoo\tComments from Finance and regulatory forum\n1.0\t2026-09-28\tOlivia Banda\tFinal; workstream closed","related_documents":"NRB-RM-10 – Regulatory reporting roadmap\nDelivery Overview – Regulatory reporting\nNRB-ADR – Architecture decision log","integration_architect":"Priya Naidoo","middleware_integration_platform":"Integration platform with API gateway and event broker","systems_integrated":"Target core\nFinance ledger\nMapping workbook\nReporting tool\nDifference account 14918\nEvidence store\nMigration staging","integration_patterns":["batch","file_transfer"],"interfaces":"Trial balance – Target core – Finance ledger – File transfer – Daily\nReport-line lookup – Mapping workbook – Reporting tool – Batch – Each report run\nDifference postings – Finance ledger – Difference account 14918 – Batch – Each report run\nEvidence filing – Reporting tool – Evidence store – Batch – Each report run\nMock cross-check – Migration staging – Reporting tool – Batch – Each mock","message_formats":["csv","xml"],"api_standards":"Versioned REST resources\nOne error format across all APIs\nCorrelation identifier on every message\nContract approved before build","error_handling":"Failed messages go to a repair queue with the original payload; operations repair and replay them, and every replay is idempotent so it cannot create a duplicate.","throughput_targets":"1,240 report lines mapped\n14 report families","availability_target":99,"monitoring_approach":"Every interface reports success, failure and latency to one dashboard; a failure raises an alert to the interface owner within five minutes.","authentication_methods":["certificates"],"security_controls":"Mutual TLS on service-to-service calls\nCertificates inventoried with expiry alerts\nNo shared service accounts\nPayloads with personal data encrypted in transit"}$j$),
  ('00000000-0000-4000-a020-000000000001', '00000000-0000-4000-9003-00000000000a', 'Customer and digital channels security architecture', 'Security Architecture for customer and digital channels on the Northbridge Bank technology programme. Owner: Amina Diallo.', 'draft', $j${"document_reference":"NRB-SEC-01","document_version":"0.9","document_owner":"Amina Diallo","next_review_date":"2026-11-16","purpose":"Describes the security architecture for customer and digital channels on the Northbridge Bank technology programme. Delivery of customer master data and the internet, mobile and branch channels for the Northbridge Bank technology programme.","objectives":"Every active customer has one surviving customer number\nAddress completeness at or above 85%\nInternet and mobile users can sign in on day one\nDuplicate customers reduced below 1%\nMandate images linked to the surviving customer\nBranch search returns the customer in under 3 seconds","scope":"Retail and SME customer master\nCorporate customer master from the second legacy instance\nInternet banking registration\nMobile banking registration\nBranch teller customer search\nContact centre customer view","out_of_scope":"Card plastic personalisation\nMarketing campaign tool\nLoyalty scheme\nInsurance product origination\nWealth advisory portal","assumptions":"Both legacy instances are profiled before Mock 2\nThe surviving record is the one with the most complete KYC data\nCustomers accept a new customer number where numbers clash\nBranch staff are trained before the dress rehearsal\nStatement templates are approved by the business","constraints":"Customer numbers must be unique across both legacy instances\nKYC fields are mandatory before a customer can be loaded\nAddress completeness target is 85%\nImages must be linked before the channel is opened\nThe load window is the weekend of 10–12 April 2027","risks_mitigations":"Account takeover through weak registration checks – Two-factor registration and device binding\nDuplicate customer merged onto the wrong survivor – Survivor rule signed by the business data owner and sample-checked\nMandate images exposed through a direct link – Images served only through the authenticated retrieval API\nCredential stuffing on internet banking sign-in – Rate limits and lock-out on sign-in\nPersonal data copied into test environments – Masked data only in lower environments","roles_and_responsibilities":"Delivery lead – Owns delivery and the plan – Amina Diallo\nBusiness owner – Accepts the scope and the result – Nomvula Khumalo\nExecutive sponsor – Funds the work and decides escalations – Grace Moyo\nTechnical lead – Owns the technical design – Ravi Pillai\nData analyst – Profiles and maps the data – Priya Naidoo\nChannel analyst – Designs channel journeys and entitlements – Brian Otieno","glossary":"Target core\tThe new core banking platform that replaces both legacy cores\nMock\tA full rehearsal load of migrated data into the target core\nHypercare\tThe four weeks of extra support after go-live\nRecertification\tA line manager confirming each person still needs their access\nPrivileged access\tAccess that can change system configuration or bypass controls","appendices":"Customer and digital channels delivery overview\tDelivery Overview – Customer and digital channels\nCustomer and digital channels roadmap\tNRB-RM-01\nProgramme architecture principles\tNRB-EA-PR-01","version_history":"0.1\t2026-04-27\tAmina Diallo\tFirst draft\n0.5\t2026-07-05\tRavi Pillai\tComments from Channels steering group\n0.9\t2026-09-03\tAmina Diallo\tReady for review","related_documents":"NRB-RM-01 – Customer and digital channels roadmap\nDelivery Overview – Customer and digital channels\nNRB-ADR – Architecture decision log","security_architect":"Nadia Rahman","overall_security_risk":"high","security_requirements":"Every user has a recertified entitlement\nLeavers are absent from the load\nPrivileged access is listed and approved\nSecurity events reach central monitoring","regulatory_frameworks":"Banking regulator outsourcing and cyber guidance\nData protection law for personal data\nPayment scheme security rules","data_classification":"Customer personal data: Restricted\nAccount and balance data: Confidential\nReference data: Internal","threat_model_summary":"The main threats to customer and digital channels are account takeover through weak registration checks and duplicate customer merged onto the wrong survivor. Controls below are designed against each one.","key_threats":"Account takeover through weak registration checks\nDuplicate customer merged onto the wrong survivor\nMandate images exposed through a direct link\nCredential stuffing on internet banking sign-in\nPersonal data copied into test environments","identity_and_access_controls":"Roles from the recertified catalogue only\nTwo-factor sign-in for privileged users\nSame-day leaver revocation","network_controls":"Segmented production network\nOnly the API gateway exposed to channels\nDeny by default between zones","data_protection_controls":"Encryption at rest\nMasked data in lower environments\nKey rotation every 12 months","application_controls":"Input validation on every API\nDual control on repair and override actions\nSession timeout after 15 minutes","logging_and_monitoring":"Security events to central monitoring\nPrivileged sessions recorded\nAlerts on failed sign-in bursts","security_testing":["static_analysis","vulnerability_scan","penetration_test","configuration_review"],"compliance_checks":"Access recertification evidence\nPenetration test findings closed or accepted\nLogging control checked before go-live","residual_risks":"Credential stuffing on internet banking sign-in (accepted with monitoring)\nPersonal data copied into test environments (accepted with monitoring)"}$j$),
  ('00000000-0000-4000-a020-000000000002', '00000000-0000-4000-9003-00000000000a', 'Payments and transfers security architecture', 'Security Architecture for payments and transfers on the Northbridge Bank technology programme. Owner: Ahmed Hassan.', 'draft', $j${"document_reference":"NRB-SEC-02","document_version":"0.9","document_owner":"Ahmed Hassan","next_review_date":"2026-11-18","purpose":"Describes the security architecture for payments and transfers on the Northbridge Bank technology programme. Delivery of domestic payments, standing orders and internal transfers onto the target platform.","objectives":"Every active standing order is recreated before go-live\nSettlement totals agree to the cent\nReturned payments land on the repair queue\nChannel limits match the signed matrix\nNo duplicate payment on the cutover weekend\nCut-off calendar loaded for the next 18 months","scope":"Domestic credit transfers\nInternal account transfers\nStanding orders\nFuture-dated payments\nPayment limits by channel\nSettlement timetable","out_of_scope":"Card authorisation\nATM cash\nCheque clearing replacement\nCross-border correspondent banking rebuild\nCash-in-transit","assumptions":"The scheme timetable does not change before go-live\nStanding orders are recreated, not replayed from history\nBoth legacy instances use the same value-date rule\nPayment limits are signed by the business before UAT\nThe repair queue is staffed for hypercare","constraints":"Scheme cut-off cannot move\nSettlement must balance on the night\nStanding orders with an end date in the past are excluded\nDual control stays on the repair queue\nPayment files are not accepted during the freeze","risks_mitigations":"Duplicate payment on the cutover weekend – Idempotent posting keyed on the payment reference\nChannel limits looser than the signed matrix – Load limits from the signed matrix and test every band\nScheme certificate expiry – Certificate inventory with 60-day expiry alerts\nTampered payment file in transit – Signed and encrypted payment files\nRepair actions without dual control – Dual control enforced on every repair action","roles_and_responsibilities":"Delivery lead – Owns delivery and the plan – Ahmed Hassan\nBusiness owner – Accepts the scope and the result – Catherine Mwangi\nExecutive sponsor – Funds the work and decides escalations – Daniel Okafor\nTechnical lead – Owns the technical design – Brian Otieno\nSettlement analyst – Designs settlement and reconciliation – Olivia Banda\nTest lead – Owns test entry, exit and evidence – Priya Naidoo","glossary":"Target core\tThe new core banking platform that replaces both legacy cores\nMock\tA full rehearsal load of migrated data into the target core\nHypercare\tThe four weeks of extra support after go-live\nRecertification\tA line manager confirming each person still needs their access\nPrivileged access\tAccess that can change system configuration or bypass controls","appendices":"Payments and transfers delivery overview\tDelivery Overview – Payments and transfers\nPayments and transfers roadmap\tNRB-RM-02\nProgramme architecture principles\tNRB-EA-PR-01","version_history":"0.1\t2026-05-25\tAhmed Hassan\tFirst draft\n0.5\t2026-08-02\tBrian Otieno\tComments from Payments working group\n0.9\t2026-10-04\tAhmed Hassan\tReady for review","related_documents":"NRB-RM-02 – Payments and transfers roadmap\nDelivery Overview – Payments and transfers\nNRB-ADR – Architecture decision log","security_architect":"Nadia Rahman","overall_security_risk":"high","security_requirements":"Every user has a recertified entitlement\nLeavers are absent from the load\nPrivileged access is listed and approved\nSecurity events reach central monitoring","regulatory_frameworks":"Banking regulator outsourcing and cyber guidance\nData protection law for personal data\nPayment scheme security rules","data_classification":"Customer personal data: Restricted\nAccount and balance data: Confidential\nReference data: Internal","threat_model_summary":"The main threats to payments and transfers are duplicate payment on the cutover weekend and channel limits looser than the signed matrix. Controls below are designed against each one.","key_threats":"Duplicate payment on the cutover weekend\nChannel limits looser than the signed matrix\nScheme certificate expiry\nTampered payment file in transit\nRepair actions without dual control","identity_and_access_controls":"Roles from the recertified catalogue only\nTwo-factor sign-in for privileged users\nSame-day leaver revocation","network_controls":"Segmented production network\nOnly the API gateway exposed to channels\nDeny by default between zones","data_protection_controls":"Encryption at rest\nMasked data in lower environments\nKey rotation every 12 months","application_controls":"Input validation on every API\nDual control on repair and override actions\nSession timeout after 15 minutes","logging_and_monitoring":"Security events to central monitoring\nPrivileged sessions recorded\nAlerts on failed sign-in bursts","security_testing":["static_analysis","vulnerability_scan","penetration_test","configuration_review"],"compliance_checks":"Access recertification evidence\nPenetration test findings closed or accepted\nLogging control checked before go-live","residual_risks":"Tampered payment file in transit (accepted with monitoring)\nRepair actions without dual control (accepted with monitoring)"}$j$),
  ('00000000-0000-4000-a020-000000000003', '00000000-0000-4000-9003-00000000000a', 'Lending, limits and collateral security architecture', 'Security Architecture for lending, limits and collateral on the Northbridge Bank technology programme. Owner: Joy Akinyi.', 'draft', $j${"document_reference":"NRB-SEC-03","document_version":"0.9","document_owner":"Joy Akinyi","next_review_date":"2026-11-11","purpose":"Describes the security architecture for lending, limits and collateral on the Northbridge Bank technology programme. Delivery of loans, limits and collateral, including overdue bills and the expired-limit rule.","objectives":"Every live loan has an arrangement, a balance and a schedule\nAgeing continues from the legacy past-due date\nExpired limits follow the signed rule\nCollateral is linked before the loan is loaded\nOne repayment account per customer per currency\nTake-over accounts return to zero","scope":"Retail loan arrangements\nCorporate loan arrangements\nOverdue and due bills\nAccrued interest on loans\nLimit records\nExpired limits still linked to a contract","out_of_scope":"New scorecard build\nDebt collection agency files\nSecuritisation\nSyndicated loan agency\nTrade finance instruments","assumptions":"Schedules are regenerated from the migrated frequency\nThe expired-limit rule is expiry plus one day, with the original date kept\nOne liquidation account is allowed per customer per currency\nCollateral rights load before collateral items\nPast-due date becomes the bill date","constraints":"A loan cannot load before its customer and account\nCollateral cannot load before its right\nAgeing must not reset to zero\nExpired limits cannot be dropped while a contract is live\nTake-over accounts must be zero after reconciliation","risks_mitigations":"Expired limit left securing a live contract – Expired-limit rule signed and every case on a credit review queue\nCollateral loaded before its right and rejected – Load rights before items, rehearsed in Mock 2\nAccrual counted twice after migration – Accrual value date set to the migration date\nUnauthorised limit override – Limit overrides need a second approver\nCredit data exposed to non-credit staff – Credit screens limited to credit roles","roles_and_responsibilities":"Delivery lead – Owns delivery and the plan – Joy Akinyi\nBusiness owner – Accepts the scope and the result – Daniel Okafor\nExecutive sponsor – Funds the work and decides escalations – Grace Moyo\nTechnical lead – Owns the technical design – Priya Naidoo\nCredit analyst – Defines lending and limit rules – Ahmed Hassan\nCollateral analyst – Maps collateral rights and items – Linda Zhou","glossary":"Target core\tThe new core banking platform that replaces both legacy cores\nMock\tA full rehearsal load of migrated data into the target core\nHypercare\tThe four weeks of extra support after go-live\nRecertification\tA line manager confirming each person still needs their access\nPrivileged access\tAccess that can change system configuration or bypass controls","appendices":"Lending, limits and collateral delivery overview\tDelivery Overview – Lending, limits and collateral\nLending, limits and collateral roadmap\tNRB-RM-03\nProgramme architecture principles\tNRB-EA-PR-01","version_history":"0.1\t2026-06-08\tJoy Akinyi\tFirst draft\n0.5\t2026-08-16\tPriya Naidoo\tComments from Credit design authority\n0.9\t2026-10-21\tJoy Akinyi\tReady for review","related_documents":"NRB-RM-03 – Lending, limits and collateral roadmap\nDelivery Overview – Lending, limits and collateral\nNRB-ADR – Architecture decision log","security_architect":"Nadia Rahman","overall_security_risk":"medium","security_requirements":"Every user has a recertified entitlement\nLeavers are absent from the load\nPrivileged access is listed and approved\nSecurity events reach central monitoring","regulatory_frameworks":"Banking regulator outsourcing and cyber guidance\nData protection law for personal data\nPayment scheme security rules","data_classification":"Customer personal data: Restricted\nAccount and balance data: Confidential\nReference data: Internal","threat_model_summary":"The main threats to lending, limits and collateral are expired limit left securing a live contract and collateral loaded before its right and rejected. Controls below are designed against each one.","key_threats":"Expired limit left securing a live contract\nCollateral loaded before its right and rejected\nAccrual counted twice after migration\nUnauthorised limit override\nCredit data exposed to non-credit staff","identity_and_access_controls":"Roles from the recertified catalogue only\nTwo-factor sign-in for privileged users\nSame-day leaver revocation","network_controls":"Segmented production network\nOnly the API gateway exposed to channels\nDeny by default between zones","data_protection_controls":"Encryption at rest\nMasked data in lower environments\nKey rotation every 12 months","application_controls":"Input validation on every API\nDual control on repair and override actions\nSession timeout after 15 minutes","logging_and_monitoring":"Security events to central monitoring\nPrivileged sessions recorded\nAlerts on failed sign-in bursts","security_testing":["static_analysis","vulnerability_scan","penetration_test","configuration_review"],"compliance_checks":"Access recertification evidence\nPenetration test findings closed or accepted\nLogging control checked before go-live","residual_risks":"Unauthorised limit override (accepted with monitoring)\nCredit data exposed to non-credit staff (accepted with monitoring)"}$j$),
  ('00000000-0000-4000-a020-000000000004', '00000000-0000-4000-9003-00000000000a', 'Deposits and accounts security architecture', 'Security Architecture for deposits and accounts on the Northbridge Bank technology programme. Owner: Catherine Mwangi.', 'draft', $j${"document_reference":"NRB-SEC-04","document_version":"0.9","document_owner":"Catherine Mwangi","next_review_date":"2026-11-17","purpose":"Describes the security architecture for deposits and accounts on the Northbridge Bank technology programme. Delivery of current accounts, savings and term deposits, including balances and accruals.","objectives":"Every open account has a product, a balance and an owner\nInstance 2 account numbers are kept as alternate keys\nDormant accounts over five years are closed or transferred\nMatured deposits no longer carry a balance at the freeze\nRestrictions match the legacy narrative\nStatement frequency is remapped","scope":"Current accounts\nSavings accounts\nTerm deposits\nDeposit balances and accruals\nDormant accounts over five years\nMatured deposits that still hold a balance","out_of_scope":"Safe custody\nNew savings product launch\nPrize-linked savings\nChildren account campaign\nBrokerage cash accounts","assumptions":"Three legacy current-account products become one target product\nInstance 2 numbers become 10 digits with a check digit\nDormant means no customer-initiated transaction for five years\nUnclaimed balances move under the existing regulation\nMatured deposits are paid out or rolled, not migrated as running","constraints":"No account closures in the week before go-live\nA zero-balance account marked for closure is excluded\nAlternate keys are mandatory for instance 2\nAccrual value date cannot be the original accrual date\nProduct mapping cannot change after Mock 2 without a new approval","risks_mitigations":"Matured deposit still carrying a balance at the freeze – Pay out or roll matured deposits before the freeze\nAccount numbers clashing across the two instances – 10-digit numbers with check digit and alternate keys\nRestriction narrative dropped in migration – Sample-check restriction narratives after each mock\nStatement sent to the wrong address – Address taken from the survivor customer record\nInterest accrued twice – Accrual reconciled by product after Mock 3","roles_and_responsibilities":"Delivery lead – Owns delivery and the plan – Catherine Mwangi\nBusiness owner – Accepts the scope and the result – Nomvula Khumalo\nExecutive sponsor – Funds the work and decides escalations – Olivia Banda\nTechnical lead – Owns the technical design – Brian Otieno\nProduct analyst – Maps products to the target core – Amina Diallo\nFinance partner – Agrees accounting and control totals – Daniel Okafor","glossary":"Target core\tThe new core banking platform that replaces both legacy cores\nMock\tA full rehearsal load of migrated data into the target core\nHypercare\tThe four weeks of extra support after go-live\nRecertification\tA line manager confirming each person still needs their access\nPrivileged access\tAccess that can change system configuration or bypass controls","appendices":"Deposits and accounts delivery overview\tDelivery Overview – Deposits and accounts\nDeposits and accounts roadmap\tNRB-RM-04\nProgramme architecture principles\tNRB-EA-PR-01","version_history":"0.1\t2026-05-11\tCatherine Mwangi\tFirst draft\n0.5\t2026-07-19\tBrian Otieno\tComments from Deposits product forum\n0.9\t2026-09-26\tCatherine Mwangi\tReady for review","related_documents":"NRB-RM-04 – Deposits and accounts roadmap\nDelivery Overview – Deposits and accounts\nNRB-ADR – Architecture decision log","security_architect":"Nadia Rahman","overall_security_risk":"medium","security_requirements":"Every user has a recertified entitlement\nLeavers are absent from the load\nPrivileged access is listed and approved\nSecurity events reach central monitoring","regulatory_frameworks":"Banking regulator outsourcing and cyber guidance\nData protection law for personal data\nPayment scheme security rules","data_classification":"Customer personal data: Restricted\nAccount and balance data: Confidential\nReference data: Internal","threat_model_summary":"The main threats to deposits and accounts are matured deposit still carrying a balance at the freeze and account numbers clashing across the two instances. Controls below are designed against each one.","key_threats":"Matured deposit still carrying a balance at the freeze\nAccount numbers clashing across the two instances\nRestriction narrative dropped in migration\nStatement sent to the wrong address\nInterest accrued twice","identity_and_access_controls":"Roles from the recertified catalogue only\nTwo-factor sign-in for privileged users\nSame-day leaver revocation","network_controls":"Segmented production network\nOnly the API gateway exposed to channels\nDeny by default between zones","data_protection_controls":"Encryption at rest\nMasked data in lower environments\nKey rotation every 12 months","application_controls":"Input validation on every API\nDual control on repair and override actions\nSession timeout after 15 minutes","logging_and_monitoring":"Security events to central monitoring\nPrivileged sessions recorded\nAlerts on failed sign-in bursts","security_testing":["static_analysis","vulnerability_scan","penetration_test","configuration_review"],"compliance_checks":"Access recertification evidence\nPenetration test findings closed or accepted\nLogging control checked before go-live","residual_risks":"Statement sent to the wrong address (accepted with monitoring)\nInterest accrued twice (accepted with monitoring)"}$j$),
  ('00000000-0000-4000-a020-000000000005', '00000000-0000-4000-9003-00000000000a', 'Data migration and quality security architecture', 'Security Architecture for data migration and quality on the Northbridge Bank technology programme. Owner: Priya Naidoo.', 'draft', $j${"document_reference":"NRB-SEC-05","document_version":"0.9","document_owner":"Priya Naidoo","next_review_date":"2026-11-13","purpose":"Describes the security architecture for data migration and quality on the Northbridge Bank technology programme. Cross-cutting delivery of extraction, cleansing, transformation, mock runs and reconciliation for the programme.","objectives":"Mock 2 static data loads inside the window\nMock 3 financial data reconciles\nDress rehearsal finishes with no severity-1 defect open\nTake-over and suspense accounts are zero\nEach population has a named data owner\nControl totals tie to the trial balance","scope":"Source profiling\nExtraction from both legacy instances\nCleansing at source\nTransformation rules\nMock runs\nDress rehearsal","out_of_scope":"Building the target platform\nCard scheme certification\nGeneral ledger replacement\nStaff identity directory rebuild\nA new data warehouse","assumptions":"Three mock runs and one dress rehearsal are enough\nCleansing is done in the source, not in the load\nThe file layout is plain text, one record per line\nDates travel as YYYYMMDD\nControl totals come from the final close of business","constraints":"The April 2027 weekend is fixed\nPersonal data stays in the residency region\nA population cannot load before its predecessor\nSeverity-1 defects block the next mock\nTake-over accounts must finish at zero","risks_mitigations":"Production data copied into a shared workbook – Remove samples from shared workbooks; extracts stay in the staging store\nExtract taken before close of business – Extract after close of business, checked on the mock entry list\nTake-over accounts not at zero – Reconcile take-over accounts to zero before sign-off\nUnmasked data in a lower environment – Masking applied before any refresh\nLoad window overrun – Three mocks with the window measured each time","roles_and_responsibilities":"Delivery lead – Owns delivery and the plan – Priya Naidoo\nBusiness data owner – Signs off the data population – Amina Diallo\nExecutive sponsor – Funds the work and decides escalations – Olivia Banda\nTechnical lead – Owns the technical design – Brian Otieno\nReconciliation lead – Proves control totals after each load – Olivia Banda\nFinance partner – Agrees accounting and control totals – Daniel Okafor","glossary":"Target core\tThe new core banking platform that replaces both legacy cores\nMock\tA full rehearsal load of migrated data into the target core\nHypercare\tThe four weeks of extra support after go-live\nRecertification\tA line manager confirming each person still needs their access\nPrivileged access\tAccess that can change system configuration or bypass controls","appendices":"Data migration and quality delivery overview\tDelivery Overview – Data migration and quality\nData migration and quality roadmap\tNRB-RM-05\nProgramme architecture principles\tNRB-EA-PR-01","version_history":"0.1\t2026-03-23\tPriya Naidoo\tFirst draft\n0.5\t2026-05-31\tBrian Otieno\tComments from Data migration design authority\n0.9\t2026-08-11\tPriya Naidoo\tReady for review","related_documents":"NRB-RM-05 – Data migration and quality roadmap\nDelivery Overview – Data migration and quality\nNRB-ADR – Architecture decision log","security_architect":"Nadia Rahman","overall_security_risk":"high","security_requirements":"Every user has a recertified entitlement\nLeavers are absent from the load\nPrivileged access is listed and approved\nSecurity events reach central monitoring","regulatory_frameworks":"Banking regulator outsourcing and cyber guidance\nData protection law for personal data\nPayment scheme security rules","data_classification":"Customer personal data: Restricted\nAccount and balance data: Confidential\nReference data: Internal","threat_model_summary":"The main threats to data migration and quality are production data copied into a shared workbook and extract taken before close of business. Controls below are designed against each one.","key_threats":"Production data copied into a shared workbook\nExtract taken before close of business\nTake-over accounts not at zero\nUnmasked data in a lower environment\nLoad window overrun","identity_and_access_controls":"Roles from the recertified catalogue only\nTwo-factor sign-in for privileged users\nSame-day leaver revocation","network_controls":"Segmented production network\nOnly the API gateway exposed to channels\nDeny by default between zones","data_protection_controls":"Encryption at rest\nMasked data in lower environments\nKey rotation every 12 months","application_controls":"Input validation on every API\nDual control on repair and override actions\nSession timeout after 15 minutes","logging_and_monitoring":"Security events to central monitoring\nPrivileged sessions recorded\nAlerts on failed sign-in bursts","security_testing":["static_analysis","vulnerability_scan","penetration_test","configuration_review"],"compliance_checks":"Access recertification evidence\nPenetration test findings closed or accepted\nLogging control checked before go-live","residual_risks":"Unmasked data in a lower environment (accepted with monitoring)\nLoad window overrun (accepted with monitoring)"}$j$),
  ('00000000-0000-4000-a020-000000000006', '00000000-0000-4000-9003-00000000000a', 'Integration and interfaces security architecture', 'Security Architecture for integration and interfaces on the Northbridge Bank technology programme. Owner: Brian Otieno.', 'draft', $j${"document_reference":"NRB-SEC-06","document_version":"0.9","document_owner":"Brian Otieno","next_review_date":"2026-11-19","purpose":"Describes the security architecture for integration and interfaces on the Northbridge Bank technology programme. Delivery of the interfaces the target platform needs from channels, cards, finance, documents and the user store.","objectives":"Each in-scope interface has a contract, a test and an owner\nFailed messages are visible on one dashboard\nCard status cross-check agrees active cards\nTrial-balance file balances before it is used\nImage retrieval works for a mandate\nChannels no longer call the legacy cores after go-live","scope":"Internet banking interface\nMobile banking interface\nBranch teller interface\nContact centre interface\nCard status cross-check\nDocument image retrieval","out_of_scope":"A new integration platform product selection\nOpen-banking directory build\nCard scheme certification\nATM switch replacement\nPoint of sale acquiring","assumptions":"Existing channels are reused and pointed at the target\nThe card system is not migrated; only status is cross-checked\nThe finance system stays and sends a file\nCertificates can be renewed without a scheme change\nOne dashboard covers every in-scope interface","constraints":"SIT entry dates are fixed on the integration plan\nA missing certificate blocks that interface\nCard numbers are not stored on the dashboard\nThe trial-balance file is after close of business\nReplay cannot create a second payment","risks_mitigations":"Silent message loss – Every interface reports to one dashboard with alerts\nCertificate expiring in hypercare – Certificates valid through hypercare, renewed before the freeze\nReplay creating a duplicate payment – Idempotent replay keyed on the message identifier\nA channel still calling the legacy core – Remove legacy addresses and test from each channel\nUnauthenticated internal API – Mutual TLS on every internal API","roles_and_responsibilities":"Delivery lead – Owns delivery and the plan – Brian Otieno\nBusiness owner – Accepts the scope and the result – Ravi Pillai\nExecutive sponsor – Funds the work and decides escalations – Daniel Okafor\nTechnical lead – Owns the technical design – Ravi Pillai\nInterface analyst – Writes and tests interface contracts – Priya Naidoo\nTest lead – Owns test entry, exit and evidence – Catherine Mwangi","glossary":"Target core\tThe new core banking platform that replaces both legacy cores\nMock\tA full rehearsal load of migrated data into the target core\nHypercare\tThe four weeks of extra support after go-live\nRecertification\tA line manager confirming each person still needs their access\nPrivileged access\tAccess that can change system configuration or bypass controls","appendices":"Integration and interfaces delivery overview\tDelivery Overview – Integration and interfaces\nIntegration and interfaces roadmap\tNRB-RM-06\nProgramme architecture principles\tNRB-EA-PR-01","version_history":"0.1\t2026-06-22\tBrian Otieno\tFirst draft\n0.5\t2026-08-30\tRavi Pillai\tComments from Integration design authority\n0.9\t2026-11-13\tBrian Otieno\tReady for review","related_documents":"NRB-RM-06 – Integration and interfaces roadmap\nDelivery Overview – Integration and interfaces\nNRB-ADR – Architecture decision log","security_architect":"Nadia Rahman","overall_security_risk":"high","security_requirements":"Every user has a recertified entitlement\nLeavers are absent from the load\nPrivileged access is listed and approved\nSecurity events reach central monitoring","regulatory_frameworks":"Banking regulator outsourcing and cyber guidance\nData protection law for personal data\nPayment scheme security rules","data_classification":"Customer personal data: Restricted\nAccount and balance data: Confidential\nReference data: Internal","threat_model_summary":"The main threats to integration and interfaces are silent message loss and certificate expiring in hypercare. Controls below are designed against each one.","key_threats":"Silent message loss\nCertificate expiring in hypercare\nReplay creating a duplicate payment\nA channel still calling the legacy core\nUnauthenticated internal API","identity_and_access_controls":"Roles from the recertified catalogue only\nTwo-factor sign-in for privileged users\nSame-day leaver revocation","network_controls":"Segmented production network\nOnly the API gateway exposed to channels\nDeny by default between zones","data_protection_controls":"Encryption at rest\nMasked data in lower environments\nKey rotation every 12 months","application_controls":"Input validation on every API\nDual control on repair and override actions\nSession timeout after 15 minutes","logging_and_monitoring":"Security events to central monitoring\nPrivileged sessions recorded\nAlerts on failed sign-in bursts","security_testing":["static_analysis","vulnerability_scan","penetration_test","configuration_review"],"compliance_checks":"Access recertification evidence\nPenetration test findings closed or accepted\nLogging control checked before go-live","residual_risks":"A channel still calling the legacy core (accepted with monitoring)\nUnauthenticated internal API (accepted with monitoring)"}$j$),
  ('00000000-0000-4000-a020-000000000007', '00000000-0000-4000-9003-00000000000a', 'Cybersecurity and access security architecture', 'Security Architecture for cybersecurity and access on the Northbridge Bank technology programme. Owner: Nadia Rahman.', 'draft', $j${"document_reference":"NRB-SEC-07","document_version":"0.9","document_owner":"Nadia Rahman","next_review_date":"2026-11-24","purpose":"Describes the security architecture for cybersecurity and access on the Northbridge Bank technology programme. Delivery of user access, recertification and the security controls required before go-live. Currently on hold.","objectives":"Every loaded user has a recertified entitlement\nLeavers are absent from the load\nPrivileged access is listed and approved\nStaff can sign in on day one\nLogging meets the agreed control\nAudit can see who approved each role","scope":"Bank user profiles\nUser groups and roles\nLine-manager recertification\nPrivileged access\nJoiner, mover and leaver handling\nAuthentication for staff","out_of_scope":"Customer authentication redesign\nA new identity product selection\nBuilding access\nCard PIN platform\nEndpoint replacement","assumptions":"Line managers recertify their own staff\nThe identity directory is a source, not a system being replaced\nPrivileged access is a separate list\nLeavers are removed in the source before extract\nCustomer sign-in is owned by the channels delivery","constraints":"User load cannot start before recertification\nThe freeze date does not move for this workstream alone\nPrivileged access requires two approvers\nPersonal data in access logs follows the retention schedule\nA leaver cannot be loaded","risks_mitigations":"Leaver loaded into the target platform – Leaver extract applied before every user load\nShared identity created to save time – Named identities only; shared accounts refused\nPrivileged access copied unchanged – Privileged roles rebuilt and approved, not copied\nLogging weaker than the agreed control – Logging checked against the control before go-live\nSame-day revocation not possible in hypercare – Same-day revocation process tested with the service desk","roles_and_responsibilities":"Delivery lead – Owns delivery and the plan – Nadia Rahman\nBusiness owner – Accepts the scope and the result – Daniel Okafor\nExecutive sponsor – Funds the work and decides escalations – Grace Moyo\nTechnical lead – Owns the technical design – Nadia Rahman\nAccess analyst – Builds the role catalogue and access reviews – Ravi Pillai\nAudit partner – Checks evidence for audit – Olivia Banda","glossary":"Target core\tThe new core banking platform that replaces both legacy cores\nMock\tA full rehearsal load of migrated data into the target core\nHypercare\tThe four weeks of extra support after go-live\nRecertification\tA line manager confirming each person still needs their access\nPrivileged access\tAccess that can change system configuration or bypass controls","appendices":"Cybersecurity and access delivery overview\tDelivery Overview – Cybersecurity and access\nCybersecurity and access roadmap\tNRB-RM-07\nProgramme architecture principles\tNRB-EA-PR-01","version_history":"0.1\t2026-07-06\tNadia Rahman\tFirst draft\n0.5\t2026-09-13\tNadia Rahman\tComments from Security design authority\n0.9\t2026-11-30\tNadia Rahman\tReady for review","related_documents":"NRB-RM-07 – Cybersecurity and access roadmap\nDelivery Overview – Cybersecurity and access\nNRB-ADR – Architecture decision log","security_architect":"Nadia Rahman","overall_security_risk":"critical","security_requirements":"Every user has a recertified entitlement\nLeavers are absent from the load\nPrivileged access is listed and approved\nSecurity events reach central monitoring","regulatory_frameworks":"Banking regulator outsourcing and cyber guidance\nData protection law for personal data\nPayment scheme security rules","data_classification":"Customer personal data: Restricted\nAccount and balance data: Confidential\nReference data: Internal","threat_model_summary":"The main threats to cybersecurity and access are leaver loaded into the target platform and shared identity created to save time. Controls below are designed against each one.","key_threats":"Leaver loaded into the target platform\nShared identity created to save time\nPrivileged access copied unchanged\nLogging weaker than the agreed control\nSame-day revocation not possible in hypercare","identity_and_access_controls":"Roles from the recertified catalogue only\nTwo-factor sign-in for privileged users\nSame-day leaver revocation","network_controls":"Segmented production network\nOnly the API gateway exposed to channels\nDeny by default between zones","data_protection_controls":"Encryption at rest\nMasked data in lower environments\nKey rotation every 12 months","application_controls":"Input validation on every API\nDual control on repair and override actions\nSession timeout after 15 minutes","logging_and_monitoring":"Security events to central monitoring\nPrivileged sessions recorded\nAlerts on failed sign-in bursts","security_testing":["static_analysis","vulnerability_scan","penetration_test","configuration_review"],"compliance_checks":"Access recertification evidence\nPenetration test findings closed or accepted\nLogging control checked before go-live","residual_risks":"Logging weaker than the agreed control (accepted with monitoring)\nSame-day revocation not possible in hypercare (accepted with monitoring)"}$j$),
  ('00000000-0000-4000-a020-000000000008', '00000000-0000-4000-9003-00000000000a', 'Environments and release security architecture', 'Security Architecture for environments and release on the Northbridge Bank technology programme. Owner: Ravi Pillai.', 'draft', $j${"document_reference":"NRB-SEC-08","document_version":"0.9","document_owner":"Ravi Pillai","next_review_date":"2026-11-18","purpose":"Describes the security architecture for environments and release on the Northbridge Bank technology programme. Delivery of the environment path from development through dress rehearsal, production and recovery, and the release calendar that uses it.","objectives":"Every test stage has a booked environment\nDress rehearsal uses a production-like path\nRefresh is requested and logged\nThe release calendar is the only source of release dates\nRecovery is restored and checked before go-live\nNo two mocks share an environment","scope":"Development environment\nTest environment\nSystem integration environment\nUser acceptance environment\nPre-production\nProduction cutover runbook","out_of_scope":"A new data centre build\nEnd-user device replacement\nNetwork redesign\nCloud provider selection\nProduction support model","assumptions":"Existing hosting is reused\nProduction-like data is masked except in dress rehearsal under approval\nOne calendar is enough\nRecovery is a restore test, not a second data centre project\nTeams will book if the booking is easier than asking in a chat","constraints":"The dress rehearsal date is fixed once booked\nMasked data is the default\nProduction access is named people only\nTwo mocks cannot share an environment\nA refresh during execution is refused","risks_mitigations":"Refresh using unmasked production data – Masking approved and applied before refresh\nTwo mocks booked on one environment – One booking register, mandatory from SIT\nRecovery backup that cannot be restored – Recovery restore rehearsed before go-live\nProduction access wider than the named list – Named production access list reviewed monthly\nConfiguration drift between environments – One configuration baseline promoted through every environment","roles_and_responsibilities":"Delivery lead – Owns delivery and the plan – Ravi Pillai\nBusiness owner – Accepts the scope and the result – Brian Otieno\nExecutive sponsor – Funds the work and decides escalations – Daniel Okafor\nTechnical lead – Owns the technical design – Ravi Pillai\nEnvironment analyst – Books and refreshes environments – Priya Naidoo\nRelease manager – Owns the release calendar – Linda Zhou","glossary":"Target core\tThe new core banking platform that replaces both legacy cores\nMock\tA full rehearsal load of migrated data into the target core\nHypercare\tThe four weeks of extra support after go-live\nRecertification\tA line manager confirming each person still needs their access\nPrivileged access\tAccess that can change system configuration or bypass controls","appendices":"Environments and release delivery overview\tDelivery Overview – Environments and release\nEnvironments and release roadmap\tNRB-RM-08\nProgramme architecture principles\tNRB-EA-PR-01","version_history":"0.1\t2026-04-06\tRavi Pillai\tFirst draft\n0.5\t2026-06-14\tRavi Pillai\tComments from Environment and release forum\n0.9\t2026-09-03\tRavi Pillai\tReady for review","related_documents":"NRB-RM-08 – Environments and release roadmap\nDelivery Overview – Environments and release\nNRB-ADR – Architecture decision log","security_architect":"Nadia Rahman","overall_security_risk":"medium","security_requirements":"Every user has a recertified entitlement\nLeavers are absent from the load\nPrivileged access is listed and approved\nSecurity events reach central monitoring","regulatory_frameworks":"Banking regulator outsourcing and cyber guidance\nData protection law for personal data\nPayment scheme security rules","data_classification":"Customer personal data: Restricted\nAccount and balance data: Confidential\nReference data: Internal","threat_model_summary":"The main threats to environments and release are refresh using unmasked production data and two mocks booked on one environment. Controls below are designed against each one.","key_threats":"Refresh using unmasked production data\nTwo mocks booked on one environment\nRecovery backup that cannot be restored\nProduction access wider than the named list\nConfiguration drift between environments","identity_and_access_controls":"Roles from the recertified catalogue only\nTwo-factor sign-in for privileged users\nSame-day leaver revocation","network_controls":"Segmented production network\nOnly the API gateway exposed to channels\nDeny by default between zones","data_protection_controls":"Encryption at rest\nMasked data in lower environments\nKey rotation every 12 months","application_controls":"Input validation on every API\nDual control on repair and override actions\nSession timeout after 15 minutes","logging_and_monitoring":"Security events to central monitoring\nPrivileged sessions recorded\nAlerts on failed sign-in bursts","security_testing":["static_analysis","vulnerability_scan","penetration_test","configuration_review"],"compliance_checks":"Access recertification evidence\nPenetration test findings closed or accepted\nLogging control checked before go-live","residual_risks":"Production access wider than the named list (accepted with monitoring)\nConfiguration drift between environments (accepted with monitoring)"}$j$),
  ('00000000-0000-4000-a020-000000000009', '00000000-0000-4000-9003-00000000000a', 'Operational readiness and hypercare security architecture', 'Security Architecture for operational readiness and hypercare on the Northbridge Bank technology programme. Owner: Linda Zhou.', 'draft', $j${"document_reference":"NRB-SEC-09","document_version":"0.9","document_owner":"Linda Zhou","next_review_date":"2026-11-20","purpose":"Describes the security architecture for operational readiness and hypercare on the Northbridge Bank technology programme. Delivery of the support model, runbooks, monitoring handover and the hypercare period after go-live.","objectives":"Every cutover step has a runbook someone has walked through\nHypercare shifts are named, including nights\nThe daily bridge has an agenda and a chair\nSeverity scale matches the defect scale\nMonitoring alerts reach the roster\nKnown errors are written down before go-live","scope":"Support model\nRunbooks for the cutover weekend\nHypercare roster\nDaily hypercare bridge\nSeverity scale for hypercare\nMonitoring handover","out_of_scope":"A new service-desk product\nBranch refurbishment\nA 24-hour contact centre build\nVendor contract renegotiation\nProduction data centre build","assumptions":"Hypercare lasts four weeks\nThe existing service desk is the front door\nRunbooks are steps with an expected result\nNight shifts are required for the first week only\nMonitoring is handed over, not rebuilt","constraints":"Hypercare cannot be staffed by unnamed roles\nA runbook that has not been walked through does not count\nThe first week has night cover\nExit criteria are set before go-live\nThe bridge is every business day in hypercare","risks_mitigations":"Alerts going to a mailbox nobody reads – Alerts routed to the named roster, not a mailbox\nNight shifts left unnamed – Name every shift, including nights, before the dress rehearsal\nRunbooks never walked through – Walk through every runbook in the dress rehearsal\nKnown errors found by customers – Publish the known-error list before go-live\nSeverity 1 response slower than 30 minutes – Severity 1 bridge opened within 15 minutes","roles_and_responsibilities":"Delivery lead – Owns delivery and the plan – Linda Zhou\nBusiness owner – Accepts the scope and the result – Catherine Mwangi\nExecutive sponsor – Funds the work and decides escalations – Grace Moyo\nTechnical lead – Owns the technical design – Ahmed Hassan\nService desk lead – Prepares the service desk for go-live – Brian Otieno\nOperations lead – Owns run procedures after go-live – Ravi Pillai","glossary":"Target core\tThe new core banking platform that replaces both legacy cores\nMock\tA full rehearsal load of migrated data into the target core\nHypercare\tThe four weeks of extra support after go-live\nRecertification\tA line manager confirming each person still needs their access\nPrivileged access\tAccess that can change system configuration or bypass controls","appendices":"Operational readiness and hypercare delivery overview\tDelivery Overview – Operational readiness and hypercare\nOperational readiness and hypercare roadmap\tNRB-RM-09\nProgramme architecture principles\tNRB-EA-PR-01","version_history":"0.1\t2026-09-22\tLinda Zhou\tFirst draft\n0.5\t2026-11-30\tAhmed Hassan\tComments from Operational readiness forum\n0.9\t2027-02-22\tLinda Zhou\tReady for review","related_documents":"NRB-RM-09 – Operational readiness and hypercare roadmap\nDelivery Overview – Operational readiness and hypercare\nNRB-ADR – Architecture decision log","security_architect":"Nadia Rahman","overall_security_risk":"medium","security_requirements":"Every user has a recertified entitlement\nLeavers are absent from the load\nPrivileged access is listed and approved\nSecurity events reach central monitoring","regulatory_frameworks":"Banking regulator outsourcing and cyber guidance\nData protection law for personal data\nPayment scheme security rules","data_classification":"Customer personal data: Restricted\nAccount and balance data: Confidential\nReference data: Internal","threat_model_summary":"The main threats to operational readiness and hypercare are alerts going to a mailbox nobody reads and night shifts left unnamed. Controls below are designed against each one.","key_threats":"Alerts going to a mailbox nobody reads\nNight shifts left unnamed\nRunbooks never walked through\nKnown errors found by customers\nSeverity 1 response slower than 30 minutes","identity_and_access_controls":"Roles from the recertified catalogue only\nTwo-factor sign-in for privileged users\nSame-day leaver revocation","network_controls":"Segmented production network\nOnly the API gateway exposed to channels\nDeny by default between zones","data_protection_controls":"Encryption at rest\nMasked data in lower environments\nKey rotation every 12 months","application_controls":"Input validation on every API\nDual control on repair and override actions\nSession timeout after 15 minutes","logging_and_monitoring":"Security events to central monitoring\nPrivileged sessions recorded\nAlerts on failed sign-in bursts","security_testing":["static_analysis","vulnerability_scan","penetration_test","configuration_review"],"compliance_checks":"Access recertification evidence\nPenetration test findings closed or accepted\nLogging control checked before go-live","residual_risks":"Known errors found by customers (accepted with monitoring)\nSeverity 1 response slower than 30 minutes (accepted with monitoring)"}$j$),
  ('00000000-0000-4000-a020-000000000010', '00000000-0000-4000-9003-00000000000a', 'Regulatory reporting security architecture', 'Security Architecture for regulatory reporting. Superseded: the reporting workstream closed on 30 September 2026; kept for reference.', 'superseded', $j${"document_reference":"NRB-SEC-10","document_version":"1.0","document_owner":"Olivia Banda","next_review_date":"2027-03-31","purpose":"Describes the security architecture for regulatory reporting on the Northbridge Bank technology programme. Completed delivery of the report-line mapping that lets finance keep the existing reporting tool across the migration.","objectives":"Every report line used in the last year has a mapped source\nThe mock cross-check agreed\nDifferences go to the agreed difference account\nThe financial controller has signed\nFinance did not change tool\nEvidence is in the go-live pack","scope":"Report-line map from the trial balance\nCurrency and company mapping\nFirst mock cross-check\nEvidence pack for finance\nNamed owner per report family\nDifference account treatment","out_of_scope":"A new reporting tool\nPrudential return redesign\nTax engine replacement\nManagement information warehouse\nBoard pack redesign","assumptions":"The finance system stays\nThe chart of accounts does not change for go-live\nLast year of report lines is the scope\nDifferences use account 14918 as already agreed for the journals\nThe controller is the signer","constraints":"No new reporting tool\nThe map cannot drop a line used in the last year\nDifferences have one account\nSign-off is the controller, not the project\nThe guide stays short","risks_mitigations":"A report line missed in the map – Check every report line used in the last year against the map\nA mapped line changing meaning – Reopen rule limited to the affected report\nThe difference account used for something else – Account 14918 reserved for differences only\nCustomer-level data in the evidence pack – Remove customer-level rows from the pack\nController signature on the wrong version – Controller signs the version number on the pack","roles_and_responsibilities":"Delivery lead – Owns delivery and the plan – Olivia Banda\nBusiness owner – Accepts the scope and the result – Olivia Banda\nExecutive sponsor – Funds the work and decides escalations – Grace Moyo\nTechnical lead – Owns the technical design – Priya Naidoo\nFinance analyst – Maps ledger accounts and report lines – Daniel Okafor\nMapping analyst – Maintains the report-line map – Amina Diallo","glossary":"Target core\tThe new core banking platform that replaces both legacy cores\nMock\tA full rehearsal load of migrated data into the target core\nHypercare\tThe four weeks of extra support after go-live\nRecertification\tA line manager confirming each person still needs their access\nPrivileged access\tAccess that can change system configuration or bypass controls","appendices":"Regulatory reporting delivery overview\tDelivery Overview – Regulatory reporting\nRegulatory reporting roadmap\tNRB-RM-10\nProgramme architecture principles\tNRB-EA-PR-01","version_history":"0.1\t2026-02-23\tOlivia Banda\tFirst draft\n0.5\t2026-05-03\tPriya Naidoo\tComments from Finance and regulatory forum\n1.0\t2026-09-28\tOlivia Banda\tFinal; workstream closed","related_documents":"NRB-RM-10 – Regulatory reporting roadmap\nDelivery Overview – Regulatory reporting\nNRB-ADR – Architecture decision log","security_architect":"Nadia Rahman","overall_security_risk":"low","security_requirements":"Every user has a recertified entitlement\nLeavers are absent from the load\nPrivileged access is listed and approved\nSecurity events reach central monitoring","regulatory_frameworks":"Banking regulator outsourcing and cyber guidance\nData protection law for personal data\nPayment scheme security rules","data_classification":"Customer personal data: Restricted\nAccount and balance data: Confidential\nReference data: Internal","threat_model_summary":"The main threats to regulatory reporting are a report line missed in the map and a mapped line changing meaning. Controls below are designed against each one.","key_threats":"A report line missed in the map\nA mapped line changing meaning\nThe difference account used for something else\nCustomer-level data in the evidence pack\nController signature on the wrong version","identity_and_access_controls":"Roles from the recertified catalogue only\nTwo-factor sign-in for privileged users\nSame-day leaver revocation","network_controls":"Segmented production network\nOnly the API gateway exposed to channels\nDeny by default between zones","data_protection_controls":"Encryption at rest\nMasked data in lower environments\nKey rotation every 12 months","application_controls":"Input validation on every API\nDual control on repair and override actions\nSession timeout after 15 minutes","logging_and_monitoring":"Security events to central monitoring\nPrivileged sessions recorded\nAlerts on failed sign-in bursts","security_testing":["static_analysis","vulnerability_scan","penetration_test","configuration_review"],"compliance_checks":"Access recertification evidence\nPenetration test findings closed or accepted\nLogging control checked before go-live","residual_risks":"Customer-level data in the evidence pack (accepted with monitoring)\nController signature on the wrong version (accepted with monitoring)"}$j$),
  ('00000000-0000-4000-a021-000000000001', '00000000-0000-4000-9003-00000000000b', 'Survivor rule for duplicate customers', 'Decision record NRB-ADR-01. Owner: Amina Diallo.', 'draft', $j${"document_reference":"NRB-ADR-01","document_version":"1.0","document_owner":"Amina Diallo","next_review_date":"2027-03-31","decision_owner":"Amina Diallo","decision_date":"2026-10-19","decision_area":"data","glossary":"Target core\tThe new core banking platform that replaces both legacy cores\nMock\tA full rehearsal load of migrated data into the target core\nHypercare\tThe four weeks of extra support after go-live\nDecision record\tA short note of one architecture decision, its options and why it was chosen","version_history":"0.1\t2026-10-05\tAmina Diallo\tOptions written up\n1.0\t2026-10-19\tAmina Diallo\tDecision recorded","related_documents":"NRB-EA-05 – Data migration and quality enterprise architecture\nDelivery Overview – Northbridge Bank technology programme","decision_context":"23,400 customers exist in both legacy instances and 4,150 have more than one number in a single instance. One customer must survive with one number.","problem_statement":"Which record survives when duplicates are merged, and which values it keeps?","decision_drivers":"Every active customer has one surviving customer number\nMandate images must follow the survivor\nOld numbers must still be found","decision_constraints":"No customer advice may be sent during the load\nKYC data stays with the record that passed KYC last","options_considered":"Most recent KYC wins – Keeps the best-verified identity – Older contact details may be lost\nOldest relationship wins – Keeps the longest history – May keep stale KYC\nField-level survivorship – Best value for each field – Complex to test before Mock 2","decision_outcome":"The record with the most recent passed KYC survives; contact fields are taken field by field from the most recently updated record.","rationale":"KYC quality matters most to the regulator; field-level contact rules fix the address completeness gap without delaying Mock 2.","positive_consequences":"One number per customer\nAddress completeness improves","negative_consequences":"Survivorship rules add test effort","follow_up_actions":"Run the rule on the Mock 2 extract\nBusiness data owner signs off the result","related_decisions":"NRB-ADR-03 – 8-digit customer number standard","risks_mitigations":"Decision not followed in build – Check at the design authority\nDecision overtaken by new facts – Review on 2027-03-31","roles_and_responsibilities":"Decision owner – Records and maintains the decision – Amina Diallo\nDesign authority chair – Approves the decision – Ravi Pillai\nExecutive sponsor – Decides escalations – Grace Moyo"}$j$),
  ('00000000-0000-4000-a021-000000000002', '00000000-0000-4000-9003-00000000000b', 'Store mandate and signature images in a file store', 'Decision record NRB-ADR-02. Owner: Ravi Pillai.', 'draft', $j${"document_reference":"NRB-ADR-02","document_version":"1.0","document_owner":"Ravi Pillai","next_review_date":"2027-03-31","decision_owner":"Ravi Pillai","decision_date":"2026-10-26","decision_area":"infrastructure","glossary":"Target core\tThe new core banking platform that replaces both legacy cores\nMock\tA full rehearsal load of migrated data into the target core\nHypercare\tThe four weeks of extra support after go-live\nDecision record\tA short note of one architecture decision, its options and why it was chosen","version_history":"0.1\t2026-10-12\tRavi Pillai\tOptions written up\n1.0\t2026-10-26\tRavi Pillai\tDecision recorded","related_documents":"NRB-EA-05 – Data migration and quality enterprise architecture\nDelivery Overview – Northbridge Bank technology programme","decision_context":"Mandate and signature images must move with the customer. Image volume threatens the static data window if loaded into the core database.","problem_statement":"Where do mandate and signature images live after migration?","decision_drivers":"Static load must fit inside the window\nBranch staff must see images in under 3 seconds\nImages kept 7 years","decision_constraints":"No customer data outside the agreed region","options_considered":"Object store linked from the core – Keeps the core small; fast to load – Needs an image retrieval API\nCore database – One place for all data – Slows the load and backups\nLeave in the legacy archive – No migration effort – Legacy archive must stay running","decision_outcome":"Images move to the object store; the target core keeps a reference and branch screens call the image retrieval API.","rationale":"Keeps the static window and backup times within limits and lets the legacy archive be switched off.","positive_consequences":"Shorter load window\nSmaller core backups","negative_consequences":"One more API to run and monitor","follow_up_actions":"Build the image retrieval API\nRehearse image load in Mock 2","related_decisions":"NRB-ADR-10 – Store mandate images in the core database","supersedes":"NRB-ADR-10","risks_mitigations":"Decision not followed in build – Check at the design authority\nDecision overtaken by new facts – Review on 2027-03-31","roles_and_responsibilities":"Decision owner – Records and maintains the decision – Ravi Pillai\nDesign authority chair – Approves the decision – Ravi Pillai\nExecutive sponsor – Decides escalations – Grace Moyo"}$j$),
  ('00000000-0000-4000-a021-000000000003', '00000000-0000-4000-9003-00000000000b', '8-digit customer number standard', 'Decision record NRB-ADR-03. Owner: Priya Naidoo.', 'draft', $j${"document_reference":"NRB-ADR-03","document_version":"1.0","document_owner":"Priya Naidoo","next_review_date":"2027-03-31","decision_owner":"Priya Naidoo","decision_date":"2026-09-21","decision_area":"data","glossary":"Target core\tThe new core banking platform that replaces both legacy cores\nMock\tA full rehearsal load of migrated data into the target core\nHypercare\tThe four weeks of extra support after go-live\nDecision record\tA short note of one architecture decision, its options and why it was chosen","version_history":"0.1\t2026-09-07\tPriya Naidoo\tOptions written up\n1.0\t2026-09-21\tPriya Naidoo\tDecision recorded","related_documents":"NRB-EA-05 – Data migration and quality enterprise architecture\nDelivery Overview – Northbridge Bank technology programme","decision_context":"The two legacy instances use different customer number formats that clash.","problem_statement":"What format do surviving customer numbers take in the target core?","decision_drivers":"No clash across instances\nChannels must accept the format\nOld numbers searchable","decision_constraints":"Card platform accepts up to 10 digits","options_considered":"New 8-digit numbers with old numbers as alternate keys – Clean and clash-free – Customers see a new number\nKeep instance 1 numbers, renumber instance 2 – Fewer changes for most customers – Two rules to explain\nPrefix legacy numbers – No renumbering – Breaks channel field lengths","decision_outcome":"Every surviving customer gets a new 8-digit number; legacy numbers are kept as alternate keys for search.","rationale":"Removes the clash once and keeps old numbers findable for branch and contact centre staff.","positive_consequences":"No clashes\nSearch by old number still works","negative_consequences":"Customer communication needed for changed numbers","follow_up_actions":"Agree the customer communication\nLoad alternate keys in Mock 2","related_decisions":"NRB-ADR-01 – Survivor rule for duplicate customers","risks_mitigations":"Decision not followed in build – Check at the design authority\nDecision overtaken by new facts – Review on 2027-03-31","roles_and_responsibilities":"Decision owner – Records and maintains the decision – Priya Naidoo\nDesign authority chair – Approves the decision – Ravi Pillai\nExecutive sponsor – Decides escalations – Grace Moyo"}$j$),
  ('00000000-0000-4000-a021-000000000004', '00000000-0000-4000-9003-00000000000b', '10-digit account numbers with a check digit', 'Decision record NRB-ADR-04. Owner: Catherine Mwangi.', 'draft', $j${"document_reference":"NRB-ADR-04","document_version":"1.0","document_owner":"Catherine Mwangi","next_review_date":"2027-03-31","decision_owner":"Catherine Mwangi","decision_date":"2026-09-28","decision_area":"data","glossary":"Target core\tThe new core banking platform that replaces both legacy cores\nMock\tA full rehearsal load of migrated data into the target core\nHypercare\tThe four weeks of extra support after go-live\nDecision record\tA short note of one architecture decision, its options and why it was chosen","version_history":"0.1\t2026-09-14\tCatherine Mwangi\tOptions written up\n1.0\t2026-09-28\tCatherine Mwangi\tDecision recorded","related_documents":"NRB-EA-05 – Data migration and quality enterprise architecture\nDelivery Overview – Northbridge Bank technology programme","decision_context":"Account numbers from the second instance clash with the first.","problem_statement":"What account number format does the target core use?","decision_drivers":"No clash across instances\nCatch keying errors at the branch\nPayments must route correctly","decision_constraints":"Scheme routing uses the existing sort codes","options_considered":"New 10-digit numbers with check digit – Catches errors; clash-free – Customers get new numbers\nKeep legacy numbers – No change for customers – Clashes remain\nKeep and pad instance 2 numbers – Fewer changes – No error detection","decision_outcome":"Accounts get 10-digit numbers with a check digit; instance 2 numbers are kept as alternate keys.","rationale":"One format for all accounts with error detection, and old numbers still route incoming payments during hypercare.","positive_consequences":"Keying errors caught\nNo clashes","negative_consequences":"Statement and card reissue for changed numbers","follow_up_actions":"Agree incoming-payment redirection for old numbers\nSample-check alternate keys","related_decisions":"NRB-ADR-03 – 8-digit customer number standard","risks_mitigations":"Decision not followed in build – Check at the design authority\nDecision overtaken by new facts – Review on 2027-03-31","roles_and_responsibilities":"Decision owner – Records and maintains the decision – Catherine Mwangi\nDesign authority chair – Approves the decision – Ravi Pillai\nExecutive sponsor – Decides escalations – Grace Moyo"}$j$),
  ('00000000-0000-4000-a021-000000000005', '00000000-0000-4000-9003-00000000000b', 'Recreate standing orders instead of replaying them', 'Decision record NRB-ADR-05. Owner: Ahmed Hassan.', 'draft', $j${"document_reference":"NRB-ADR-05","document_version":"1.0","document_owner":"Ahmed Hassan","next_review_date":"2027-03-31","decision_owner":"Ahmed Hassan","decision_date":"2026-10-12","decision_area":"application","glossary":"Target core\tThe new core banking platform that replaces both legacy cores\nMock\tA full rehearsal load of migrated data into the target core\nHypercare\tThe four weeks of extra support after go-live\nDecision record\tA short note of one architecture decision, its options and why it was chosen","version_history":"0.1\t2026-09-28\tAhmed Hassan\tOptions written up\n1.0\t2026-10-12\tAhmed Hassan\tDecision recorded","related_documents":"NRB-EA-05 – Data migration and quality enterprise architecture\nDelivery Overview – Northbridge Bank technology programme","decision_context":"1,180 standing orders exist in both instances; replaying history risks duplicates.","problem_statement":"How are active standing orders moved to the target core?","decision_drivers":"No duplicate payment on the cutover weekend\nEvery active standing order runs on its next date","decision_constraints":"Freeze starts the Friday before go-live","options_considered":"Recreate from the active list – Clean; no history to replay – History stays in the legacy archive\nReplay full history – Complete history in the target core – High duplicate risk\nCustomers re-enter them – No migration effort – Poor customer experience","decision_outcome":"Active standing orders are recreated from the frozen active list with their next payment date; history stays in the legacy archive for enquiry.","rationale":"Removes the duplicate risk and keeps the next payment on time.","positive_consequences":"No duplicate payments\nSimpler reconciliation","negative_consequences":"History enquiry needs the archive for 12 months","follow_up_actions":"Choose the survivor where both instances hold one\nReconcile counts in Mock 3","related_decisions":"NRB-ADR-01 – Survivor rule for duplicate customers","risks_mitigations":"Decision not followed in build – Check at the design authority\nDecision overtaken by new facts – Review on 2027-03-31","roles_and_responsibilities":"Decision owner – Records and maintains the decision – Ahmed Hassan\nDesign authority chair – Approves the decision – Ravi Pillai\nExecutive sponsor – Decides escalations – Grace Moyo"}$j$),
  ('00000000-0000-4000-a021-000000000006', '00000000-0000-4000-9003-00000000000b', 'Migrate expired limits that still secure a live contract', 'Decision record NRB-ADR-06. Owner: Joy Akinyi.', 'draft', $j${"document_reference":"NRB-ADR-06","document_version":"1.0","document_owner":"Joy Akinyi","next_review_date":"2027-03-31","decision_owner":"Joy Akinyi","decision_date":"2026-11-02","decision_area":"application","glossary":"Target core\tThe new core banking platform that replaces both legacy cores\nMock\tA full rehearsal load of migrated data into the target core\nHypercare\tThe four weeks of extra support after go-live\nDecision record\tA short note of one architecture decision, its options and why it was chosen","version_history":"0.1\t2026-10-19\tJoy Akinyi\tOptions written up\n1.0\t2026-11-02\tJoy Akinyi\tDecision recorded","related_documents":"NRB-EA-05 – Data migration and quality enterprise architecture\nDelivery Overview – Northbridge Bank technology programme","decision_context":"2,180 expired limits are still linked to live contracts.","problem_statement":"Do expired limits move to the target core, and in what state?","decision_drivers":"No contract left unsecured\nCredit must review each one","decision_constraints":"Target core rejects a loan without a limit","options_considered":"Migrate as expired and flag for review – Contracts stay secured – Review backlog after go-live\nRenew all before the freeze – Clean data at go-live – Credit cannot review 2,180 in time\nDrop expired limits – Simple – Loans rejected at load","decision_outcome":"Expired limits linked to a live contract migrate in an expired state and land on a credit review queue.","rationale":"Keeps every contract secured and loadable while giving credit a controlled review queue.","positive_consequences":"Every loan loads\nCredit keeps control","negative_consequences":"Review queue to clear in the first quarter","follow_up_actions":"Sign the expired-limit rule\nSize the review queue for credit","risks_mitigations":"Decision not followed in build – Check at the design authority\nDecision overtaken by new facts – Review on 2027-03-31","roles_and_responsibilities":"Decision owner – Records and maintains the decision – Joy Akinyi\nDesign authority chair – Approves the decision – Ravi Pillai\nExecutive sponsor – Decides escalations – Grace Moyo"}$j$),
  ('00000000-0000-4000-a021-000000000007', '00000000-0000-4000-9003-00000000000b', 'Three mock migrations and one dress rehearsal', 'Decision record NRB-ADR-07. Owner: Priya Naidoo.', 'draft', $j${"document_reference":"NRB-ADR-07","document_version":"1.0","document_owner":"Priya Naidoo","next_review_date":"2027-03-31","decision_owner":"Priya Naidoo","decision_date":"2026-08-31","decision_area":"process","glossary":"Target core\tThe new core banking platform that replaces both legacy cores\nMock\tA full rehearsal load of migrated data into the target core\nHypercare\tThe four weeks of extra support after go-live\nDecision record\tA short note of one architecture decision, its options and why it was chosen","version_history":"0.1\t2026-08-17\tPriya Naidoo\tOptions written up\n1.0\t2026-08-31\tPriya Naidoo\tDecision recorded","related_documents":"NRB-EA-05 – Data migration and quality enterprise architecture\nDelivery Overview – Northbridge Bank technology programme","decision_context":"Mock 1 overran by 9 hours and take-over accounts did not reach zero.","problem_statement":"How many full rehearsals are needed before go-live?","decision_drivers":"Load fits inside the window\nReconciliation reaches zero\nRollback rehearsed","decision_constraints":"Go-live weekend 10–12 April 2027","options_considered":"Three mocks plus a dress rehearsal – Time to fix and prove – More environment cost\nTwo mocks plus a dress rehearsal – Cheaper – No buffer after Mock 1 overran\nDress rehearsal only – Cheapest – High go-live risk","decision_outcome":"Run Mock 2 (static data), Mock 3 (financial data) and a full dress rehearsal before go-live.","rationale":"Mock 1 showed the window and reconciliation risks are real; two more mocks give time to fix and prove both.","positive_consequences":"Window and reconciliation proven before go-live","negative_consequences":"Environment booked for longer","follow_up_actions":"Book the dress rehearsal environment\nAdd mapping sign-off to the Mock 2 entry criteria","related_decisions":"NRB-ADR-08 – Masked production-like data in lower environments","risks_mitigations":"Decision not followed in build – Check at the design authority\nDecision overtaken by new facts – Review on 2027-03-31","roles_and_responsibilities":"Decision owner – Records and maintains the decision – Priya Naidoo\nDesign authority chair – Approves the decision – Ravi Pillai\nExecutive sponsor – Decides escalations – Grace Moyo"}$j$),
  ('00000000-0000-4000-a021-000000000008', '00000000-0000-4000-9003-00000000000b', 'Masked production-like data in lower environments', 'Decision record NRB-ADR-08. Owner: Ravi Pillai.', 'draft', $j${"document_reference":"NRB-ADR-08","document_version":"1.0","document_owner":"Ravi Pillai","next_review_date":"2027-03-31","decision_owner":"Ravi Pillai","decision_date":"2026-10-05","decision_area":"security","glossary":"Target core\tThe new core banking platform that replaces both legacy cores\nMock\tA full rehearsal load of migrated data into the target core\nHypercare\tThe four weeks of extra support after go-live\nDecision record\tA short note of one architecture decision, its options and why it was chosen","version_history":"0.1\t2026-09-21\tRavi Pillai\tOptions written up\n1.0\t2026-10-05\tRavi Pillai\tDecision recorded","related_documents":"NRB-EA-05 – Data migration and quality enterprise architecture\nDelivery Overview – Northbridge Bank technology programme","decision_context":"Refreshes are still a manual copy and a shared workbook held a customer sample longer than agreed.","problem_statement":"What data may lower environments hold?","decision_drivers":"No personal data outside production\nRealistic volumes for testing","decision_constraints":"Masking must keep referential integrity","options_considered":"Masked production-like refresh – Realistic and safe – Masking tool to run\nSynthetic data only – Safest – Misses real data problems\nUnmasked copies with access control – Fast – Breaks data protection rules","decision_outcome":"Lower environments get masked production-like data only; refreshes are requested and logged.","rationale":"Testing needs real data shapes; masking keeps personal data out of non-production.","positive_consequences":"Realistic testing\nNo personal data in test","negative_consequences":"Refresh takes longer","follow_up_actions":"Approve the masking rules\nRetire the manual copy","risks_mitigations":"Decision not followed in build – Check at the design authority\nDecision overtaken by new facts – Review on 2027-03-31","roles_and_responsibilities":"Decision owner – Records and maintains the decision – Ravi Pillai\nDesign authority chair – Approves the decision – Ravi Pillai\nExecutive sponsor – Decides escalations – Grace Moyo"}$j$),
  ('00000000-0000-4000-a021-000000000009', '00000000-0000-4000-9003-00000000000b', 'One dashboard for every interface', 'Decision record NRB-ADR-09. Owner: Brian Otieno.', 'draft', $j${"document_reference":"NRB-ADR-09","document_version":"1.0","document_owner":"Brian Otieno","next_review_date":"2027-03-31","decision_owner":"Brian Otieno","decision_date":"2026-10-14","decision_area":"integration","glossary":"Target core\tThe new core banking platform that replaces both legacy cores\nMock\tA full rehearsal load of migrated data into the target core\nHypercare\tThe four weeks of extra support after go-live\nDecision record\tA short note of one architecture decision, its options and why it was chosen","version_history":"0.1\t2026-09-30\tBrian Otieno\tOptions written up\n1.0\t2026-10-14\tBrian Otieno\tDecision recorded","related_documents":"NRB-EA-05 – Data migration and quality enterprise architecture\nDelivery Overview – Northbridge Bank technology programme","decision_context":"The dashboard shows four of twelve interfaces and replay has not been tested.","problem_statement":"How are interface failures seen and repaired?","decision_drivers":"No silent message loss\nRepair under 30 minutes","decision_constraints":"Each interface keeps its owner","options_considered":"Integration platform dashboard for all interfaces – One place to look – Every interface must report\nPer-team monitoring – Teams keep their tools – Failures missed between teams\nLog search only – No build – Slow to spot failures","decision_outcome":"All twelve interfaces report to the integration platform dashboard; failures alert the interface owner within five minutes.","rationale":"Silent loss is the biggest integration risk at go-live; one view makes it visible.","positive_consequences":"Failures visible at once","negative_consequences":"Every interface needs a monitoring hook","follow_up_actions":"Add the remaining eight interfaces\nRun the replay test before SIT exit","related_decisions":"NRB-ADR-02 – Store mandate and signature images in a file store","risks_mitigations":"Decision not followed in build – Check at the design authority\nDecision overtaken by new facts – Review on 2027-03-31","roles_and_responsibilities":"Decision owner – Records and maintains the decision – Brian Otieno\nDesign authority chair – Approves the decision – Ravi Pillai\nExecutive sponsor – Decides escalations – Grace Moyo"}$j$),
  ('00000000-0000-4000-a021-000000000010', '00000000-0000-4000-9003-00000000000b', 'Store mandate images in the core database', 'Superseded by NRB-ADR-02. Early design kept every customer artefact in the target core database.', 'superseded', $j${"document_reference":"NRB-ADR-10","document_version":"1.0","document_owner":"Ravi Pillai","next_review_date":"2027-03-31","decision_owner":"Ravi Pillai","decision_date":"2026-07-20","decision_area":"infrastructure","glossary":"Target core\tThe new core banking platform that replaces both legacy cores\nMock\tA full rehearsal load of migrated data into the target core\nHypercare\tThe four weeks of extra support after go-live\nDecision record\tA short note of one architecture decision, its options and why it was chosen","version_history":"0.1\t2026-07-06\tRavi Pillai\tOptions written up\n1.0\t2026-07-20\tRavi Pillai\tDecision recorded","related_documents":"NRB-EA-05 – Data migration and quality enterprise architecture\nDelivery Overview – Northbridge Bank technology programme","decision_context":"Early design kept every customer artefact in the target core database.","problem_statement":"Where do mandate and signature images live after migration?","decision_drivers":"One place for customer data","decision_constraints":"Static load must fit inside the window","options_considered":"Core database – One place for all data – Slows the load and backups\nObject store – Fast load – Extra API","decision_outcome":"Images were to be stored in the core database.","rationale":"Chosen for simplicity before image volumes were measured.","positive_consequences":"Single store","negative_consequences":"Image volume threatened the load window","follow_up_actions":"Superseded by NRB-ADR-02 after Mock 1 volumes were measured","related_decisions":"NRB-ADR-02 – Store mandate and signature images in a file store","risks_mitigations":"Decision not followed in build – Check at the design authority\nDecision overtaken by new facts – Review on 2027-03-31","roles_and_responsibilities":"Decision owner – Records and maintains the decision – Ravi Pillai\nDesign authority chair – Approves the decision – Ravi Pillai\nExecutive sponsor – Decides escalations – Grace Moyo"}$j$),
  ('00000000-0000-4000-a022-000000000001', '00000000-0000-4000-9003-00000000000c', 'Enterprise architecture baseline review', 'Held 9 March 2026 by the design authority. Baseline of both legacy cores and the target capability map accepted with three actions. Chair: Ravi Pillai.', 'complete', $j${}$j$),
  ('00000000-0000-4000-a022-000000000002', '00000000-0000-4000-9003-00000000000c', 'Target platform solution design review', 'Held 13 April 2026. Solution architecture for the target core accepted; non-functional targets confirmed for payments and channels. Chair: Ravi Pillai.', 'complete', $j${}$j$),
  ('00000000-0000-4000-a022-000000000003', '00000000-0000-4000-9003-00000000000c', 'Customer and channels design review', 'Held 18 May 2026. Customer master and channel access design accepted subject to the survivor rule decision. Presenter: Amina Diallo.', 'complete', $j${}$j$),
  ('00000000-0000-4000-a022-000000000004', '00000000-0000-4000-9003-00000000000c', 'Integration design authority review', 'Held 22 June 2026. Twelve in-scope interfaces reviewed; card status and trial-balance test slots raised as actions. Presenter: Brian Otieno.', 'complete', $j${}$j$),
  ('00000000-0000-4000-a022-000000000005', '00000000-0000-4000-9003-00000000000c', 'Environments and release architecture review', 'Held 20 July 2026. Environment path accepted; masked data refresh and recovery restore raised as conditions. Presenter: Ravi Pillai.', 'complete', $j${}$j$),
  ('00000000-0000-4000-a022-000000000006', '00000000-0000-4000-9003-00000000000c', 'Data migration architecture review after Mock 1', 'Held 12 October 2026. Mock 1 overrun and take-over balances reviewed; three mocks plus a dress rehearsal confirmed. Presenter: Priya Naidoo.', 'complete', $j${}$j$),
  ('00000000-0000-4000-a022-000000000007', '00000000-0000-4000-9003-00000000000c', 'Lending and collateral design review', 'Planned for 11 November 2026. Expired-limit rule and collateral load order to be reviewed before Mock 2. Presenter: Joy Akinyi.', 'scheduled', $j${}$j$),
  ('00000000-0000-4000-a022-000000000008', '00000000-0000-4000-9003-00000000000c', 'Security architecture review – access recertification', 'Planned for 24 November 2026. Restart criteria for the security workstream and the recertification approach. Presenter: Nadia Rahman.', 'scheduled', $j${}$j$),
  ('00000000-0000-4000-a022-000000000009', '00000000-0000-4000-9003-00000000000c', 'Dress rehearsal readiness architecture review', 'Planned for 22 February 2027. Environment, rollback steps and interface readiness checked before the dress rehearsal. Chair: Ravi Pillai.', 'scheduled', $j${}$j$),
  ('00000000-0000-4000-a022-000000000010', '00000000-0000-4000-9003-00000000000c', 'Go-live architecture sign-off review', 'Planned for 29 March 2027. Final architecture sign-off before the 10–12 April 2027 cutover. Chair: Grace Moyo.', 'scheduled', $j${}$j$)
) AS v(id, register_id, title, description, status, field_values)
CROSS JOIN proj p
ON CONFLICT (id) DO NOTHING;

DO $$
DECLARE
  v_project UUID;
  v_block TEXT;
  v_count INT;
BEGIN
  SELECT id INTO v_project FROM public.projects WHERE project_code = 'SEED334-PRJ-08' LIMIT 1;
  IF v_project IS NULL THEN
    RAISE NOTICE 'v1374: project SEED334-PRJ-08 not found — no seed rows inserted';
    RETURN;
  END IF;
  FOREACH v_block IN ARRAY ARRAY['a01b', 'a01c', 'a01d', 'a01e', 'a01f', 'a020', 'a021', 'a022'] LOOP
    SELECT COUNT(*) INTO v_count FROM public.local_register_records
      WHERE id::text LIKE '00000000-0000-4000-' || v_block || '-%' AND record_project_id = v_project AND is_deleted = FALSE;
    RAISE NOTICE 'v1374: block % has % records (expected 10)', v_block, v_count;
  END LOOP;
END $$;
